'use client';

import { useApp } from '@/contexts/AppContext';
import { useAuth } from '@/contexts/AuthContext';
import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';

export default function AuditPage() {
  const { state } = useApp();
  const { user } = useAuth();
  const router = useRouter();
  const [mounted, setMounted] = useState(false);
  const [toast, setToast] = useState('');
  const [activeTab, setActiveTab] = useState<'users' | 'campaigns' | 'time_entries'>('users');
  const [campaigns, setCampaigns] = useState<any[]>([]);
  const [timeEntries, setTimeEntries] = useState<any[]>([]);
  const [users, setUsers] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchData = async () => {
    setLoading(true);
    try {
      const token = localStorage.getItem('invictus_jwt');
      const headers = { 'Authorization': `Bearer ${token}` };

      const [campRes, teRes, usersRes] = await Promise.all([
        fetch('http://localhost:4000/api/campaigns', { headers }),
        fetch('http://localhost:4000/api/time-logs', { headers }),
        fetch('http://localhost:4000/api/users', { headers })
      ]);

      if (campRes.ok) setCampaigns(await campRes.json());
      if (teRes.ok) setTimeEntries(await teRes.json());
      if (usersRes.ok) setUsers(await usersRes.json());
    } catch (e) {
      console.error('Error fetching audit data', e);
    }
    setLoading(false);
  };

  useEffect(() => {
    setMounted(true);
    fetchData();
  }, []);

  if (!mounted || !user) {
    return <div className="p-8 text-[var(--c-text-2)]">Loading audit view...</div>;
  }

  if (user.role !== 'admin' && user.role !== 'ceo') {
    return (
      <div className="p-8 text-center text-[var(--c-error)] font-bold">
        UNAUTHORIZED: Admin or CEO access required.
      </div>
    );
  }

  const handleSync = () => {
    setToast('Data sync initiated. Pulling latest from database...');
    fetchData().then(() => {
      setToast('Sync complete! All caches cleared.');
      setTimeout(() => setToast(''), 3000);
    });
  };



  return (
    <div className="p-8 max-w-6xl mx-auto flex flex-col gap-6 min-h-[calc(100vh-4rem)]">
      <div className="flex items-center justify-between mb-2">
        <div>
          <h1 className="text-3xl font-bold text-[var(--c-text)] font-syne flex items-center gap-2">
            <span className="material-symbols-outlined text-[var(--c-error)] text-3xl">admin_panel_settings</span>
            Financial & System Audit
          </h1>
          <p className="text-[var(--c-text-2)] mt-1 text-sm font-grotesk">Raw database views and system controls. Confidential.</p>
        </div>
        <button 
          onClick={handleSync}
          className="bg-[var(--c-surface-2)] text-[var(--c-text)] border border-[var(--c-border)] px-4 py-2 rounded-lg font-bold text-sm hover:bg-[var(--c-hover)] transition-colors flex items-center gap-2"
        >
          <span className="material-symbols-outlined text-[18px]">sync</span>
          Sync Data & Clear Cache
        </button>
      </div>

      {toast && (
        <div className="bg-[var(--c-primary)]/10 border border-[var(--c-primary)] text-[var(--c-primary)] px-4 py-3 rounded-lg font-bold text-sm animate-pulse">
          {toast}
        </div>
      )}

      {/* Tabs */}
      <div className="flex gap-2 border-b border-[var(--c-border)] mb-4 pb-2">
        {(['users', 'campaigns', 'time_entries'] as const).map(tab => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`px-4 py-2 rounded-t-lg font-bold text-sm capitalize ${activeTab === tab ? 'bg-[var(--c-surface)] text-[var(--c-primary)] border-t border-l border-r border-[var(--c-border)] -mb-[9px] relative z-10' : 'text-[var(--c-text-2)] hover:text-[var(--c-text)]'}`}
          >
            {tab.replace('_', ' ')}
          </button>
        ))}
      </div>

      <div className="bg-[var(--c-surface)] rounded-b-xl rounded-tr-xl border border-[var(--c-border)] p-1 overflow-x-auto shadow-sm">
        <table className="w-full text-left border-collapse text-sm">
          <thead>
            <tr className="bg-[var(--c-surface-2)] border-b border-[var(--c-border)]">
              {activeTab === 'users' && (
                <>
                  <th className="p-3 font-bold text-[var(--c-text-3)] uppercase tracking-wider text-xs">ID</th>
                  <th className="p-3 font-bold text-[var(--c-text-3)] uppercase tracking-wider text-xs">Name</th>
                  <th className="p-3 font-bold text-[var(--c-text-3)] uppercase tracking-wider text-xs">Email</th>
                  <th className="p-3 font-bold text-[var(--c-text-3)] uppercase tracking-wider text-xs">Role</th>
                  <th className="p-3 font-bold text-[var(--c-text-3)] uppercase tracking-wider text-xs">Created At</th>
                </>
              )}
              {activeTab === 'campaigns' && (
                <>
                  <th className="p-3 font-bold text-[var(--c-text-3)] uppercase tracking-wider text-xs">ID</th>
                  <th className="p-3 font-bold text-[var(--c-text-3)] uppercase tracking-wider text-xs">Client ID</th>
                  <th className="p-3 font-bold text-[var(--c-text-3)] uppercase tracking-wider text-xs">Name</th>
                  <th className="p-3 font-bold text-[var(--c-text-3)] uppercase tracking-wider text-xs">Status</th>
                  <th className="p-3 font-bold text-[var(--c-text-3)] uppercase tracking-wider text-xs">Spend (INR)</th>
                  <th className="p-3 font-bold text-[var(--c-text-3)] uppercase tracking-wider text-xs">Leads</th>
                </>
              )}
              {activeTab === 'time_entries' && (
                <>
                  <th className="p-3 font-bold text-[var(--c-text-3)] uppercase tracking-wider text-xs">ID</th>
                  <th className="p-3 font-bold text-[var(--c-text-3)] uppercase tracking-wider text-xs">User ID</th>
                  <th className="p-3 font-bold text-[var(--c-text-3)] uppercase tracking-wider text-xs">Task ID</th>
                  <th className="p-3 font-bold text-[var(--c-text-3)] uppercase tracking-wider text-xs">Duration (Min)</th>
                  <th className="p-3 font-bold text-[var(--c-text-3)] uppercase tracking-wider text-xs">Logged At</th>
                </>
              )}
            </tr>
          </thead>
          <tbody>
            {activeTab === 'users' && users.map(u => (
              <tr key={u.id} className="border-b border-[var(--c-border)] last:border-0 hover:bg-[var(--c-surface-2)]">
                <td className="p-3 font-mono text-xs text-[var(--c-text-3)]">{u.id}</td>
                <td className="p-3 font-bold text-[var(--c-text)]">{u.name}</td>
                <td className="p-3 text-[var(--c-text-2)]">{u.email}</td>
                <td className="p-3 text-[var(--c-text-2)]">{u.role}</td>
                <td className="p-3 text-[var(--c-text-3)]">{new Date(u.created_at || Date.now()).toLocaleDateString()}</td>
              </tr>
            ))}
            {activeTab === 'campaigns' && campaigns.map(c => (
              <tr key={c.id} className="border-b border-[var(--c-border)] last:border-0 hover:bg-[var(--c-surface-2)]">
                <td className="p-3 font-mono text-xs text-[var(--c-text-3)]">{c.id}</td>
                <td className="p-3 font-mono text-[var(--c-text-2)]">{c.client_id}</td>
                <td className="p-3 font-bold text-[var(--c-text)]">{c.campaign_name}</td>
                <td className="p-3">
                  <span className={`text-xs px-2 py-0.5 rounded font-bold ${c.status === 'running' ? 'bg-[var(--c-primary)]/10 text-[var(--c-primary)]' : 'bg-[var(--c-surface-3)] text-[var(--c-text-2)]'}`}>{c.status}</span>
                </td>
                <td className="p-3 font-mono text-[var(--c-text)]">{c.spend_inr ? c.spend_inr.toLocaleString() : '0'}</td>
                <td className="p-3 text-[var(--c-primary)] font-bold">{c.leads || 0}</td>
              </tr>
            ))}
            {activeTab === 'time_entries' && timeEntries.map(t => (
              <tr key={t.id} className="border-b border-[var(--c-border)] last:border-0 hover:bg-[var(--c-surface-2)]">
                <td className="p-3 font-mono text-xs text-[var(--c-text-3)]">{t.id}</td>
                <td className="p-3 font-mono text-[var(--c-text-2)]">{t.user_id}</td>
                <td className="p-3 font-mono text-[var(--c-text-2)]">{t.task_id}</td>
                <td className="p-3 font-bold text-[var(--c-text)]">{t.duration_minutes}</td>
                <td className="p-3 text-[var(--c-text-3)]">{new Date(t.started_at).toLocaleString()}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { useApp } from '@/contexts/AppContext';
import { useRouter } from 'next/navigation';
import { fetchGoogleCalendarEvents, GoogleEvent } from '@/lib/googleCalendar';
import { ChevronLeft, ChevronRight, Calendar as CalendarIcon, Video, AlignLeft, Sparkles, X, Link as LinkIcon } from 'lucide-react';
import { Task } from '@/lib/data';

type ViewMode = 'day' | 'week' | 'month' | 'year';

export default function CalendarPage() {
  const { state, dispatch } = useApp();
  const router = useRouter();
  const [view, setView] = useState<ViewMode>('week');
  const [currentDate, setCurrentDate] = useState(new Date());

  const [selectedEvent, setSelectedEvent] = useState<GoogleEvent | null>(null);
  const [isPrepPanelOpen, setIsPrepPanelOpen] = useState(false);

  const [loading, setLoading] = useState(true);

  // Auto scroll to current time in day/week views
  const timeGridRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if ((view === 'day' || view === 'week') && timeGridRef.current) {
      const now = new Date();
      const scrollPosition = (now.getHours() - 1) * 60; // 1 hour before now
      timeGridRef.current.scrollTop = scrollPosition;
    }
  }, [view]);

  // Fetch google events
  useEffect(() => {
    async function loadEvents() {
      setLoading(true);
      const minDate = new Date(currentDate);
      minDate.setDate(1);
      minDate.setMonth(minDate.getMonth() - 1); // Fetch +/- 1 month
      const maxDate = new Date(currentDate);
      maxDate.setDate(28);
      maxDate.setMonth(maxDate.getMonth() + 2);

      const events = await fetchGoogleCalendarEvents(
        state.googleAccessToken || 'mock_token',
        minDate.toISOString(), 
        maxDate.toISOString()
      );
      (dispatch as any)({ type: 'SET_GOOGLE_EVENTS', payload: events });
      setLoading(false);
    }
    loadEvents();
  }, [currentDate, state.googleAccessToken, dispatch]);

  const tasksWithDeadlines = useMemo(() => {
    return state.tasks.filter(t => t.deadline && t.status !== 'done' && t.status !== 'cancelled');
  }, [state.tasks]);

  const handlePrev = () => {
    const next = new Date(currentDate);
    if (view === 'day') next.setDate(next.getDate() - 1);
    else if (view === 'week') next.setDate(next.getDate() - 7);
    else next.setMonth(next.getMonth() - 1);
    setCurrentDate(next);
  };

  const handleNext = () => {
    const next = new Date(currentDate);
    if (view === 'day') next.setDate(next.getDate() + 1);
    else if (view === 'week') next.setDate(next.getDate() + 7);
    else next.setMonth(next.getMonth() + 1);
    setCurrentDate(next);
  };

  const handleToday = () => {
    setCurrentDate(new Date());
  };

  const openEventPrep = (e: React.MouseEvent, evt: GoogleEvent) => {
    e.stopPropagation();
    setSelectedEvent(evt);
    setIsPrepPanelOpen(true);
  };

  // Helpers for grid
  const getDaysInView = () => {
    if (view === 'day') return [currentDate];
    if (view === 'week') {
      const start = new Date(currentDate);
      const day = start.getDay();
      const diff = start.getDate() - day + (day === 0 ? -6 : 1); // Adjust when day is sunday
      start.setDate(diff);
      const days = [];
      for (let i = 0; i < 7; i++) {
        const d = new Date(start);
        d.setDate(d.getDate() + i);
        days.push(d);
      }
      return days;
    }
    // Month view days
    const start = new Date(currentDate.getFullYear(), currentDate.getMonth(), 1);
    const day = start.getDay();
    const diff = start.getDate() - day + (day === 0 ? -6 : 1);
    start.setDate(diff);
    const days = [];
    for (let i = 0; i < 42; i++) {
      const d = new Date(start);
      d.setDate(d.getDate() + i);
      days.push(d);
    }
    return days;
  };

  const daysInView = getDaysInView();
  const isToday = (d: Date) => {
    const today = new Date();
    return d.getDate() === today.getDate() && d.getMonth() === today.getMonth() && d.getFullYear() === today.getFullYear();
  };

  return (
    <div className="flex flex-col h-full bg-app-bg overflow-hidden relative">
      {/* Header */}
      <div className="flex-shrink-0 px-6 py-4 border-b border-app-border flex items-center justify-between">
        <div className="flex items-center gap-4">
          <h1 className="text-2xl font-bold font-syne text-app-text tracking-tight">Calendar</h1>
          <div className="flex items-center bg-app-surface2 border border-app-border rounded-lg p-1">
            <button onClick={handlePrev} className="p-1 hover:bg-app-surface rounded text-app-text2 hover:text-app-text"><ChevronLeft className="w-5 h-5" /></button>
            <button onClick={handleToday} className="px-3 py-1 text-sm font-medium hover:bg-app-surface rounded text-app-text2 hover:text-app-text">Today</button>
            <button onClick={handleNext} className="p-1 hover:bg-app-surface rounded text-app-text2 hover:text-app-text"><ChevronRight className="w-5 h-5" /></button>
          </div>
          <span className="text-lg font-medium text-app-text font-grotesk ml-2">
            {currentDate.toLocaleDateString('default', { month: 'long', year: 'numeric' })}
          </span>
        </div>

        <div className="flex items-center gap-3">
          <div className="flex bg-app-surface border border-app-border rounded-lg p-1">
            {(['day', 'week', 'month', 'year'] as ViewMode[]).map(m => (
              <button
                key={m}
                onClick={() => setView(m)}
                className={`px-4 py-1.5 rounded-md text-sm font-medium capitalize transition ${
                  view === m ? 'bg-app-surface2 text-app-text shadow-sm' : 'text-app-text3 hover:text-app-text2'
                }`}
              >
                {m}
              </button>
            ))}
          </div>
          <button className="btn-primary" onClick={() => !state.isGoogleConnected && alert('Please integrate Google Calendar first')} disabled={loading}>
            <Sparkles className="w-4 h-4 mr-2" />
            {state.isGoogleConnected ? 'Sync Now' : 'Connect Google'}
          </button>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="flex-1 overflow-hidden flex relative">

        {/* Calendar Grid */}
        <div className="flex-1 flex flex-col h-full overflow-hidden">

          {/* Day / Week Header */}
          {(view === 'day' || view === 'week') && (
            <div className="flex border-b border-app-border flex-shrink-0" style={{ paddingLeft: '60px' }}>
              {daysInView.map((d, i) => (
                <div key={i} className="flex-1 py-3 text-center border-l border-app-border border-opacity-30">
                  <p className="text-xs font-semibold text-app-text3 uppercase mb-1">{d.toLocaleDateString('default', { weekday: 'short' })}</p>
                  <p className={`text-xl font-bold font-syne ${isToday(d) ? 'text-primary bg-primary/10 w-8 h-8 rounded-full flex items-center justify-center mx-auto' : 'text-app-text'}`}>
                    {d.getDate()}
                  </p>
                </div>
              ))}
            </div>
          )}

          {/* Month Header */}
          {view === 'month' && (
            <div className="flex border-b border-app-border flex-shrink-0 bg-app-surface2">
              {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map(day => (
                <div key={day} className="flex-1 py-2 text-center text-xs font-semibold text-app-text3 uppercase">{day}</div>
              ))}
            </div>
          )}

          {/* Time Grid (Day/Week) */}
          {(view === 'day' || view === 'week') && (
            <div className="flex-1 overflow-y-auto relative bg-app-bg" ref={timeGridRef}>

              {/* NOW Line Indicator */}
              <div 
                className="absolute left-[60px] right-0 z-20 pointer-events-none flex items-center" 
                style={{ 
                  top: `${new Date().getHours() * 60 + new Date().getMinutes()}px`,
                }}
              >
                <div className="w-2 h-2 rounded-full bg-red-500 -ml-1"></div>
                <div className="h-[2px] bg-red-500 opacity-70 w-full shadow-[0_0_8px_rgba(239,68,68,0.6)]"></div>
              </div>

              {/* Grid Lines */}
              <div className="relative h-[1440px]">
                {Array.from({ length: 24 }).map((_, i) => (
                  <div key={i} className="absolute w-full flex" style={{ top: `${i * 60}px` }}>
                    <div className="w-[60px] flex-shrink-0 text-right pr-3 -mt-2">
                      <span className="text-[10px] font-medium text-app-text3">{i === 0 ? '12 AM' : i < 12 ? `${i} AM` : i === 12 ? '12 PM' : `${i - 12} PM`}</span>
                    </div>
                    <div className="flex-1 border-t border-app-border border-opacity-30"></div>
                  </div>
                ))}

                {/* Events & Task Deadlines Overlay */}
                <div className="absolute top-0 left-[60px] right-0 bottom-0 flex">
                  {daysInView.map((d, i) => {
                    const dayEvents = state.googleEvents.filter(e => {
                      const estart = new Date(e.start.dateTime);
                      return estart.getDate() === d.getDate() && estart.getMonth() === d.getMonth();
                    });

                    const dayTasks = tasksWithDeadlines.filter(t => {
                      const tdeadline = new Date(t.deadline!);
                      return tdeadline.getDate() === d.getDate() && tdeadline.getMonth() === d.getMonth();
                    });

                    return (
                      <div key={i} className="flex-1 border-l border-app-border border-opacity-30 relative px-1">

                        {/* Render Google Events */}
                        {dayEvents.map(evt => {
                          const start = new Date(evt.start.dateTime);
                          const end = new Date(evt.end.dateTime);
                          const top = start.getHours() * 60 + start.getMinutes();
                          const height = Math.max(20, (end.getTime() - start.getTime()) / 60000);

                          return (
                            <div 
                              key={evt.id}
                              onClick={(e) => openEventPrep(e, evt)}
                              className="absolute left-1 right-1 rounded-md p-2 cursor-pointer shadow-sm border overflow-hidden group hover:z-30 transition-all"
                              style={{ 
                                top: `${top}px`, 
                                height: `${height}px`,
                                background: 'rgba(66, 133, 244, 0.15)',
                                borderColor: 'rgba(66, 133, 244, 0.3)',
                                zIndex: 10
                              }}
                            >
                              <div className="absolute left-0 top-0 bottom-0 w-1 bg-[#4285F4]"></div>
                              <div className="flex items-center gap-1">
                                <p className="text-xs font-bold text-[#4285F4] truncate flex-1">{evt.summary}</p>
                                {state.meetingNotes && state.meetingNotes.some((n: any) => n.googleEventId === evt.id) && (
                                  <button
                                    onClick={(e) => { e.stopPropagation(); router.push(`/ai?tab=meeting&prefill=${evt.id}`); }}
                                    className="flex-shrink-0 text-[9px] font-black px-1 py-0.5 rounded"
                                    style={{ background: 'rgba(124,58,237,0.2)', color: '#7C3AED' }}
                                    title="View AI meeting notes"
                                  >
                                    🤖
                                  </button>
                                )}
                              </div>
                              <p className="text-[10px] text-app-text3 truncate opacity-80">
                                {start.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})} - {end.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                              </p>
                            </div>
                          );
                        })}

                        {/* Render Task Deadlines (Diamonds/Lines) */}
                        {dayTasks.map(task => {
                          const deadline = new Date(task.deadline!);
                          const top = deadline.getHours() * 60 + deadline.getMinutes();
                          return (
                            <div 
                              key={`task-${task.id}`}
                              className="absolute left-0 right-0 h-[2px] bg-[#EF4444] opacity-50 z-20 flex items-center justify-center cursor-pointer group"
                              style={{ top: `${top}px` }}
                              title={`Deadline: ${task.title}`}
                            >
                              <div className="w-3 h-3 bg-[#EF4444] rotate-45 transform border-2 border-app-bg shadow-sm"></div>
                              <div className="absolute left-full ml-2 w-max bg-app-surface border border-app-border rounded px-2 py-1 text-[10px] font-bold shadow-lg opacity-0 group-hover:opacity-100 pointer-events-none text-app-text transition-opacity z-50">
                                🎯 Due: {task.title}
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    );
                  })}
                </div>
              </div>
            </div>
          )}

          {/* Month Grid */}
          {view === 'month' && (
            <div className="flex-1 grid grid-cols-7 grid-rows-6 border-l border-t border-app-border overflow-y-auto">
              {daysInView.map((d, i) => {
                const dayEvents = state.googleEvents.filter((e: any) => {
                  const estart = new Date(e.start.dateTime);
                  return estart.getDate() === d.getDate() && estart.getMonth() === d.getMonth() && estart.getFullYear() === d.getFullYear();
                });
                const dayTasks = tasksWithDeadlines.filter(t => {
                  const tdeadline = new Date(t.deadline!);
                  return tdeadline.getDate() === d.getDate() && tdeadline.getMonth() === d.getMonth() && tdeadline.getFullYear() === d.getFullYear();
                });

                const isCurrentMonth = d.getMonth() === currentDate.getMonth();

                return (
                  <div key={i} className={`border-r border-b border-app-border p-2 min-h-[120px] overflow-hidden hover:overflow-y-auto custom-scrollbar flex flex-col ${isCurrentMonth ? 'bg-app-bg' : 'bg-app-surface2 opacity-50'}`}>
                    <div className="flex justify-between items-start mb-2 shrink-0">
                      <span className={`text-sm font-bold font-syne w-7 h-7 flex items-center justify-center rounded-full ${isToday(d) ? 'bg-primary text-white' : 'text-app-text2'}`}>
                        {d.getDate()}
                      </span>
                    </div>

                    <div className="space-y-1 flex-1">
                      {dayEvents.map(evt => (
                        <div key={evt.id} onClick={(e) => openEventPrep(e, evt)} className="px-1.5 py-0.5 rounded text-[10px] font-bold truncate cursor-pointer hover:opacity-80" style={{ background: 'rgba(66, 133, 244, 0.15)', color: '#4285F4' }}>
                          {evt.summary}
                        </div>
                      ))}
                      {dayTasks.map(task => (
                        <div key={task.id} className="px-1.5 py-0.5 rounded text-[10px] font-bold truncate hover:opacity-80 flex items-center gap-1" style={{ background: 'rgba(239, 68, 68, 0.1)', color: '#EF4444' }}>
                          <span className="w-1.5 h-1.5 bg-red-500 rounded-full shrink-0"></span> {task.title}
                        </div>
                      ))}
                    </div>
                  </div>
                );
              })}
            </div>
          )}

          {/* Year Grid */}
          {view === 'year' && (
            <div className="flex-1 overflow-y-auto p-6 bg-app-bg custom-scrollbar">
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6 max-w-7xl mx-auto">
                {Array.from({ length: 12 }).map((_, monthIndex) => {
                  const date = new Date(currentDate.getFullYear(), monthIndex, 1);
                  const monthName = date.toLocaleDateString('default', { month: 'long' });

                  // Calculate days for this month's mini grid
                  const start = new Date(date);
                  const day = start.getDay();
                  const diff = start.getDate() - day + (day === 0 ? -6 : 1);
                  start.setDate(diff);
                  const days = [];
                  for (let i = 0; i < 42; i++) {
                    const d = new Date(start);
                    d.setDate(d.getDate() + i);
                    days.push(d);
                  }

                  return (
                    <div key={monthIndex} className="bg-app-surface border border-app-border rounded-xl p-4 shadow-sm hover:border-primary/50 transition">
                      <h3 className="text-lg font-bold font-syne text-app-text mb-3">{monthName}</h3>
                      <div className="grid grid-cols-7 gap-1 mb-1">
                        {['M', 'T', 'W', 'T', 'F', 'S', 'S'].map((d, i) => (
                          <div key={i} className="text-center text-[10px] font-bold text-app-text3">{d}</div>
                        ))}
                      </div>
                      <div className="grid grid-cols-7 gap-1">
                        {days.map((d, i) => {
                          const isCurrentMonth = d.getMonth() === monthIndex;
                          const isTdy = isToday(d);

                          // Check if day has events or tasks
                          const hasEvent = state.googleEvents.some((e: any) => {
                            const estart = new Date(e.start.dateTime);
                            return estart.getDate() === d.getDate() && estart.getMonth() === d.getMonth() && estart.getFullYear() === d.getFullYear();
                          });
                          const hasTask = tasksWithDeadlines.some(t => {
                            const tdeadline = new Date(t.deadline!);
                            return tdeadline.getDate() === d.getDate() && tdeadline.getMonth() === d.getMonth() && tdeadline.getFullYear() === d.getFullYear();
                          });

                          return (
                            <div 
                              key={i} 
                              onClick={() => {
                                setCurrentDate(d);
                                setView('day');
                              }}
                              className={`aspect-square flex flex-col items-center justify-center rounded text-[10px] cursor-pointer hover:bg-app-surface2 transition relative
                                ${!isCurrentMonth ? 'text-app-text3 opacity-30' : isTdy ? 'bg-primary text-white font-bold shadow-md' : 'text-app-text2 font-medium'}
                              `}
                            >
                              <span>{d.getDate()}</span>
                              <div className="flex gap-0.5 mt-0.5">
                                {hasEvent && <span className={`w-1 h-1 rounded-full ${isTdy ? 'bg-white' : 'bg-blue-500'}`}></span>}
                                {hasTask && <span className={`w-1 h-1 rounded-full ${isTdy ? 'bg-white' : 'bg-red-500'}`}></span>}
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          )}
        </div>

        {/* Sliding Right Panel - Prep & AI Notes */}
        <div 
          className={`flex-shrink-0 w-[380px] bg-app-surface border-l border-app-border flex flex-col transition-transform duration-300 transform ${isPrepPanelOpen && selectedEvent ? 'translate-x-0' : 'translate-x-full absolute right-0 top-0 bottom-0 z-50'}`}
          style={{ boxShadow: isPrepPanelOpen ? '-10px 0 30px rgba(0,0,0,0.2)' : 'none' }}
        >
          {selectedEvent && (
            <>
              {/* Prep Header */}
              <div className="p-5 border-b border-app-border flex justify-between items-start">
                <div>
                  <h3 className="font-bold text-lg font-syne text-app-text mb-1">{selectedEvent.summary}</h3>
                  <p className="text-xs text-app-text3 font-medium">
                    {new Date(selectedEvent.start.dateTime).toLocaleString()} - {new Date(selectedEvent.end.dateTime).toLocaleTimeString()}
                  </p>
                </div>
                <button onClick={() => setIsPrepPanelOpen(false)} className="text-app-text3 hover:text-app-text p-1 bg-app-surface2 rounded-lg">
                  <X className="w-5 h-5" />
                </button>
              </div>

              {/* Prep Actions */}
              <div className="p-5 border-b border-app-border space-y-3">
                {selectedEvent.meetLink && (
                  <a href={selectedEvent.meetLink} target="_blank" rel="noreferrer" className="flex items-center justify-center gap-2 w-full py-2.5 bg-blue-500/10 text-blue-500 hover:bg-blue-500/20 rounded-lg font-bold text-sm transition">
                    <Video className="w-4 h-4" /> Join Google Meet
                  </a>
                )}
                <button className="flex items-center justify-center gap-2 w-full py-2.5 bg-app-surface2 text-app-text hover:bg-app-hover rounded-lg font-bold text-sm border border-app-border transition">
                  <LinkIcon className="w-4 h-4" /> Copy Link
                </button>
              </div>

              {/* AI Context / Notes */}
              <div className="flex-1 overflow-y-auto p-5">
                <div className="flex items-center gap-2 mb-4">
                  <Sparkles className="w-4 h-4 text-purple-500" />
                  <h4 className="text-sm font-bold uppercase tracking-wider text-app-text2">AI Meeting Prep</h4>
                </div>

                <div className="bg-purple-500/5 border border-purple-500/20 rounded-xl p-4 mb-6">
                  <p className="text-sm text-app-text mb-3 leading-relaxed">
                    Based on recent emails and tasks, the client will likely ask about the <strong className="text-purple-400">Q3 Campaign Creatives</strong>.
                  </p>
                  <ul className="text-[13px] text-app-text2 space-y-2 list-disc pl-4">
                    <li>Task "Draft Ad Copy" is <strong className="text-green-500">Done</strong></li>
                    <li>Task "Render final video" is <strong className="text-amber-500">In Progress</strong> (due in 2 hours)</li>
                  </ul>
                  <button className="mt-4 text-xs font-bold text-purple-500 bg-purple-500/10 px-3 py-1.5 rounded-md hover:bg-purple-500/20 transition">
                    Generate Full Brief
                  </button>
                </div>

                <div className="flex items-center gap-2 mb-4">
                  <AlignLeft className="w-4 h-4 text-app-text3" />
                  <h4 className="text-sm font-bold uppercase tracking-wider text-app-text2">Attendees</h4>
                </div>

                <div className="space-y-2">
                  {selectedEvent.attendees ? selectedEvent.attendees.map((a, i) => (
                    <div key={i} className="flex items-center gap-3 p-2 rounded-lg hover:bg-app-surface2 transition">
                      <div className="w-8 h-8 rounded-full bg-app-border flex items-center justify-center text-xs font-bold text-app-text">
                        {a.email.charAt(0).toUpperCase()}
                      </div>
                      <div className="min-w-0">
                        <p className="text-sm font-medium text-app-text truncate">{a.email}</p>
                        <p className="text-[10px] text-app-text3 capitalize">{a.responseStatus || 'needsAction'}</p>
                      </div>
                    </div>
                  )) : (
                    <p className="text-xs text-app-text3">No attendees listed.</p>
                  )}
                </div>

                {selectedEvent.description && (
                  <div className="mt-8">
                    <h4 className="text-sm font-bold uppercase tracking-wider text-app-text2 mb-3">Description</h4>
                    <div className="text-sm text-app-text2 prose prose-invert" dangerouslySetInnerHTML={{ __html: selectedEvent.description }} />
                  </div>
                )}
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';

import { useApp } from '@/contexts/AppContext';
import { useAuth } from '@/contexts/AuthContext';
import { notFound } from 'next/navigation';
import Link from 'next/link';
import { useState, useEffect, use } from 'react';
import TaskCard from '@/components/tasks/TaskCard';

export default function ClientDetailPage({ params }: { params: Promise<{ id: string }> }) {
  const { state } = useApp();
  const { user } = useAuth();
  const { id } = use(params);

  const [client, setClient] = useState<any>(null);
  const [activeServices, setActiveServices] = useState<any[]>([]);
  const [invoices, setInvoices] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchClientData = async () => {
      try {
        const token = localStorage.getItem('invictus_jwt');
        const headers = { 'Authorization': `Bearer ${token}` };

        const [clientRes, delivRes, invRes] = await Promise.all([
          fetch(`http://localhost:4000/api/clients/${id}`, { headers }),
          fetch(`http://localhost:4000/api/clients/${id}/deliverables`, { headers }),
          fetch(`http://localhost:4000/api/clients/${id}/invoices`, { headers })
        ]);

        if (clientRes.ok) setClient(await clientRes.json());
        if (delivRes.ok) setActiveServices(await delivRes.json());
        if (invRes.ok) setInvoices(await invRes.json());
      } catch (err) {
        console.error('Failed to fetch client data', err);
      } finally {
        setLoading(false);
      }
    }
    fetchClientData();
  }, [id]);

  if (loading) {
    return <div className="p-8 text-[var(--c-text-2)]">Loading client details...</div>;
  }

  if (!client) {
    return (
      <div className="p-8 text-[var(--c-error)]">
        <h2>Client not found</h2>
        <Link href="/clients" className="text-[var(--c-primary)] hover:underline mt-4 inline-block">Return to Clients</Link>
      </div>
    );
  }

  // Real Tasks
  const relatedTasks = state.tasks.filter(t => t.clientId === id);
  const todoTasks = relatedTasks.filter(t => t.status === 'todo');
  const inProgressTasks = relatedTasks.filter(t => t.status === 'in_progress');
  const doneTasks = relatedTasks.filter(t => t.status === 'done');

  return (
    <div className="p-8 max-w-6xl mx-auto flex flex-col gap-8 min-h-[calc(100vh-4rem)]">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Link href="/clients" className="p-2 rounded-lg hover:bg-[var(--c-surface-2)] transition-colors flex items-center justify-center text-[var(--c-text-3)] hover:text-[var(--c-text)]">
          <span className="material-symbols-outlined">arrow_back</span>
        </Link>
        <div>
          <h1 className="text-3xl font-bold font-syne text-[var(--c-text)]">{client.name}</h1>
          <div className="flex items-center gap-3 mt-1 text-sm text-[var(--c-text-2)]">
            <span className="font-mono bg-[var(--c-primary)]/10 text-[var(--c-primary)] px-2 py-0.5 rounded font-bold">{client.short_code || client.code || 'CODE'}</span>
            <span>Client Portal</span>
            <span>•</span>
            <span className="flex items-center gap-1">
              <span className="material-symbols-outlined text-[16px]">person</span>
              {client.primary_contact || 'Main Contact'}
            </span>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Left Column: Client Info & Services */}
        <div className="lg:col-span-1 flex flex-col gap-8">
          <div className="bg-[var(--c-surface)] rounded-xl border border-[var(--c-border)] p-6 shadow-sm">
            <h2 className="text-lg font-bold font-syne text-[var(--c-text)] mb-4">Client Info</h2>
            <div className="space-y-3 text-sm">
              <div className="flex justify-between border-b border-[var(--c-border)] pb-2">
                <span className="text-[var(--c-text-2)]">Email:</span>
                <span className="font-bold">{client.email || 'N/A'}</span>
              </div>
              <div className="flex justify-between border-b border-[var(--c-border)] pb-2">
                <span className="text-[var(--c-text-2)]">Phone:</span>
                <span className="font-bold">{client.phone || 'N/A'}</span>
              </div>
              <div className="flex justify-between border-b border-[var(--c-border)] pb-2">
                <span className="text-[var(--c-text-2)]">Status:</span>
                <span className={`font-bold ${client.status === 'active' ? 'text-[var(--c-primary)]' : 'text-[var(--c-text-3)]'}`}>
                  {client.status?.toUpperCase() || 'ACTIVE'}
                </span>
              </div>
            </div>
          </div>

          <div className="bg-[var(--c-surface)] rounded-xl border border-[var(--c-border)] p-6 shadow-sm">
            <h2 className="text-lg font-bold font-syne text-[var(--c-text)] mb-4 flex justify-between items-center">
              Active Services
              <button className="text-[var(--c-primary)] hover:underline text-sm font-bold flex items-center gap-1">
                <span className="material-symbols-outlined text-[16px]">add</span> Add
              </button>
            </h2>
            <div className="space-y-4">
              {activeServices.length === 0 && <div className="text-[var(--c-text-3)] text-sm">No active services found.</div>}
              {activeServices.map((s, i) => (
                <div key={i} className="bg-[var(--c-bg)] border border-[var(--c-border)] rounded-lg p-3">
                  <div className="flex justify-between items-center mb-1">
                    <span className="font-bold text-[var(--c-text)] text-sm">{s.deliverable_name}</span>
                    <span className={`text-xs px-2 py-0.5 rounded font-bold ${s.is_active ? 'bg-[var(--c-primary)]/10 text-[var(--c-primary)]' : 'bg-[var(--c-surface-3)] text-[var(--c-text-2)]'}`}>{s.is_active ? 'Active' : 'Paused'}</span>
                  </div>
                  <div className="text-xs text-[var(--c-text-3)]">{s.quantity_per_month} {s.unit} ({s.deliverable_type})</div>
                </div>
              ))}
            </div>
          </div>

          <div className="bg-[var(--c-surface)] rounded-xl border border-[var(--c-border)] p-6 shadow-sm">
            <h2 className="text-lg font-bold font-syne text-[var(--c-text)] mb-4 flex justify-between items-center">
              Invoices
              <button className="text-[var(--c-primary)] hover:underline text-sm font-bold flex items-center gap-1">
                <span className="material-symbols-outlined text-[16px]">receipt_long</span> View All
              </button>
            </h2>
            <div className="space-y-0">
              {invoices.length === 0 && <div className="text-[var(--c-text-3)] text-sm p-3">No invoices generated yet.</div>}
              {invoices.map((inv, i) => (
                <div key={i} className="flex justify-between items-center border-b border-[var(--c-border)] last:border-0 py-3">
                  <div>
                    <div className="font-bold text-[var(--c-text)] text-sm">{inv.invoice_number}</div>
                    <div className="text-xs text-[var(--c-text-3)]">{new Date(inv.issue_date).toLocaleDateString()}</div>
                  </div>
                  <div className="text-right">
                    <div className="font-bold text-[var(--c-text)] text-sm">₹{inv.amount_inr?.toLocaleString()}</div>
                    <div className={`text-xs font-bold capitalize ${
                      inv.status === 'paid' ? 'text-[var(--c-primary)]' : 
                      inv.status === 'pending' ? 'text-amber-500' : 'text-[var(--c-text-3)]'
                    }`}>{inv.status}</div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Right Column: Tasks */}
        <div className="lg:col-span-2 bg-[var(--c-surface)] rounded-xl border border-[var(--c-border)] shadow-sm flex flex-col h-[800px] overflow-hidden">
          <div className="p-6 border-b border-[var(--c-border)] bg-[var(--c-surface-2)] flex justify-between items-center">
            <h2 className="text-lg font-bold font-syne text-[var(--c-text)]">Client Tasks</h2>
            <div className="flex gap-2">
              <span className="text-xs font-bold px-2 py-1 bg-[var(--c-primary)]/10 text-[var(--c-primary)] rounded">To Do: {todoTasks.length}</span>
              <span className="text-xs font-bold px-2 py-1 bg-blue-500/10 text-blue-500 rounded">In Progress: {inProgressTasks.length}</span>
            </div>
          </div>
          <div className="p-6 flex-1 overflow-y-auto space-y-6 bg-[var(--c-bg)]">
            {relatedTasks.length === 0 ? (
              <div className="text-center p-8 text-[var(--c-text-3)]">No tasks assigned to this client.</div>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {relatedTasks.map(task => (
                  <TaskCard key={task.id} task={task} onClick={() => {}} />
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

