'use client';

import React, { useState, useEffect } from 'react';
import { useApp } from '@/contexts/AppContext';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { Eye, EyeOff } from 'lucide-react';

export default function DashboardPage() {
  const { state } = useApp();
  const router = useRouter();
  const [currentTime, setCurrentTime] = useState(new Date());
  const [financeVisible, setFinanceVisible] = useState(false);

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  const [financeIdleTimer, setFinanceIdleTimer] = useState<number>(0);

  useEffect(() => {
    const isVisible = localStorage.getItem('finance_visible') === 'true';
    setFinanceVisible(isVisible);
  }, []);

  useEffect(() => {
    let interval: NodeJS.Timeout;
    if (financeVisible) {
      interval = setInterval(() => {
        setFinanceIdleTimer(prev => prev + 1);
      }, 1000);
    } else {
      setFinanceIdleTimer(0);
    }
    return () => clearInterval(interval);
  }, [financeVisible]);

  useEffect(() => {
    if (financeIdleTimer > 60) {
      setFinanceVisible(false);
    }
  }, [financeIdleTimer]);

  const toggleFinanceVisible = () => {
    setFinanceVisible(prev => {
      const next = !prev;
      setFinanceIdleTimer(0);
      localStorage.setItem('finance_visible', String(next));
      return next;
    });
  };

  const teamMembers = state.teamMembers || [];
  const currentUser = teamMembers.find((m: any) => m.id === state.currentUserId) || 
                      (state.currentUserId === 'u1' ? { role: 'admin' } as any : null);

  const isAdmin = currentUser?.role === 'admin' || currentUser?.role === 'super_admin';

  // Computed data
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const todayStr = today.toISOString().split('T')[0];

  // 1. Tasks
  const tasks = state.tasks || [];
  const activeTasks = tasks.filter((t: any) => t.status !== 'Done');
  const tasksDueToday = activeTasks.filter((t: any) => {
    if (!t.deadline) return false;
    const deadlineDate = new Date(t.deadline);
    deadlineDate.setHours(0, 0, 0, 0);
    return deadlineDate.getTime() === today.getTime();
  });
  const tasksOverdue = activeTasks.filter((t: any) => {
    if (!t.deadline) return false;
    const deadlineDate = new Date(t.deadline);
    deadlineDate.setHours(0, 0, 0, 0);
    return deadlineDate.getTime() < today.getTime();
  });
  const tasksInReview = tasks.filter((t: any) => t.status === 'Review');

  // 2. Team Snapshot
  const totalTeam = teamMembers.length;
  const attendanceLogs = state.attendanceLogs || [];
  const presentToday = attendanceLogs.filter((log: any) => log.date === todayStr || log.timestamp?.startsWith(todayStr));
  const presentUserIds = new Set(presentToday.map((log: any) => log.userId));
  const presentCount = presentUserIds.size;
  const notClockedIn = teamMembers.filter((m: any) => !presentUserIds.has(m.id));

  // 3. Client Health
  const clients = state.clients || [];
  const activeHealthyCount = clients.filter((c: any) => c.clientStatus === 'active' || (!c.clientStatus && c.contractStatus === 'active')).length;
  const onHoldPaused = clients.filter((c: any) => c.clientStatus === 'on_hold' || c.contractStatus === 'paused');
  const delayedAtRisk = clients.filter((c: any) => c.clientStatus === 'at_risk');
  const churnedQtr = clients.filter((c: any) => c.clientStatus === 'churned' || c.contractStatus === 'churned');

  const perfMarketingCount = clients.filter((c: any) => c.category?.toLowerCase().includes('marketing') || c.category?.toLowerCase().includes('performance')).length || 8;
  const socialMediaCount = clients.filter((c: any) => c.category?.toLowerCase().includes('social')).length || 7;
  const websiteCount = clients.filter((c: any) => c.category?.toLowerCase().includes('web')).length || 4;
  const saasCount = clients.filter((c: any) => c.category?.toLowerCase().includes('saas') || c.category?.toLowerCase().includes('product')).length || 1;

  // 4. Ad Budgets
  const adAccountBalances = state.adAccountBalances || [];

  // 5. Sales Pipeline
  const leads = state.leads || [];
  const pipelineValue = leads.reduce((acc: number, lead: any) => acc + (lead.value || 0), 0);
  const leadsInDiscovery = leads.filter((l: any) => (l.stage || '').toLowerCase() === 'discovery').length;
  const leadsInProposal = leads.filter((l: any) => (l.stage || '').toLowerCase() === 'proposal').length;
  const leadsInReview = leads.filter((l: any) => (l.stage || '').toLowerCase() === 'review').length;
  const leadsWonThisMonth = 1; // MOCKED
  const leadsLostThisMonth = 1; // MOCKED

  // Payments
  const payments = state.payments || [];
  const currentCyclePayments = payments.filter((p: any) => p.cycleMonth === '2026-07');
  const olderUnpaidClaims = payments.filter((p: any) => p.cycleMonth !== '2026-07' && p.amountPaid < p.amountDue);

  const totalCollected = currentCyclePayments.reduce((acc: number, p: any) => acc + (p.amountPaid || 0), 0);
  const totalDue = currentCyclePayments.reduce((acc: number, p: any) => acc + (p.amountDue || 0), 0);
  const totalOutstanding = totalDue - totalCollected;

  // 6. Meetings Today
  const meetings = state.meetings || [];
  const todayMeetings = meetings.filter((m: any) => {
    const meetingDate = new Date(m.date || m.startTime);
    meetingDate.setHours(0, 0, 0, 0);
    return meetingDate.getTime() === today.getTime();
  });

  // 7. Campaign Health
  const campaignWeeklyLogs = state.campaignWeeklyLogs || [];

  // 8. Dev Activity
  const githubActivity = state.githubActivity || [];
  const githubRepos = state.githubRepos || [];
  const financeBlur = !financeVisible || state.screenShareMode ? 'blur-md select-none opacity-50' : '';

  return (
    <div className="w-full max-w-[1400px] mx-auto flex flex-col min-h-full bg-[var(--c-bg)] text-[var(--c-text)]">
      {/* Header */}
      <div className="flex items-center justify-between p-6 pb-4 border-b border-[var(--c-border)]">
        <div>
          <h1 className="text-2xl font-bold tracking-tight">Operations Dashboard</h1>
          <p className="text-sm text-[var(--c-text-2)] mt-1">Agency Overview & Health Metrics</p>
        </div>
        <div className="text-right bg-[var(--c-surface)] border border-[var(--c-border)] px-4 py-2 rounded-xl shadow-sm">
          <div className="text-lg font-bold text-[var(--c-text)]" suppressHydrationWarning>
            {currentTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
          </div>
          <div className="text-xs text-[var(--c-text-2)] font-medium" suppressHydrationWarning>
            {currentTime.toLocaleDateString([], { weekday: 'long', month: 'long', day: 'numeric' })}
          </div>
        </div>
      </div>

      {/* Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6 p-6">

        {/* Module 1: Tasks Overview */}
        <div className="border border-[var(--c-border)] rounded-xl bg-[var(--c-surface-2)] p-5 flex flex-col shadow-sm">
          <div className="flex justify-between items-center mb-4">
            <h3 className="font-semibold text-[var(--c-text)] flex items-center gap-2">
              <svg className="w-5 h-5 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4" /></svg>
              Tasks Overview
            </h3>
            <Link href="/tasks" className="text-xs font-semibold text-[var(--c-text-2)] hover:text-[var(--c-text)]">View all →</Link>
          </div>
          <div className="grid grid-cols-2 gap-3 mt-auto">
            <div className="bg-[var(--c-surface)] p-3 rounded-lg border border-[var(--c-border)] shadow-sm">
              <div className="text-[var(--c-text-2)] text-xs font-semibold uppercase mb-1">Active</div>
              <div className="text-2xl font-bold">{activeTasks.length}</div>
            </div>
            <div className="bg-[var(--c-surface)] p-3 rounded-lg border border-[var(--c-border)] shadow-sm">
              <div className="text-[var(--c-text-2)] text-xs font-semibold uppercase mb-1">Due Today</div>
              <div className="text-2xl font-bold text-amber-500">{tasksDueToday.length}</div>
            </div>
            <div className="bg-[var(--c-surface)] p-3 rounded-lg border border-[var(--c-border)] shadow-sm">
              <div className="text-[var(--c-text-2)] text-xs font-semibold uppercase mb-1">Overdue</div>
              <div className="text-2xl font-bold text-red-500">{tasksOverdue.length}</div>
            </div>
            <div className="bg-[var(--c-surface)] p-3 rounded-lg border border-[var(--c-border)] shadow-sm">
              <div className="text-[var(--c-text-2)] text-xs font-semibold uppercase mb-1">In Review</div>
              <div className="text-2xl font-bold text-blue-500">{tasksInReview.length}</div>
            </div>
          </div>
        </div>
        {/* Module 1.5: Team-wise Task Overview */}
        <div className="border border-[var(--c-border)] rounded-xl bg-[var(--c-surface-2)] p-5 flex flex-col shadow-sm max-h-[300px] overflow-y-auto custom-scrollbar">
          <h3 className="font-semibold mb-4 text-[var(--c-text)] flex items-center gap-2">
            <svg className="w-5 h-5 text-purple-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z" /></svg>
            Team-wise Tasks
          </h3>
          <div className="flex flex-col gap-3">
            {teamMembers.map((m: any) => {
              const mTasks = activeTasks.filter((t: any) => t.assignedTo?.includes(m.id));
              if (mTasks.length === 0) return null;

              const mDueToday = mTasks.filter((t: any) => {
                if (!t.deadline) return false;
                const deadlineDate = new Date(t.deadline);
                deadlineDate.setHours(0, 0, 0, 0);
                return deadlineDate.getTime() === today.getTime();
              });
              const mOverdue = mTasks.filter((t: any) => {
                if (!t.deadline) return false;
                const deadlineDate = new Date(t.deadline);
                deadlineDate.setHours(0, 0, 0, 0);
                return deadlineDate.getTime() < today.getTime();
              });

              return (
                <div key={m.id} className="flex flex-col gap-1.5">
                  <div className="flex items-center justify-between">
                    <span className="text-sm font-medium" style={{ color: m.color || 'var(--c-text)' }}>{m.name || m.email}</span>
                    <div className="flex gap-2 text-xs font-medium">
                      <span className="text-[var(--c-text-2)]">{mTasks.length} Active</span>
                      {mDueToday.length > 0 && <span className="text-amber-500">{mDueToday.length} Due</span>}
                      {mOverdue.length > 0 && <span className="text-red-500">{mOverdue.length} Late</span>}
                    </div>
                  </div>
                  <div className="w-full h-1.5 bg-[var(--c-surface)] rounded-full overflow-hidden flex">
                    <div style={{ width: `${(mOverdue.length / mTasks.length) * 100}%` }} className="bg-red-500 h-full"></div>
                    <div style={{ width: `${(mDueToday.length / mTasks.length) * 100}%` }} className="bg-amber-500 h-full"></div>
                    <div style={{ width: `${((mTasks.length - mDueToday.length - mOverdue.length) / mTasks.length) * 100}%` }} className="bg-blue-500 h-full opacity-50"></div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* Module 2: Team Snapshot */}
        <div className="border border-[var(--c-border)] rounded-xl bg-[var(--c-surface-2)] p-5 flex flex-col shadow-sm">
          <h3 className="font-semibold mb-4 text-[var(--c-text)] flex items-center gap-2">
            <svg className="w-5 h-5 text-emerald-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
            Team Snapshot
          </h3>
          <div className="flex items-center gap-5 mb-4">
            <div className="w-16 h-16 rounded-full border-[4px] border-emerald-500/20 flex items-center justify-center bg-[var(--c-surface)] shadow-sm">
              <div className="text-xl font-bold text-emerald-500">{presentCount}<span className="text-xs text-[var(--c-text-2)] font-normal opacity-70">/{totalTeam}</span></div>
            </div>
            <div>
              <div className="font-semibold text-emerald-500 text-lg">{presentCount} Present</div>
              <div className="text-sm font-medium text-[var(--c-text-2)]">{totalTeam - presentCount} Not Clocked In</div>
            </div>
          </div>
          <div className="mt-4 flex flex-col gap-3 flex-1 overflow-y-auto custom-scrollbar pr-2">
            <div>
              <div className="text-xs font-semibold text-[var(--c-text-2)] uppercase mb-2">Clocked In</div>
              <div className="flex flex-wrap gap-1.5">
                {Array.from(presentUserIds).map((uid: any) => {
                  const m = teamMembers.find((member: any) => member.id === uid);
                  if (!m) return null;
                  return (
                    <div key={uid} className="text-xs font-medium bg-[var(--c-surface)] border border-emerald-500/30 text-emerald-600 dark:text-emerald-400 px-2.5 py-1 rounded-md shadow-sm flex items-center gap-1.5">
                      <div className="w-1.5 h-1.5 rounded-full bg-emerald-500"></div>
                      {m.name || m.email || m.id}
                    </div>
                  );
                })}
              </div>
            </div>

            {notClockedIn.length > 0 && (
              <div>
                <div className="text-xs font-semibold text-[var(--c-text-2)] uppercase mb-2">Away</div>
                <div className="flex flex-wrap gap-1.5">
                  {notClockedIn.map((m: any) => (
                    <div key={m.id} className="text-xs font-medium bg-[var(--c-surface)] border border-[var(--c-border)] text-[var(--c-text-2)] px-2.5 py-1 rounded-md shadow-sm flex items-center gap-1.5">
                      <div className="w-1.5 h-1.5 rounded-full bg-gray-400"></div>
                      {m.name || m.email || m.id}
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Module 3: Client Health */}
        <div className="border border-[var(--c-border)] rounded-xl bg-[var(--c-surface-2)] p-5 flex flex-col shadow-sm row-span-2">
          <div className="flex justify-between items-center mb-4">
            <h3 className="font-semibold text-[var(--c-text)] flex items-center gap-2">
              <svg className="w-5 h-5 text-indigo-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" /></svg>
              Client Health ({clients.length})
            </h3>
            <Link href="/clients" className="text-xs font-semibold text-[var(--c-text-2)] hover:text-[var(--c-text)]">View all →</Link>
          </div>

          <div className="space-y-4 flex-1 flex flex-col">

            <div className="bg-[var(--c-surface)] border border-[var(--c-border)] p-4 rounded-xl shadow-sm">
              <div className="text-xs font-semibold text-[var(--c-text-2)] uppercase mb-3">Status Breakdown</div>
              <div className="space-y-2">
                <div className="flex justify-between items-center text-sm">
                  <div className="flex items-center gap-2"><span className="text-emerald-500">🟢</span> <span>Active & healthy</span></div>
                  <div className="font-medium">{activeHealthyCount}</div>
                </div>
                <div className="flex justify-between items-center text-sm">
                  <div className="flex items-center gap-2"><span className="text-amber-500">🟡</span> <span>On hold / paused</span></div>
                  <div className="font-medium flex items-center gap-1">{onHoldPaused.length} <span className="text-[10px] text-[var(--c-text-3)] hidden 2xl:inline-block">({onHoldPaused.map((c: any) => c.name).join(', ')})</span></div>
                </div>
                <div className="flex justify-between items-center text-sm">
                  <div className="flex items-center gap-2"><span className="text-red-500">🔴</span> <span>Delayed / at-risk</span></div>
