const SIDEBAR_FULL = 240;
const SIDEBAR_COLLAPSED = 64;

export default function AppLayout({ children }: { children: React.ReactNode }) {
  const pathname = usePathname();
  const router = useRouter();
  const { state } = useApp();
  const [collapsed, setCollapsed] = useState(false);

  const user = state.teamMembers.find(m => m.id === state.currentUserId);
  const isTeamMember = user && (user.role === 'team' || user.role === 'viewer');

  // For team members on mobile, sidebar width is 0 effectively since it's hidden
  const sw = isTeamMember ? (collapsed ? SIDEBAR_COLLAPSED : SIDEBAR_FULL) : (collapsed ? SIDEBAR_COLLAPSED : SIDEBAR_FULL); // We'll handle responsive margin via CSS classes

  useEffect(() => {
    if (isTeamMember) {
      if (pathname !== '/my-workspace') {
        alert('You do not have permission to view this page.'); // Replace with toast later
        router.push('/my-workspace');
      }
    }
  }, [pathname, isTeamMember, router]);

  return (
    <div className="h-screen overflow-hidden" style={{ background: 'var(--c-bg)' }}>
      <SideNavBar />
      <TopAppBar sidebarWidth={sw} />
      <main
        className={`page-enter overflow-y-auto ${isTeamMember ? 'md:ml-[240px] mb-[64px] md:mb-0' : ''}`}
        style={{
          marginLeft: isTeamMember ? undefined : sw,
          marginTop: 56,
          height: isTeamMember ? 'calc(100vh - 56px - 64px)' : 'calc(100vh - 56px)', // Adjust height on mobile for bottom bar
          padding: '28px 32px',
          transition: 'margin-left 0.3s',
        }}
      >
        {state.globalError ? (
          <div className="flex flex-col items-center justify-center h-full text-center">
            <div className="text-red-500 text-xl font-medium mb-4">API Error</div>
            <p className="text-[#888888] mb-6">{state.globalError}</p>
            <button onClick={() => window.location.reload()} className="bg-[#222222] hover:bg-[#333333] px-4 py-2 rounded-lg transition-colors">
              Retry
            </button>
          </div>
        ) : state.isGlobalLoading ? (
          <div className="animate-pulse space-y-6">
            <div className="h-10 bg-[#222222] rounded w-1/4"></div>
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
              {[1,2,3,4].map(i => <div key={i} className="h-24 bg-[#111111] rounded border border-[#222222]"></div>)}
            </div>
            <div className="h-64 bg-[#111111] rounded border border-[#222222]"></div>
          </div>
        ) : (
          children
        )}
      </main>
      <BottomTabBar />
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useApp } from '@/contexts/AppContext';
import TeamTaskCard from '@/components/tasks/TeamTaskCard';
import TaskDrawer from '@/components/tasks/TaskDrawer';
import RoleWidget from '@/components/team/RoleWidget';
import { Play, Square, CheckCircle, Bell, User, Clock, ChevronRight } from 'lucide-react';

export default function MyWorkspacePage() {
  const { state, setTaskStatus, clockIn, clockOut } = useApp();
  const [selectedTaskId, setSelectedTaskId] = useState<string | null>(null);

  const currentUser = (state.teamMembers || []).find(m => m.id === state.currentUserId);
  const firstName = currentUser?.name.split(' ')[0] || 'Team Member';

  // Date and greeting
  const hour = new Date().getHours();
  const greeting = hour < 12 ? 'Good morning' : hour < 17 ? 'Good afternoon' : 'Good evening';
  const dateStr = new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' });

  // Filter Tasks
  const myTasks = (state.tasks || []).filter(t => t.assignedTo?.includes(state.currentUserId) && t.status !== 'done');

  const today = new Date();
  today.setHours(0,0,0,0);

  const todaysFocus = myTasks.filter(t => {
    let overdue = false;
    let dueToday = false;
    if (t.deadline) {
      const dl = new Date(t.deadline);
      dl.setHours(0,0,0,0);
      if (dl.getTime() < today.getTime()) overdue = true;
      if (dl.getTime() === today.getTime()) dueToday = true;
    }
    return overdue || dueToday || t.priority === 'critical' || t.priority === 'high';
  }).sort((a, b) => {
    // overdue first
    const aDl = a.deadline ? new Date(a.deadline).getTime() : Infinity;
    const bDl = b.deadline ? new Date(b.deadline).getTime() : Infinity;
    if (aDl < today.getTime() && bDl >= today.getTime()) return -1;
    if (bDl < today.getTime() && aDl >= today.getTime()) return 1;
    return aDl - bDl;
  });

  const inReviewTasks = myTasks.filter(t => t.status === 'in_review');
  const upcomingTasks = myTasks.filter(t => !todaysFocus.find(tf => tf.id === t.id) && t.status !== 'in_review');

  const activeTimerTask = myTasks.find(t => t.status === 'in_progress');
  const unreadCount = (state.notifications || []).filter(n => n.userId === state.currentUserId && !n.read).length;

  return (
    <div className="flex flex-col h-full gap-6 pb-20 md:pb-10 max-w-7xl mx-auto">

      {/* A1 Header Bar */}
      <div className="flex items-center justify-between bg-surface rounded-xl p-4 border border-border sticky top-0 z-20 shadow-sm">
        <div>
          <h2 className="text-xl md:text-2xl font-bold font-syne text-text">
            {hour < 12 ? '☀️' : hour < 17 ? '🌤️' : '🌙'} {greeting}, {firstName}.
          </h2>
          <p className="text-text-2 text-sm mt-1 flex items-center gap-2">
            {dateStr} &middot; <span className="font-semibold text-text">{todaysFocus.length} due today</span> &middot; <span className="font-semibold text-red-500">1 overdue</span>
          </p>
        </div>
        <div className="flex items-center gap-3 md:gap-4">
          {(() => {
            if (!currentUser) return null;
            const todayStr = new Date().toISOString().split('T')[0];
            const log = state.attendanceLogs.find(l => l.userId === currentUser.id && l.date === todayStr);
            if (log && !log.clockOut) {
              return (
                <button 
                  onClick={() => clockOut(currentUser.id, todayStr, new Date().toISOString())}
                  className="hidden md:flex bg-amber-500/10 hover:bg-amber-500/20 text-amber-500 font-bold text-sm px-4 py-2 rounded-lg border border-amber-500/20 transition items-center gap-2"
                >
                  <Clock size={16} /> Clock out
                </button>
              );
            } else if (log && log.clockOut) {
              return (
                <button disabled className="hidden md:flex bg-surface-3 text-text-3 font-bold text-sm px-4 py-2 rounded-lg border border-border items-center gap-2 opacity-50 cursor-not-allowed">
                  <Clock size={16} /> Done for today
                </button>
              );
            } else {
              return (
                <button 
                  onClick={() => clockIn(currentUser.id, todayStr, new Date().toISOString(), new Date().getHours() >= 10)}
                  className="hidden md:flex bg-primary/10 hover:bg-primary/20 text-primary font-bold text-sm px-4 py-2 rounded-lg border border-primary/20 transition items-center gap-2"
                >
                  <Clock size={16} /> Clock in
                </button>
              );
            }
          })()}
          <button className="relative w-10 h-10 rounded-full bg-surface-2 flex items-center justify-center hover:bg-surface-3 transition border border-border">
            <Bell size={20} className="text-text-2" />
            {unreadCount > 0 && <span className="absolute top-0 right-0 w-3 h-3 bg-red-500 rounded-full border-2 border-surface" />}
          </button>
          <div className="w-10 h-10 rounded-full bg-surface-2 flex items-center justify-center border border-border overflow-hidden">
            <User size={20} className="text-text-2" />
          </div>
        </div>
      </div>

      {/* A2 Active Timer Bar */}
      {activeTimerTask ? (
        <div className="bg-[#10B981] text-white p-4 rounded-xl shadow-lg flex items-center justify-between sticky top-[88px] z-10 transition-transform">
          <div className="flex items-center gap-3">
            <div className="w-2 h-2 rounded-full bg-white animate-pulse" />
            <span className="font-bold">Working on: {activeTimerTask.title}</span>
            <span className="font-mono text-lg ml-2">00:47:32</span>
          </div>
          <button 
            onClick={() => setTaskStatus(activeTimerTask.id, 'todo')}
            className="bg-black/20 hover:bg-black/30 font-bold px-4 py-2 rounded-lg flex items-center gap-2 transition"
          >
            <Square size={16} fill="currentColor" /> Stop
          </button>
        </div>
      ) : (
        <div className="text-center py-2 text-xs font-semibold text-text-3 uppercase tracking-wider bg-surface-2 rounded-lg border border-border">
          No active timer — start one from any task
        </div>
      )}

      {/* A3 Role Widget */}
      <RoleWidget />

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 flex flex-col gap-8">

          {/* A4 Today's Focus */}
          <section>
            <h3 className="text-lg font-bold font-syne mb-4 flex items-center gap-2">
              <span className="w-2 h-6 rounded-full bg-primary" /> Today's Focus
            </h3>
            {todaysFocus.length === 0 ? (
              <div className="p-6 bg-surface-2 border border-border rounded-xl text-text-2 text-sm flex items-center gap-2">
                <CheckCircle size={16} className="text-primary" /> You're clear for today. Check Upcoming below.
              </div>
            ) : (
              <div className="flex flex-col gap-4">
                {todaysFocus.map(task => (
                  <TeamTaskCard key={task.id} task={task} onClick={() => setSelectedTaskId(task.id)} />
                ))}
              </div>
            )}
          </section>

          {/* A5 In Review */}
          {inReviewTasks.length > 0 && (
            <section>
              <h3 className="text-lg font-bold font-syne mb-4 flex items-center gap-2 text-amber-500">
                <span className="w-2 h-6 rounded-full bg-amber-500" /> In Review
              </h3>
              <div className="flex flex-col gap-3">
                {inReviewTasks.map(task => (
                  <div key={task.id} onClick={() => setSelectedTaskId(task.id)} className="p-4 bg-surface rounded-xl border border-border flex justify-between items-center cursor-pointer hover:border-amber-500/50 transition">
                    <div>
                      <div className="text-sm font-bold text-text">{task.title}</div>
                      <div className="text-xs text-text-2 mt-1">Waiting for review &middot; 22h</div>
                    </div>
                    <ChevronRight size={16} className="text-text-3" />
                  </div>
                ))}
              </div>
            </section>
          )}

          {/* A6 Upcoming */}
          <section>
            <h3 className="text-lg font-bold font-syne mb-4 flex items-center gap-2">
              <span className="w-2 h-6 rounded-full bg-text-3" /> Upcoming
            </h3>
            <div className="flex flex-col gap-4">
              {upcomingTasks.map(task => (
                <div key={task.id} className="relative p-4 bg-surface rounded-xl border border-border opacity-75">
                  <div className="flex justify-between items-start">
                    <div>
                      <div className="text-sm font-bold text-text mb-1">{task.title}</div>
                      <div className="text-xs text-text-2">Deadline: {task.deadline ? new Date(task.deadline).toLocaleDateString() : 'None'}</div>
                    </div>
                  </div>
                  {task.status === 'blocked' && (
                    <div className="mt-3 bg-red-500/10 text-red-500 text-xs font-bold p-2 rounded flex items-center gap-2">
                      🔗 Blocked by [Dependencies] — you'll be notified
                    </div>
                  )}
                </div>
              ))}
              {upcomingTasks.length === 0 && <div className="text-sm text-text-3">No upcoming tasks assigned.</div>}
            </div>
          </section>

        </div>

        {/* A7 Right Rail */}
        <div className="lg:col-span-1 flex flex-col gap-6">

          <div className="p-5 bg-surface rounded-xl border border-border">
            <h4 className="text-sm font-bold uppercase tracking-wider text-text-2 mb-4">My Leave Balance</h4>
            <div className="grid grid-cols-3 gap-2 text-center">
              {(() => {
                const myLedger = (state.leaveLedger || []).filter((l: any) => l.userId === state.currentUserId);
                const el = myLedger.filter(l => l.leaveType === 'EL').reduce((s, l) => s + l.delta, 0);
                const cl = myLedger.filter(l => l.leaveType === 'CL').reduce((s, l) => s + l.delta, 0);
                const sl = myLedger.filter(l => l.leaveType === 'SL').reduce((s, l) => s + l.delta, 0);
                return (
                  <>
                    <div className="bg-surface-2 rounded p-2 border border-border">
                      <div className="text-xs text-text-3 mb-1">EL</div>
                      <div className="font-bold text-primary">{el}</div>
                    </div>
                    <div className="bg-surface-2 rounded p-2 border border-border">
                      <div className="text-xs text-text-3 mb-1">CL</div>
                      <div className="font-bold text-primary">{cl}</div>
                    </div>
                    <div className="bg-surface-2 rounded p-2 border border-border">
                      <div className="text-xs text-text-3 mb-1">SL</div>
                      <div className="font-bold text-primary">{sl}</div>
                    </div>
                  </>
                );
              })()}
            </div>
            <button className="w-full mt-4 bg-surface-2 hover:bg-surface-3 text-text font-bold py-2 rounded-lg transition border border-border text-sm">
              Apply for Leave
            </button>
          </div>

          <div className="p-5 bg-surface rounded-xl border border-border">
            <h4 className="text-sm font-bold uppercase tracking-wider text-text-2 mb-4">Quick Time Log</h4>
            <select className="w-full bg-surface-2 border border-border rounded-lg p-2.5 text-sm mb-3">
              <option value="">Select task...</option>
              {myTasks.map(t => <option key={t.id} value={t.id}>{t.title}</option>)}
            </select>
            <div className="flex gap-3 mb-3">
              <input type="number" placeholder="Hours" className="w-1/2 bg-surface-2 border border-border rounded-lg p-2.5 text-sm" />
              <input type="number" placeholder="Mins" className="w-1/2 bg-surface-2 border border-border rounded-lg p-2.5 text-sm" />
            </div>
            <button className="w-full bg-primary hover:bg-primary/90 text-white font-bold py-2.5 rounded-lg transition">Log Time</button>
          </div>

          <div className="p-5 bg-surface rounded-xl border border-border">
            <h4 className="text-sm font-bold uppercase tracking-wider text-text-2 mb-4">My Week</h4>
            <div className="flex items-end justify-between h-24 gap-1">
              {[4, 6, 8, 5, 0, 0, 0].map((h, i) => (
                <div key={i} className="flex flex-col items-center gap-2 flex-1">
                  <div className="w-full bg-surface-2 rounded-sm h-full relative flex items-end">
                    <div className="w-full bg-primary/60 rounded-sm" style={{ height: `${(h/8)*100}%` }} />
                  </div>
                  <span className="text-[10px] text-text-3 uppercase">{['M','T','W','T','F','S','S'][i]}</span>
                </div>
              ))}
            </div>
            <div className="mt-4 pt-4 border-t border-border flex justify-between items-center text-sm">
              <span className="text-text-2">Total Logged</span>
              <span className="font-bold text-text">23h / 40h</span>
            </div>
          </div>

          <div className="p-5 bg-surface rounded-xl border border-border">
            <h4 className="text-sm font-bold uppercase tracking-wider text-text-2 mb-4">Leave Balance</h4>
            <div className="flex justify-between mb-4">
              <div className="text-center"><div className="text-lg font-bold text-text">4</div><div className="text-[10px] text-text-2">EL</div></div>
              <div className="text-center"><div className="text-lg font-bold text-text">2</div><div className="text-[10px] text-text-2">CL</div></div>
              <div className="text-center"><div className="text-lg font-bold text-text">3</div><div className="text-[10px] text-text-2">SL</div></div>
            </div>
            <button className="w-full bg-surface-2 hover:bg-surface-3 text-text border border-border font-bold py-2.5 rounded-lg transition text-sm">Apply Leave</button>
          </div>

        </div>
      </div>

      <TaskDrawer taskId={selectedTaskId} onClose={() => setSelectedTaskId(null)} />
    </div>
  );
}

'use client';

import React from 'react';
import { useApp } from '@/contexts/AppContext';

export default function ApprovalsPage() {
  const { state, decideApproval } = useApp();

  const pendingApprovals = state.approvals.filter(a => a.status === 'pending');
  const pastApprovals = state.approvals.filter(a => a.status !== 'pending').sort((a, b) => new Date(b.decidedAt!).getTime() - new Date(a.decidedAt!).getTime());

  const renderApprovalCard = (approval: typeof state.approvals[0]) => {
    const requester = state.teamMembers.find(m => m.id === approval.requestedBy);
    const approver = state.teamMembers.find(m => m.id === approval.approverId);
    if (!requester) return null;

    let content = null;
    if (approval.kind === 'leave') {
      const { leaveType, startDate, endDate, days } = approval.contextJson;
      content = (
        <div>
          <span className="inline-block px-2 py-1 rounded text-xs font-bold bg-blue-500/10 text-blue-500 mb-2">Leave Request</span>
          <p className="text-sm font-medium mb-1">Requests {days} days of {leaveType}</p>
          <p className="text-xs text-text-3">{startDate} to {endDate}</p>
        </div>
      );
    } else if (approval.kind === 'task_review') {
      const task = state.tasks.find(t => t.id === approval.refId);
      content = (
        <div>
          <span className="inline-block px-2 py-1 rounded text-xs font-bold bg-amber-500/10 text-amber-500 mb-2">Task Review</span>
          <p className="text-sm font-medium mb-1 truncate">{task?.title || 'Unknown Task'}</p>
          <p className="text-xs text-text-3">Submitted for final review</p>
        </div>
      );
    } else {
      content = (
        <div>
          <span className="inline-block px-2 py-1 rounded text-xs font-bold bg-surface-3 text-text-2 mb-2">{approval.kind}</span>
          <p className="text-sm">Action required</p>
        </div>
      );
    }

    return (
      <div key={approval.id} className={`bg-surface rounded-xl border p-5 ${approval.status === 'pending' ? 'border-border hover:border-primary/50' : 'border-surface-2 opacity-70'} transition`}>
        <div className="flex items-center mb-4 pb-4 border-b border-border">
          <div className="w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold text-white mr-3 shrink-0" style={{ backgroundColor: requester.color }}>
            {requester.initials}
          </div>
          <div>
            <div className="font-semibold text-sm">{requester.name}</div>
            <div className="text-xs text-text-3">{new Date(approval.createdAt).toLocaleDateString()}</div>
          </div>
        </div>

        <div className="mb-6">
          {content}
        </div>

        {approval.status === 'pending' ? (
          <div className="flex gap-2 mt-auto">
            <button 
              onClick={() => decideApproval(approval.id, 'approved', 'Approved from inbox')}
              className="flex-1 bg-primary text-bg font-bold text-sm py-2 rounded hover:bg-primary/90 transition"
            >
              Approve
            </button>
            <button 
              onClick={() => decideApproval(approval.id, 'rejected', 'Rejected from inbox')}
              className="flex-1 bg-surface-2 text-text font-bold text-sm py-2 rounded hover:bg-surface-3 transition"
            >
              Reject
            </button>
          </div>
        ) : (
          <div className="mt-auto">
            <div className={`text-xs font-bold px-2 py-1.5 rounded inline-block ${approval.status === 'approved' ? 'bg-emerald-500/10 text-emerald-500' : 'bg-red-500/10 text-red-500'}`}>
              {approval.status.toUpperCase()} by {approver?.name || 'Unknown'}
            </div>
            {approval.decisionNote && <p className="text-xs text-text-3 mt-2">Note: {approval.decisionNote}</p>}
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="flex flex-col h-full bg-bg text-text">
      <header className="px-8 py-6 border-b border-border flex justify-between items-center bg-surface sticky top-0 z-10">
        <div>
          <h1 className="text-2xl font-bold tracking-tight mb-1" style={{ fontFamily: 'var(--font-syne-var)' }}>
            Unified Approvals
          </h1>
          <p className="text-text-3 text-sm">Inbox zero for managers</p>
        </div>
      </header>

      <div className="flex-1 overflow-auto p-8 space-y-12">
        <div>
          <h2 className="text-lg font-bold mb-4 flex items-center">
            Pending Actions
            <span className="ml-3 bg-amber-500 text-bg text-xs font-bold px-2 py-0.5 rounded-full">{pendingApprovals.length}</span>
          </h2>
          {pendingApprovals.length === 0 ? (
            <div className="p-8 text-center text-text-3 border border-dashed border-border rounded-xl">You're all caught up!</div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
              {pendingApprovals.map(renderApprovalCard)}
            </div>
          )}
        </div>

        <div>
          <h2 className="text-lg font-bold mb-4 text-text-2">Recent Decisions</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
            {pastApprovals.slice(0, 10).map(renderApprovalCard)}
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useMemo } from 'react';
import Link from 'next/link';
import { useApp } from '@/contexts/AppContext';
import { FunnelItem } from '@/lib/data';

export default function SalesOverviewPage() {
  const { state } = useApp();
  const deals = (state.deals || []) as FunnelItem[];

  // Compute KPIs
  const { totalPipelineValue, closedWonValue, winRate, activeDealsCount } = useMemo(() => {
    let totalPipelineValue = 0;
    let closedWonValue = 0;
    let wonCount = 0;
    let closedCount = 0;
    let activeDealsCount = 0;

    deals.forEach((deal: any) => {
      const value = deal.dealValueINR || deal.value || 0;
      if (deal.stage === 'won') {
        closedWonValue += value;
        wonCount++;
        closedCount++;
      } else if (deal.stage === 'lost') {
        closedCount++;
      } else {
        totalPipelineValue += value;
        activeDealsCount++;
      }
    });

    const winRate = closedCount > 0 ? (wonCount / closedCount) * 100 : 0;

    return { totalPipelineValue, closedWonValue, winRate, activeDealsCount };
  }, [deals]);

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR',
      maximumFractionDigits: 0
    }).format(value);
  };

  const STAGES = ['lead', 'contacted', 'proposal', 'negotiation', 'won', 'lost'];

  // Compute chart data
  const stageData = useMemo(() => {
    const data: Record<string, { count: number; value: number }> = {};
    STAGES.forEach(s => data[s] = { count: 0, value: 0 });
    deals.forEach((deal: any) => {
      const s = deal.stage?.toLowerCase() || 'lead';
      const value = deal.dealValueINR || deal.value || 0;
      if (data[s]) {
        data[s].count += 1;
        data[s].value += value;
      } else {
        data[s] = { count: 1, value };
      }
    });
    return data;
  }, [deals]);

  const maxStageValue = Math.max(...Object.values(stageData).map(d => d.value), 1);
  const maxStageCount = Math.max(...Object.values(stageData).map(d => d.count), 1);

  // Revenue Trend Data
  const trendData = useMemo(() => {
    const sorted = [...deals]
      .filter((d: any) => d.createdAt)
      .sort((a: any, b: any) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime());

    let cumulative = 0;
    const points: { label: string; value: number }[] = [];

    sorted.forEach((d: any) => {
      cumulative += (d.dealValueINR || d.value || 0);
      points.push({
        label: new Date(d.createdAt).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
        value: cumulative
      });
    });

    // Fallback if not enough data
    if (points.length < 2) {
      return [
        { label: 'Jan', value: 120000 },
        { label: 'Feb', value: 180000 },
        { label: 'Mar', value: 150000 },
        { label: 'Apr', value: 320000 },
        { label: 'May', value: 280000 },
        { label: 'Jun', value: 450000 },
      ];
    }
    return points;
  }, [deals]);

  const maxTrendValue = Math.max(...trendData.map(d => d.value), 1);

  // Top Deals
  const topDeals = useMemo(() => {
    return deals
      .filter((d: any) => d.stage !== 'won' && d.stage !== 'lost' && (d.probability || 0) > 70)
      .sort((a: any, b: any) => {
        const valB = b.dealValueINR || b.value || 0;
        const valA = a.dealValueINR || a.value || 0;
        return valB - valA;
      })
      .slice(0, 5);
  }, [deals]);

  // Recent Deals
  const recentDeals = useMemo(() => {
    return [...deals]
      .sort((a: any, b: any) => {
        const dateA = a.createdAt ? new Date(a.createdAt).getTime() : 0;
        const dateB = b.createdAt ? new Date(b.createdAt).getTime() : 0;
        return dateB - dateA;
      })
      .slice(0, 8);
  }, [deals]);

  const getStageColor = (stage: string) => {
    switch (stage?.toLowerCase()) {
      case 'won': return '#2AB182';
      case 'lost': return '#EF4444';
      case 'negotiation': return '#F59E0B';
      case 'proposal': return '#3B82F6';
      case 'contacted': return '#8B5CF6';
      default: return '#6B7280';
    }
  };

  return (
    <div className="p-6 md:p-8 space-y-8" style={{ backgroundColor: 'var(--c-bg)', color: 'var(--c-text)', minHeight: '100vh' }}>

      {/* Header */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-2xl md:text-3xl font-bold">Sales Overview</h1>
          <p style={{ color: 'var(--c-text-2)' }} className="text-sm mt-1">Track pipeline health and deal velocity.</p>
        </div>
        <div className="flex items-center gap-3">
          <Link 
            href="/sales/pipeline"
            className="px-4 py-2 rounded-lg text-sm font-medium transition-colors border"
            style={{ 
              backgroundColor: 'var(--c-surface)', 
              borderColor: 'var(--c-border)', 
              color: 'var(--c-text)'
            }}
          >
            Go to Pipeline
          </Link>
          <button 
            className="px-4 py-2 rounded-lg text-sm font-medium text-white transition-opacity hover:opacity-90 shadow-lg shadow-[#0EA5E9]/20"
            style={{ backgroundColor: '#0EA5E9' }}
          >
            New Deal
          </button>
        </div>
      </div>

      {/* KPI Strip */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="p-5 rounded-xl border flex flex-col gap-1 transition-all hover:scale-[1.02]" style={{ backgroundColor: 'var(--c-surface)', borderColor: 'var(--c-border)' }}>
          <span style={{ color: 'var(--c-text-2)' }} className="text-xs font-semibold uppercase tracking-wider">Total Pipeline</span>
          <span className="text-2xl font-bold">{formatCurrency(totalPipelineValue)}</span>
        </div>
        <div className="p-5 rounded-xl border flex flex-col gap-1 transition-all hover:scale-[1.02]" style={{ backgroundColor: 'var(--c-surface)', borderColor: 'var(--c-border)' }}>
          <span style={{ color: 'var(--c-text-2)' }} className="text-xs font-semibold uppercase tracking-wider">Closed Won</span>
          <span className="text-2xl font-bold text-[#2AB182]">{formatCurrency(closedWonValue)}</span>
        </div>
        <div className="p-5 rounded-xl border flex flex-col gap-1 transition-all hover:scale-[1.02]" style={{ backgroundColor: 'var(--c-surface)', borderColor: 'var(--c-border)' }}>
          <span style={{ color: 'var(--c-text-2)' }} className="text-xs font-semibold uppercase tracking-wider">Win Rate</span>
          <span className="text-2xl font-bold">{winRate.toFixed(1)}%</span>
        </div>
        <div className="p-5 rounded-xl border flex flex-col gap-1 transition-all hover:scale-[1.02]" style={{ backgroundColor: 'var(--c-surface)', borderColor: 'var(--c-border)' }}>
          <span style={{ color: 'var(--c-text-2)' }} className="text-xs font-semibold uppercase tracking-wider">Active Deals</span>
          <span className="text-2xl font-bold">{activeDealsCount}</span>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">

        {/* Pipeline Trend Chart (SVG) */}
        <div className="p-6 rounded-xl border flex flex-col" style={{ backgroundColor: 'var(--c-surface)', borderColor: 'var(--c-border)' }}>
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-lg font-semibold">Revenue Trend</h2>
            <div className="flex items-center gap-2 text-xs font-medium" style={{ color: 'var(--c-text-2)' }}>
              <div className="w-2.5 h-2.5 rounded-full" style={{backgroundColor: '#0EA5E9'}}></div> Cumulative Value
            </div>
          </div>

          <div className="flex-1 relative w-full min-h-[220px] mt-4">
            <svg viewBox="0 0 400 200" className="w-full h-full overflow-visible" preserveAspectRatio="none">
              {/* Grid lines */}
              {[0, 1, 2, 3, 4].map(i => (
                <line 
                  key={`grid-${i}`} 
                  x1="0" y1={i * 50} x2="400" y2={i * 50} 
                  stroke="currentColor" strokeOpacity="0.05" strokeWidth="1" 
                />
              ))}

              {/* Path */}
              <path
                d={`M ${trendData.map((d, i) => {
                  const x = (i / Math.max(trendData.length - 1, 1)) * 400;
                  const y = 200 - ((d.value / maxTrendValue) * 200);
                  return `${x},${y}`;
                }).join(' L ')}`}
                fill="none"
                stroke="#0EA5E9"
                strokeWidth="3"
                strokeLinecap="round"
                strokeLinejoin="round"
                className="drop-shadow-md"
              />

              {/* Gradient Fill under path */}
              <path
                d={`M 0,200 L ${trendData.map((d, i) => {
                  const x = (i / Math.max(trendData.length - 1, 1)) * 400;
                  const y = 200 - ((d.value / maxTrendValue) * 200);
                  return `${x},${y}`;
                }).join(' L ')} L 400,200 Z`}
                fill="url(#trendGradient)"
                opacity="0.2"
              />

              <defs>
                <linearGradient id="trendGradient" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stopColor="#0EA5E9" stopOpacity="1" />
                  <stop offset="100%" stopColor="#0EA5E9" stopOpacity="0" />
                </linearGradient>
              </defs>

              {/* Data points */}
              {trendData.map((d, i) => {
                const x = (i / Math.max(trendData.length - 1, 1)) * 400;
                const y = 200 - ((d.value / maxTrendValue) * 200);
                return (
                  <circle key={`pt-${i}`} cx={x} cy={y} r="4" fill="#0EA5E9" stroke="var(--c-surface)" strokeWidth="2" />
                );
