            </svg>

            {/* X-axis labels */}
            <div className="flex justify-between mt-4 text-[10px] uppercase font-bold" style={{ color: 'var(--c-text-3)' }}>
              {trendData.map((d, i) => {
                if (trendData.length > 6 && i % Math.ceil(trendData.length / 5) !== 0 && i !== trendData.length - 1) return <span key={i} className="opacity-0 w-0">{d.label}</span>;
                return <span key={i}>{d.label}</span>;
              })}
            </div>
          </div>
