                No hot leads (probability &gt; 70%) found in active pipeline.
              </div>
            )}
          </div>
        </div>

      {/* Recent Deals Table */}
      <div className="lg:col-span-2 rounded-xl border flex flex-col overflow-hidden shadow-sm" style={{ backgroundColor: 'var(--c-surface)', borderColor: 'var(--c-border)' }}>
