              </tr>
            </thead>
            <tbody className="divide-y" style={{ borderColor: 'var(--c-border)' }}>
              {recentDeals.length > 0 ? recentDeals.map((deal: any, i: number) => {
                const value = deal.dealValueINR || deal.value || 0;
                return (
