'use client';

import React, { useState } from 'react';
import { useAuth } from '@/contexts/AuthContext';

const ACCOUNTS = [
  { name: 'Sushil Athithiyaa', role: 'CEO / Admin', email: 'sushil@invictus.com', color: '#8B5CF6' },
  { name: 'Anitha Yogan', role: 'COO / Operations', email: 'contact@invictusglobaltech.com', color: '#F59E0B' },
  { name: 'Karan K', role: 'Sales Lead', email: 'karan@invictus.com', color: '#10B981' },
  { name: 'Abhilash B Nair', role: 'Lead Developer', email: 'connect@invictusglobaltech.com', color: '#3B82F6' },
];

export default function LoginPage() {
  const [error, setError] = useState('');
  const [loadingEmail, setLoadingEmail] = useState('');
  const { login } = useAuth();

  const handleQuickLogin = async (email: string) => {
    setError('');
    setLoadingEmail(email);

    try {
      const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL || 'http://localhost:4000'}/api/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password: 'password123' }), // Using the seeded password for all users
      });
      const data = await res.json();

      if (data.token) {
        login(data.token, data.user);
      } else {
        setError(data.error || 'Invalid credentials');
      }
    } catch (err: any) {
      setError('Could not connect to the server');
    } finally {
      setLoadingEmail('');
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-[#0a0a0a] text-white">
      <div className="w-full max-w-md p-8 rounded-xl border border-[#2a2a2a] bg-[#111111] shadow-2xl">
        <h1 className="text-3xl font-bold mb-2 tracking-tight text-center">IGT OS</h1>
        <p className="text-[#888888] text-center mb-8">Select an account to log in</p>

        {error && (
          <div className="mb-6 p-3 rounded bg-red-950/50 border border-red-900/50 text-red-500 text-sm">
            {error}
          </div>
        )}

        <div className="space-y-3">
          {ACCOUNTS.map(account => (
            <button
              key={account.email}
              onClick={() => handleQuickLogin(account.email)}
              disabled={!!loadingEmail}
              className={`w-full flex items-center gap-4 p-4 rounded-xl border border-[#222222] bg-[#1a1a1a] hover:bg-[#222222] transition-colors ${loadingEmail === account.email ? 'opacity-70' : ''}`}
            >
              <div 
                className="w-10 h-10 rounded-full flex items-center justify-center font-bold text-white shadow-sm"
                style={{ backgroundColor: account.color }}
              >
                {account.name.charAt(0)}
              </div>
              <div className="text-left flex-1">
                <div className="font-medium text-[15px]">{account.name}</div>
                <div className="text-[#888888] text-xs mt-0.5">{account.role}</div>
              </div>
              {loadingEmail === account.email && (
                <div className="w-5 h-5 border-2 border-white/20 border-t-white rounded-full animate-spin" />
              )}
            </button>
          ))}
        </div>

        <div className="mt-8 text-center text-xs text-[#555555]">
          Bypassing manual entry for development preview.
        </div>
      </div>
    </div>
  );
}

