'use client';

import { useApp } from '@/contexts/AppContext';
import { useEffect, useState } from 'react';

export default function CampaignDrawer({ campaignId, onClose }: { campaignId: string, onClose: () => void }) {
  const { state } = useApp();
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
    document.body.style.overflow = 'hidden';
    return () => {
      document.body.style.overflow = '';
    };
  }, []);

  const campaign = state.campaigns.find(c => c.id === campaignId);

  if (!campaign) return null;

  const getStatusBadge = (status: string) => {
    switch(status) {
      case 'live': return <span className="text-emerald-500 bg-emerald-500/10 px-2 py-0.5 rounded text-xs font-bold">🟢 Live since {new Date(campaign.startDate).toLocaleDateString(undefined, {month:'short', day:'numeric'})}</span>;
      case 'paused': return <span className="text-amber-500 bg-amber-500/10 px-2 py-0.5 rounded text-xs font-bold">🟡 Paused</span>;
      case 'pending': return <span className="text-[var(--c-text-2)] bg-[var(--c-surface-3)] px-2 py-0.5 rounded text-xs font-bold">⏳ Pending</span>;
      case 'problem': return <span className="text-red-500 bg-red-500/10 px-2 py-0.5 rounded text-xs font-bold">🔴 Problem</span>;
      default: return <span className="text-[var(--c-text-2)] bg-[var(--c-surface-3)] px-2 py-0.5 rounded text-xs font-bold">⚫ Ended</span>;
    }
  };

  const assignees = campaign.assignedTo.map(id => state.teamMembers.find(m => m.id === id)?.name || id).join(' · ');

  // Compute logs
  const logs = campaign.weeklyLogs.map(id => state.campaignLogs2.find(l => l.id === id)).filter(Boolean) as any[];
  const currentMonthLogs = logs; // Mocking as if all logs are current month for simplicity
  const totalLeads = currentMonthLogs.reduce((sum, l) => sum + l.leads, 0);
  const totalSpend = currentMonthLogs.reduce((sum, l) => sum + l.spendINR, 0);
  const totalImpressions = currentMonthLogs.reduce((sum, l) => sum + l.impressions, 0);
  const totalClicks = currentMonthLogs.reduce((sum, l) => sum + l.clicks, 0);
  const avgCpl = totalLeads > 0 ? Math.round(totalSpend / totalLeads) : 0;
  const ctr = totalImpressions > 0 ? ((totalClicks / totalImpressions) * 100).toFixed(2) : '0';

  return (
    <>
      {/* Backdrop */}
      <div 
        className={`fixed inset-0 bg-black/40 backdrop-blur-sm z-50 transition-opacity duration-300 ${mounted ? 'opacity-100' : 'opacity-0'}`} 
        onClick={onClose} 
      />

      {/* Drawer */}
      <div 
        className={`fixed right-0 top-0 h-full w-full max-w-lg bg-[var(--c-bg)] border-l border-[var(--c-border)] z-50 flex flex-col shadow-2xl transition-transform duration-300 transform ${mounted ? 'translate-x-0' : 'translate-x-full'}`}
      >
        <div className="flex items-center justify-between p-4 border-b border-[var(--c-border)]">
          <div>
            <div className="text-xs font-semibold text-[var(--c-text-2)] uppercase tracking-wider mb-1">Campaign Detail</div>
            <h2 className="text-xl font-bold text-[var(--c-text)]">{campaign.name}</h2>
          </div>
          <button 
            onClick={onClose}
            className="p-2 bg-[var(--c-surface)] hover:bg-[var(--c-surface-3)] rounded-full transition-colors border border-[var(--c-border)]"
          >
            ✕
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-8 custom-scrollbar">

          {/* Metadata */}
          <div className="space-y-3 text-sm">
            <div className="flex"><span className="w-32 font-semibold text-[var(--c-text-2)]">STATUS:</span> {getStatusBadge(campaign.status)}</div>
            <div className="flex"><span className="w-32 font-semibold text-[var(--c-text-2)]">ASSIGNED TO:</span> <span className="font-medium">{assignees}</span></div>
            <div className="flex"><span className="w-32 font-semibold text-[var(--c-text-2)]">OBJECTIVE:</span> <span className="capitalize">{campaign.objective.replace('_', ' ')}</span></div>
            <div className="flex"><span className="w-32 font-semibold text-[var(--c-text-2)]">AD ACCOUNT:</span> <span className="text-blue-500 hover:underline cursor-pointer">{campaign.adAccountId} ↗</span></div>
            {campaign.landingPageUrl && (
              <div className="flex"><span className="w-32 font-semibold text-[var(--c-text-2)]">LANDING PAGE:</span> <span className="text-blue-500 hover:underline cursor-pointer">{campaign.landingPageUrl} ↗</span></div>
            )}
          </div>

          {/* Budget */}
          <div>
            <h3 className="font-bold text-[var(--c-text)] border-b border-[var(--c-border)] pb-2 mb-3">BUDGET</h3>
            <div className="bg-[var(--c-surface-2)] p-4 rounded-xl border border-[var(--c-border)] space-y-2 text-sm">
              <div className="flex justify-between"><span className="text-[var(--c-text-2)] font-medium">Monthly budget:</span> <span className="font-bold">₹{campaign.monthlyBudgetINR.toLocaleString()}</span></div>
              <div className="flex justify-between"><span className="text-[var(--c-text-2)] font-medium">Spent to date:</span> <span className="font-bold">₹{totalSpend.toLocaleString()}</span></div>
              <div className="flex justify-between"><span className="text-[var(--c-text-2)] font-medium">Projected end:</span> <span className="text-emerald-500 font-bold">₹{campaign.monthlyBudgetINR.toLocaleString()} ✅</span></div>
            </div>
          </div>

          {/* Performance */}
          <div>
            <h3 className="font-bold text-[var(--c-text)] border-b border-[var(--c-border)] pb-2 mb-3">PERFORMANCE — THIS MONTH</h3>
            <div className="grid grid-cols-2 gap-3 mb-4">
              <div className="bg-[var(--c-surface)] border border-[var(--c-border)] p-3 rounded-lg">
                <div className="text-[10px] uppercase font-bold text-[var(--c-text-2)]">Impressions</div>
                <div className="text-lg font-bold">{totalImpressions.toLocaleString()}</div>
              </div>
              <div className="bg-[var(--c-surface)] border border-[var(--c-border)] p-3 rounded-lg">
                <div className="text-[10px] uppercase font-bold text-[var(--c-text-2)]">Clicks</div>
                <div className="text-lg font-bold">{totalClicks.toLocaleString()} <span className="text-xs text-[var(--c-text-2)] font-normal ml-1">({ctr}%)</span></div>
              </div>
              <div className="bg-[var(--c-surface)] border border-[var(--c-border)] p-3 rounded-lg">
                <div className="text-[10px] uppercase font-bold text-[var(--c-text-2)]">Leads</div>
                <div className="text-lg font-bold">{totalLeads}</div>
              </div>
              <div className="bg-[var(--c-surface)] border border-[var(--c-border)] p-3 rounded-lg">
                <div className="text-[10px] uppercase font-bold text-[var(--c-text-2)]">Avg CPL</div>
                <div className="text-lg font-bold">₹{avgCpl}</div>
              </div>
            </div>
            <div className="text-sm bg-blue-500/10 p-3 rounded-lg text-blue-400 border border-blue-500/20">
              <strong>vs benchmark:</strong> CPL ₹{avgCpl} vs target ₹450 — {avgCpl > 450 ? '🟡 slightly above target' : '✅ on track'}
            </div>
          </div>

          {/* Weekly Trend */}
          <div>
            <h3 className="font-bold text-[var(--c-text)] border-b border-[var(--c-border)] pb-2 mb-3">WEEKLY TREND (Last 4 weeks)</h3>
            <div className="space-y-2">
              {logs.length > 0 ? logs.map((l, i) => (
                <div key={l.id} className="flex justify-between items-center text-sm p-2 bg-[var(--c-surface)] border border-[var(--c-border)] rounded">
                  <span className="font-medium text-[var(--c-text-2)]">Wk{i+1}:</span>
                  <span>{l.leads} leads <span className="text-[var(--c-text-2)] opacity-50 mx-1">·</span> ₹{l.leads > 0 ? Math.round(l.spendINR / l.leads) : 0} CPL</span>
                </div>
              )) : (
                <div className="text-sm text-[var(--c-text-2)]">No data logged yet.</div>
              )}
            </div>
          </div>

          {/* Linked Tasks */}
          {campaign.creativeTaskIds.length > 0 && (
            <div>
              <h3 className="font-bold text-[var(--c-text)] border-b border-[var(--c-border)] pb-2 mb-3">LINKED TASKS</h3>
              <div className="space-y-2">
                {campaign.creativeTaskIds.map(taskId => {
                  const t = state.tasks.find(tk => tk.id === taskId);
                  if (!t) return null;
                  return (
                    <div key={taskId} className="flex justify-between text-sm bg-[var(--c-surface)] border border-[var(--c-border)] p-2 rounded items-center">
                      <span className="text-blue-500 font-medium truncate pr-2 max-w-[200px]">{t.id} {t.title}</span>
                      <span className="text-xs bg-[var(--c-surface-3)] px-2 py-0.5 rounded capitalize">{t.status.replace('_',' ')}</span>
                    </div>
                  );
                })}
              </div>
            </div>
          )}

          {/* Notes */}
          <div>
            <h3 className="font-bold text-[var(--c-text)] border-b border-[var(--c-border)] pb-2 mb-3">NOTES</h3>
            <div className="text-sm text-[var(--c-text-2)] leading-relaxed whitespace-pre-wrap bg-[var(--c-surface-2)] p-4 rounded-xl border border-[var(--c-border)]">
              {campaign.notes || 'No notes added.'}
            </div>
          </div>

        </div>
      </div>
    </>
  );
}

import React, { useEffect, useState } from 'react';
import { useApp } from '@/contexts/AppContext';
import { fetchGoogleCalendarEvents, GoogleEvent } from '@/lib/googleCalendar';
import { Task } from '@/lib/data';
import { GripVertical } from 'lucide-react';

export default function CalendarMiniWidget({ 
  activeTasks, 
  setSelectedDate 
}: { 
  activeTasks: Task[],
  setSelectedDate: (d: Date) => void 
}) {
  const { state, dispatch } = useApp();
  const [calendarWeeks, setCalendarWeeks] = useState(2);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    async function loadEvents() {
      if (!state.googleAccessToken) return;
      setLoading(true);
      const minDate = new Date();
      const maxDate = new Date();
      maxDate.setDate(maxDate.getDate() + 30);
      const events = await fetchGoogleCalendarEvents(state.googleAccessToken, minDate.toISOString(), maxDate.toISOString());
      dispatch({ type: 'SET_GOOGLE_EVENTS', payload: events });
      setLoading(false);
    }
    loadEvents();
  }, [state.googleAccessToken, dispatch]);

  return (
    <>
      <div className="p-4 border-b border-app-border flex flex-col sm:flex-row justify-between items-center gap-4 bg-app-surface rounded-t-xl">
        <div className="flex items-center gap-3">
          <GripVertical className="w-5 h-5 text-app-text3 cursor-grab hover:text-app-text" />
          <h3 className="text-lg font-bold text-app-text">Calendar Overview</h3>
        </div>
        <div className="flex bg-surface-2 p-1 rounded-lg border border-border">
          <button 
            onClick={() => setCalendarWeeks(1)}
            className={`px-3 py-1 rounded text-[11px] font-bold ${calendarWeeks === 1 ? 'bg-surface text-text shadow-sm' : 'text-text-2 hover:text-text'}`}
          >1 Week</button>
          <button 
            onClick={() => setCalendarWeeks(2)}
            className={`px-3 py-1 rounded text-[11px] font-bold ${calendarWeeks === 2 ? 'bg-surface text-text shadow-sm' : 'text-text-2 hover:text-text'}`}
          >2 Weeks</button>
          <button 
            onClick={() => setCalendarWeeks(4)}
            className={`px-3 py-1 rounded text-[11px] font-bold ${calendarWeeks === 4 ? 'bg-surface text-text shadow-sm' : 'text-text-2 hover:text-text'}`}
          >4 Weeks</button>
        </div>
      </div>
      <div className="p-4 bg-surface-2">
        <div className="grid grid-cols-7 gap-2">
          {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(day => (
            <div key={day} className="text-center font-bold text-[12px] text-text-3 uppercase tracking-wider mb-2">{day}</div>
          ))}
          {Array.from({ length: calendarWeeks * 7 }).map((_, i) => {
            const d = new Date();
            d.setDate(d.getDate() - d.getDay() + i); 
            const dateStr = d.toISOString().split('T')[0];
            const dayTasks = activeTasks.filter(t => t.deadline && t.deadline.startsWith(dateStr));
            const dayEvents = state.googleEvents.filter(e => e.start.dateTime.startsWith(dateStr));
            const isToday = dateStr === new Date().toISOString().split('T')[0];

            return (
              <div 
                key={i} 
                className={`min-h-[90px] flex flex-col p-2 rounded-lg border cursor-pointer hover:bg-app-hover transition-colors ${isToday ? 'border-primary bg-primary/5 shadow-sm' : 'border-border bg-surface'}`}
                onClick={() => setSelectedDate(d)}
              >
                <div className={`text-[12px] font-bold mb-1 ${isToday ? 'text-primary' : 'text-text-2'}`}>{d.getDate()}</div>
                <div className="flex flex-col gap-1 flex-1 overflow-hidden">

                  {/* Events */}
                  {dayEvents.slice(0, 2).map(evt => (
                    <div 
                      key={evt.id} 
                      className="text-[9px] font-bold truncate px-1.5 py-0.5 rounded cursor-pointer hover:opacity-80 transition-opacity"
                      style={{ background: 'rgba(66, 133, 244, 0.15)', color: '#4285F4' }}
                      title={evt.summary}
                    >
                      {evt.summary}
                    </div>
                  ))}

                  {/* Tasks */}
                  {dayTasks.slice(0, Math.max(0, 3 - dayEvents.slice(0,2).length)).map(t => {
                    const primaryAssignee = state.teamMembers.find(m => t.assignedTo.includes(m.id));
                    const memberColor = primaryAssignee?.color || '#2AB182';
                    const client = state.clients.find(c => c.id === t.clientId);
                    const clientColor = client?.color || '#64748B';
                    return (
                      <div 
                        key={t.id} 
                        className="text-[9px] font-bold truncate pl-2 pr-1.5 py-0.5 rounded-r cursor-pointer hover:opacity-80 transition-opacity relative overflow-hidden"
                        style={{ 
                          background: t.status === 'done' ? 'transparent' : `${clientColor}18`,
                          borderLeft: `2.5px solid ${t.status === 'done' ? 'var(--c-border)' : memberColor}`,
                          color: t.status === 'done' ? 'var(--c-text-3)' : 'var(--c-text)',
                        }}
                        title={`${t.title} · ${primaryAssignee?.name || 'Unassigned'} · ${client?.name || ''}`}
                      >
                        {t.title}
                      </div>
                    );
                  })}

                  {(dayEvents.length + dayTasks.length) > 3 && (
                    <div className="text-[9px] font-medium text-text-3 pl-1">
                      +{(dayEvents.length + dayTasks.length) - 3} more
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </>
  );
}

import Link from 'next/link';

interface CampaignCardProps {
  id: string;
  clientCode: string;
  clientName: string;
  channelName: string;
  status: 'LIVE' | 'PROOF WINDOW' | 'NEEDS ATTENTION' | 'PAUSED';
  weekSpend: number;
  budget: number;
  weekLeads: number;
  cpl: number;
  targetCpl?: number;
  lastOptimized: string;
  trend?: {
    value: number; // e.g. 8 for +8%, -5 for -5%
    label: string; // e.g. "vs last week"
  };
  proofDeadline?: string;
  reminderText?: string;
  onLogNumbers?: () => void;
  onOptimize?: () => void;
  onOpen?: () => void;
}

export function CampaignCard(props: CampaignCardProps) {
  const isNeedsAttention = props.status === 'NEEDS ATTENTION';
  const isProofWindow = props.status === 'PROOF WINDOW';

  const statusColor = 
    props.status === 'LIVE' ? 'text-emerald-500' :
    props.status === 'PROOF WINDOW' ? 'text-red-500' :
    props.status === 'NEEDS ATTENTION' ? 'text-amber-500' :
    'text-slate-500';

  const cardBorder = 
    isNeedsAttention ? 'border-amber-500' :
    isProofWindow ? 'border-red-500' :
    'border-[var(--c-border)]';

  return (
    <div className={`w-full bg-[var(--c-surface)] border ${cardBorder} rounded-xl p-5 mb-4`}>
      <div className="flex items-center justify-between mb-4">
        <h4 className="font-bold text-[var(--c-text)]">
          <span className="text-[var(--c-text-3)] font-mono text-xs mr-2">[{props.clientCode}]</span>
          {props.clientName} — {props.channelName}
        </h4>
        <div className={`flex items-center gap-1.5 text-xs font-bold ${statusColor}`}>
          <span className="text-[10px]">●</span>
          {props.status}
        </div>
      </div>

      {!isNeedsAttention ? (
        <div className="space-y-2 text-sm text-[var(--c-text-2)]">
          <div className="flex items-center justify-between">
            <span>Week spend: ₹{props.weekSpend.toLocaleString()} / ₹{props.budget.toLocaleString()} budget</span>
            {props.weekSpend <= props.budget ? (
              <span className="text-emerald-500 font-bold">✅ Pacing OK</span>
            ) : (
              <span className="text-red-500 font-bold">⚠ Over pacing</span>
            )}
          </div>

          <div className="flex items-center gap-2">
            <span>Week leads: {props.weekLeads}</span>
            <span className="text-[var(--c-border)]">|</span>
            <span>CPL ₹{props.cpl.toLocaleString()}</span>

            {props.targetCpl && props.cpl > props.targetCpl && (
              <>
                <span className="text-[var(--c-border)]">|</span>
                <span className="text-amber-500 font-bold">Target: ₹{props.targetCpl} ⚠</span>
              </>
            )}

            {props.trend && (
              <>
                <span className="text-[var(--c-border)]">|</span>
                <span className={props.trend.value > 0 ? 'text-red-500' : 'text-emerald-500'}>
                  {props.trend.value > 0 ? '▲' : '▼'} {props.trend.value > 0 ? '+' : ''}{props.trend.value}%
                </span>
                <span className="text-xs">{props.trend.label}</span>
              </>
            )}
          </div>

          <div className="flex items-center justify-between mt-4 pt-4 border-t border-[var(--c-border)]">
            {isProofWindow && props.proofDeadline ? (
              <span className="text-red-500 font-bold">
                ⏰ Proof deadline: {props.proofDeadline}
              </span>
            ) : (
              <span>Last optimized: {props.lastOptimized}</span>
            )}

            <button 
              onClick={isProofWindow ? props.onOptimize : props.onLogNumbers}
              className="text-[var(--c-primary)] font-bold text-xs hover:underline"
            >
              {isProofWindow ? '[Optimize Now →]' : '[Log Numbers →]'}
            </button>
          </div>
        </div>
      ) : (
        <div className="space-y-2 text-sm text-[var(--c-text-2)]">
          <div>Last optimized: {props.lastOptimized}</div>
          <div className="text-amber-500 font-medium">Reminder: {props.reminderText || 'Campaign needs attention'}</div>
          <div className="flex justify-end mt-2">
            <button 
              onClick={props.onOpen}
              className="text-amber-600 font-bold text-xs hover:underline"
            >
              [Open →]
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState, useMemo, useEffect } from 'react';
import { useApp } from '@/contexts/AppContext';
import TaskDrawer from '@/components/tasks/TaskDrawer';
import NewTaskModal from '@/components/tasks/NewTaskModal';
import { Task } from '@/lib/data';
import { RefreshCw } from 'lucide-react';

const FILTER_OPTIONS = [
  { label: 'Today', days: 1 },
  { label: '2 Days', days: 2 },
  { label: '3 Days', days: 3 },
  { label: '7 Days', days: 7 },
  { label: '30 Days', days: 30 },
  { label: 'All Time', days: -1 },
];

export default function LeadershipPanel() {
  const { state } = useApp();
  const allTasks = (state.tasks || []) as Task[];

  const [filterDays, setFilterDays] = useState(7);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [selectedTaskId, setSelectedTaskId] = useState<string | null>(null);

  const handleRefresh = () => {
    setIsRefreshing(true);
    setTimeout(() => setIsRefreshing(false), 500);
  };

  const todayStr = new Date().toLocaleDateString('en-US', {
    weekday: 'long',
    month: 'long',
    day: 'numeric',
    year: 'numeric'
  });

  const filteredTasks = useMemo(() => {
    if (filterDays === -1) return allTasks;
    const now = new Date();
    // Normalize to the start of the cut-off day
    const cutoffDate = new Date(now.getFullYear(), now.getMonth(), now.getDate() - filterDays + 1);

    return allTasks.filter(t => {
      // @ts-ignore - gracefully handle variations in data structure
      const dateStr = t.createdAt || t.deadline || new Date().toISOString();
      return new Date(dateStr) >= cutoffDate;
    });
  }, [allTasks, filterDays]);

  // --- KPIs ---
  const kpis = useMemo(() => {
    const now = new Date();
    const todayDateStr = now.toISOString().split('T')[0];

    let active = 0;
    let overdue = 0;
    let dueToday = 0;
    let review = 0;
    let done = 0;

    filteredTasks.forEach(t => {
      // @ts-ignore
      const status = t.status || 'todo';
      const isDone = status === 'done';

      if (!isDone) active++;
      if (status === 'in_review') review++;
      if (isDone) done++;

      // @ts-ignore
      if (t.deadline && !isDone) {
        // @ts-ignore
        const dl = new Date(t.deadline);
        const dlStr = dl.toISOString().split('T')[0];
        if (dlStr === todayDateStr) {
          dueToday++;
        } else if (dl < now) {
          overdue++;
        }
      }
    });

    return { active, overdue, dueToday, review, done };
  }, [filteredTasks]);

  // --- Charts Data ---
  // 1. Status Breakdown
  const statusData = useMemo(() => {
    const counts = { todo: 0, in_progress: 0, review: 0, blocked: 0, done: 0 };
    filteredTasks.forEach(t => {
      // @ts-ignore
      const s = (t.status || 'todo').toLowerCase();
      if (s in counts) counts[s as keyof typeof counts]++;
      else counts.todo++;
    });
    return Object.entries(counts).map(([k, v]) => ({ label: k.replace('_', ' '), value: v }));
  }, [filteredTasks]);
  const maxStatus = Math.max(...statusData.map(d => d.value), 1);

  // 2. Priority
  const priorityData = useMemo(() => {
    const counts = { critical: 0, high: 0, medium: 0, low: 0 };
    filteredTasks.forEach(t => {
      // @ts-ignore
      const p = (t.priority || 'medium').toLowerCase();
      if (p in counts) counts[p as keyof typeof counts]++;
      else counts.medium++;
    });
    return Object.entries(counts).map(([k, v]) => ({ label: k, value: v }));
  }, [filteredTasks]);
  const maxPriority = Math.max(...priorityData.map(d => d.value), 1);

  // 3. Completion Trend (SVG Line)
  const trendData = useMemo(() => {
    const map: Record<string, number> = {};
    const daysToMap = filterDays === -1 ? 30 : filterDays === 1 ? 7 : filterDays; // min 7 days for trend line visualization

    for (let i = daysToMap - 1; i >= 0; i--) {
      const d = new Date();
      d.setDate(d.getDate() - i);
      map[d.toISOString().split('T')[0]] = 0;
    }

    filteredTasks.forEach(t => {
      // @ts-ignore
      if (t.status === 'done') {
        // @ts-ignore
        const dateStr = (t.updatedAt || t.createdAt || new Date().toISOString()).split('T')[0];
        if (map[dateStr] !== undefined) {
          map[dateStr]++;
        }
      }
    });

    const values = Object.values(map);
    return {
      labels: Object.keys(map).map(d => d.slice(5)), // MM-DD
      values,
      max: Math.max(...values, 1)
    };
  }, [filteredTasks, filterDays]);

  // 4. Team Workload
  const workloadData = useMemo(() => {
    const map: Record<string, number> = {};
    filteredTasks.forEach(t => {
      // @ts-ignore
      if (t.status !== 'done') {
        // @ts-ignore
        const assignee = t.assigneeId || t.assignee || 'Unassigned';
        map[assignee] = (map[assignee] || 0) + 1;
      }
    });
    const sorted = Object.entries(map).sort((a, b) => b[1] - a[1]).slice(0, 5);
    return sorted.map(([k, v]) => ({ label: k, value: v }));
  }, [filteredTasks]);
  const maxWorkload = Math.max(...workloadData.map(d => d.value), 1);

  return (
    <div className="flex flex-col gap-6 p-6 min-h-screen bg-bg">
      {/* Header */}
      <div className="flex justify-between items-end">
        <div>
          <h1 className="text-3xl font-bold font-syne text-text tracking-tight mb-1">Ops Dashboard</h1>
          <p className="text-sm font-grotesk text-text-2">{todayStr}</p>
        </div>

        <div className="flex items-center gap-4">
          {/* Date Filter */}
          <div className="flex bg-surface p-1 rounded-md border border-border">
            {FILTER_OPTIONS.map(opt => {
              const isActive = filterDays === opt.days;
              return (
                <button
                  key={opt.label}
                  onClick={() => setFilterDays(opt.days)}
                  className={`px-3 py-1.5 rounded text-xs font-semibold font-grotesk transition-all ${isActive ? 'bg-primary text-bg shadow-sm' : 'text-text-2 hover:text-text hover:bg-hover'}`}
                >
                  {opt.label}
                </button>
              );
            })}
          </div>

          {/* Refresh Button */}
          <button
            onClick={handleRefresh}
            className="flex items-center justify-center w-9 h-9 rounded-md bg-surface border border-border text-text hover:bg-hover transition-colors"
          >
            <RefreshCw 
              size={16} 
              className={`transition-transform duration-500 ${isRefreshing ? 'rotate-180' : 'rotate-0'}`}
            />
          </button>
        </div>
      </div>

      {/* KPIs (Bento Rhythm) */}
      <div className="grid grid-cols-1 md:grid-cols-6 gap-4">
        {/* Hero KPI */}
        <div className="col-span-1 md:col-span-2 bg-text border border-text rounded-xl p-6 flex flex-col gap-2">
          <div className="text-sm font-medium text-bg/70">Total Active</div>
          <div className="text-5xl font-syne font-bold text-bg">{kpis.active}</div>
        </div>

        {/* Standard KPIs */}
        <KpiCard title="Overdue" value={kpis.overdue} color="text-red-500" />
        <KpiCard title="Due Today" value={kpis.dueToday} color="text-amber-500" />
        <KpiCard title="In Review" value={kpis.review} color="text-blue-500" />
        <KpiCard title="Done" value={kpis.done} color="text-primary" />
      </div>

      {/* Charts Section (Bento Grid) */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {/* Chart 1: Status */}
        <ChartCard title="Task Status Breakdown" className="col-span-1">
          <div style={{ display: 'flex', height: '100%', alignItems: 'flex-end', gap: '12px', paddingTop: '20px' }}>
            {statusData.map(d => (
              <div key={d.label} style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '8px' }}>
                <div style={{ fontSize: '12px', color: 'var(--c-text-2)' }}>{d.value}</div>
                <div style={{ 
                  width: '100%', 
                  background: '#2AB182', 
                  borderRadius: '4px 4px 0 0',
                  height: `${(d.value / maxStatus) * 120}px`,
                  transition: 'height 0.3s'
                }} />
                <div style={{ fontSize: '12px', color: 'var(--c-text-3)', textTransform: 'capitalize' }}>
                  {d.label}
                </div>
              </div>
            ))}
          </div>
        </ChartCard>

        {/* Chart 3: Completion Trend (Span 2 columns for bento effect) */}
        <ChartCard title="Completion Trend" className="col-span-1 md:col-span-2 bg-surface-2 border-none">
          <div style={{ display: 'flex', height: '100%', alignItems: 'flex-end', gap: '12px', paddingTop: '20px' }}>
            {priorityData.map(d => (
              <div key={d.label} style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '8px' }}>
                <div style={{ fontSize: '12px', color: 'var(--c-text-2)' }}>{d.value}</div>
                <div style={{ 
                  width: '100%', 
                  background: '#7C3AED', 
                  borderRadius: '4px 4px 0 0',
                  height: `${(d.value / maxPriority) * 120}px`,
                  transition: 'height 0.3s'
                }} />
                <div style={{ fontSize: '12px', color: 'var(--c-text-3)', textTransform: 'capitalize' }}>
                  {d.label}
                </div>
              </div>
            ))}
          </div>
        </ChartCard>

        {/* Chart 3: Completion Trend */}
        <ChartCard title="Completion Trend">
          <div style={{ position: 'relative', height: '100%', width: '100%', paddingTop: '20px' }}>
            <svg width="100%" height="100%" viewBox="0 0 100 100" preserveAspectRatio="none">
              <polyline
                fill="none"
                stroke="#2AB182"
                strokeWidth="2"
                points={
                  trendData.values.map((v, i) => {
                    const x = trendData.values.length > 1 ? (i / (trendData.values.length - 1)) * 100 : 50;
                    const y = 100 - ((v / trendData.max) * 80); // leave 20% padding at top
                    return `${x},${y}`;
                  }).join(' ')
                }
              />
              {trendData.values.map((v, i) => {
                const x = trendData.values.length > 1 ? (i / (trendData.values.length - 1)) * 100 : 50;
                const y = 100 - ((v / trendData.max) * 80);
                return (
                  <circle key={i} cx={x} cy={y} r="3" fill="#2AB182" />
                );
              })}
            </svg>
            <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '8px' }}>
              {trendData.labels.filter((_, i) => i === 0 || i === trendData.labels.length - 1 || i === Math.floor(trendData.labels.length / 2)).map((l, i) => (
                <span key={i} style={{ fontSize: '11px', color: 'var(--c-text-3)' }}>{l}</span>
              ))}
            </div>
          </div>
        </ChartCard>

        {/* Chart 4: Team Workload */}
        <ChartCard title="Team Workload (Active)" className="col-span-1 md:col-span-3">
          <div style={{ display: 'flex', flexDirection: 'column', justifyContent: 'center', height: '100%', gap: '12px' }}>
            {workloadData.length === 0 ? (
              <div style={{ color: 'var(--c-text-3)', fontSize: '14px', textAlign: 'center' }}>No active tasks assigned</div>
            ) : workloadData.map(d => (
              <div key={d.label} style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                <div style={{ width: '80px', fontSize: '12px', color: 'var(--c-text-2)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                  {d.label}
                </div>
                <div style={{ flex: 1, background: 'var(--c-surface-2)', height: '8px', borderRadius: '4px', overflow: 'hidden' }}>
                  <div style={{ 
                    width: `${(d.value / maxWorkload) * 100}%`, 
                    height: '100%', 
                    background: '#7C3AED',
                    borderRadius: '4px',
                    transition: 'width 0.3s'
                  }} />
                </div>
                <div style={{ width: '24px', fontSize: '12px', color: 'var(--c-text-2)', textAlign: 'right' }}>
                  {d.value}
                </div>
              </div>
            ))}
          </div>
        </ChartCard>
      </div>

      {/* Task Table */}
      <div className="bg-surface border border-border rounded-xl overflow-hidden flex flex-col">
        <div className="px-5 py-4 border-b border-border flex justify-between items-center">
          <h2 className="text-base font-semibold font-syne text-text m-0">Active Tasks</h2>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full border-collapse text-left">
            <thead>
              <tr className="bg-surface-2 text-text-3 text-xs uppercase font-grotesk tracking-wider">
                <th className="px-5 py-3 font-medium">Client</th>
                <th className="px-5 py-3 font-medium">Task Title</th>
                <th className="px-5 py-3 font-medium">Category</th>
                <th className="px-5 py-3 font-medium">Priority</th>
                <th className="px-5 py-3 font-medium">Status</th>
                <th className="px-5 py-3 font-medium">Deadline</th>
                <th className="px-5 py-3 font-medium">Est. Hours</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border">
              {/* @ts-ignore */}
              {filteredTasks.filter(t => t.status !== 'done').length === 0 ? (
                <tr>
                  <td colSpan={7} style={{ padding: '32px', textAlign: 'center', color: 'var(--c-text-3)' }}>
                    No active tasks found for the selected period.
                  </td>
                </tr>
              ) : (
                filteredTasks.filter(t => (t as any).status !== 'done').map((t, idx) => {
                  const task = t as any;
                  return (
                  <tr 
                    key={task.id || idx} 
                    onClick={() => setSelectedTaskId(task.id)}
                    style={{ 
                      borderBottom: '1px solid var(--c-border)',
                      cursor: 'pointer',
                      transition: 'background 0.2s'
                    }}
                    onMouseEnter={(e) => e.currentTarget.style.background = 'var(--c-surface-2)'}
                    onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
                  >
                    <td style={{ padding: '12px 20px', color: 'var(--c-text)' }}>{task.clientId || task.client || '-'}</td>
                    <td style={{ padding: '12px 20px', color: 'var(--c-text)', fontWeight: 500 }}>{task.title || 'Untitled Task'}</td>
                    <td style={{ padding: '12px 20px', color: 'var(--c-text-2)' }}>{task.categoryId || task.category || '-'}</td>
                    <td style={{ padding: '12px 20px' }}>
                      <span style={{ 
                        padding: '4px 8px', 
                        borderRadius: '4px', 
                        fontSize: '12px',
                        background: getPriorityColor(task.priority) + '20',
                        color: getPriorityColor(task.priority)
                      }}>
                        {(task.priority || 'Medium').toUpperCase()}
                      </span>
                    </td>
                    <td style={{ padding: '12px 20px', color: 'var(--c-text-2)', textTransform: 'capitalize' }}>
                      {(task.status || 'todo').replace('_', ' ')}
                    </td>
                    <td style={{ padding: '12px 20px', color: 'var(--c-text-2)' }}>
                      {task.deadline ? new Date(task.deadline).toLocaleDateString() : '-'}
                    </td>
                    <td style={{ padding: '12px 20px', color: 'var(--c-text-2)' }}>
                      {task.estHours || task.estimatedHours || '-'}
                    </td>
                  </tr>
                )}
                )
              )}
            </tbody>
          </table>
        </div>
      </div>

      {selectedTaskId && (
        <TaskDrawer taskId={selectedTaskId} onClose={() => setSelectedTaskId(null)} />
      )}
    </div>
  );
}

// --- Helper Components ---

function KpiCard({ title, value, color }: { title: string, value: number, color: string }) {
  return (
    <div className="bg-surface border border-border rounded-xl p-5 flex flex-col gap-2">
      <div className="text-xs font-medium text-text-2 uppercase tracking-wider font-grotesk">{title}</div>
      <div className={`text-3xl font-bold font-syne ${color}`}>{value}</div>
    </div>
  );
}

function ChartCard({ title, children, className = "" }: { title: string, children: React.ReactNode, className?: string }) {
  return (
    <div className={`bg-surface border border-border rounded-xl p-5 flex flex-col min-h-[260px] ${className}`}>
      <div className="text-sm font-semibold font-syne text-text mb-4">
        {title}
      </div>
      <div className="flex-1 min-h-0">
        {children}
      </div>
    </div>
  );
}

function getPriorityColor(priority?: string) {
  switch ((priority || '').toLowerCase()) {
    case 'critical': return '#ef4444';
    case 'high': return '#f97316';
    case 'medium': return '#3b82f6';
    case 'low': return '#2AB182';
    default: return '#8b5cf6';
  }
}

import React from 'react';
import type { Task } from '@/lib/data_types';
import { isOverdue } from '@/lib/data';
import { useApp } from '@/contexts/AppContext';

interface TaskQueueTableProps {
  tasks: Task[];
  title?: string;
  onTaskClick: (taskId: string) => void;
  renderExtraColumns?: () => React.ReactNode;
  renderExtraCells?: (task: Task) => React.ReactNode;
}

export function TaskQueueTable({ tasks, title = "MY TASKS", onTaskClick, renderExtraColumns, renderExtraCells }: TaskQueueTableProps) {
  const { state } = useApp();
  return (
    <div className="w-full bg-[var(--c-surface)] border border-[var(--c-border)] rounded-xl overflow-hidden mb-6">
      <div className="px-6 py-4 border-b border-[var(--c-border)] flex justify-between items-center">
        <h3 className="font-syne font-bold text-[var(--c-text)] text-sm tracking-wider uppercase">
          {title}
        </h3>
        <span className="text-xs font-bold text-[var(--c-text-3)] bg-[var(--c-surface-2)] px-2 py-1 rounded-full">
          {tasks.length} {tasks.length === 1 ? 'task' : 'tasks'}
        </span>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="bg-[var(--c-surface-2)] border-b border-[var(--c-border)]">
              <th className="px-6 py-3 text-xs font-semibold text-[var(--c-text-2)] uppercase">Status</th>
              <th className="px-6 py-3 text-xs font-semibold text-[var(--c-text-2)] uppercase">Client</th>
              <th className="px-6 py-3 text-xs font-semibold text-[var(--c-text-2)] uppercase">Title</th>
              <th className="px-6 py-3 text-xs font-semibold text-[var(--c-text-2)] uppercase">Est.</th>
              <th className="px-6 py-3 text-xs font-semibold text-[var(--c-text-2)] uppercase">Deadline</th>
              {renderExtraColumns && renderExtraColumns()}
              <th className="px-6 py-3 text-xs font-semibold text-[var(--c-text-2)] uppercase text-right">Action</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-[var(--c-border)]">
            {tasks.length === 0 ? (
              <tr>
                <td colSpan={7} className="px-6 py-8 text-center text-[var(--c-text-3)] text-sm">
                  Your queue is clear.
                </td>
              </tr>
            ) : (
              tasks.map((t) => {
                const isLate = isOverdue(t);
                const isDone = t.status === 'done';
                const clientCode = state.clients.find(c => c.id === t.clientId)?.code || 'Unknown';

                const statusColors = {
                  todo: 'bg-slate-500/10 text-slate-500',
                  in_progress: 'bg-blue-500/10 text-blue-500',
                  in_review: 'bg-amber-500/10 text-amber-500',
                  blocked: 'bg-red-500/10 text-red-500',
                  done: 'bg-emerald-500/10 text-emerald-500',
                };

                const estText = t.timeEstimateMinutes 
                  ? `${(t.timeEstimateMinutes / 60).toFixed(1)}h`
                  : '--';
                const loggedText = t.loggedMinutes 
                  ? `${(t.loggedMinutes / 60).toFixed(1)}h`
                  : '0h';

                return (
                  <tr 
                    key={t.id} 
                    className="hover:bg-[var(--c-hover)] transition-colors cursor-pointer group"
                    onClick={() => onTaskClick(t.id)}
                  >
                    <td className="px-6 py-3">
                      <span className={`inline-flex items-center px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-wider ${statusColors[t.status] || statusColors.todo}`}>
                        {t.status.replace('_', ' ')}
                      </span>
                    </td>
                    <td className="px-6 py-3 text-sm font-medium text-[var(--c-text-2)]">
                      {clientCode}
                    </td>
                    <td className="px-6 py-3">
                      <div className="text-sm font-semibold text-[var(--c-text)] group-hover:text-[var(--c-primary)] transition-colors">
                        {t.title}
                      </div>
                    </td>
                    <td className="px-6 py-3 text-sm text-[var(--c-text-2)]">
                      {estText}
                    </td>
                    <td className="px-6 py-3 text-sm">
                      <span className={isLate && !isDone ? 'text-red-500 font-bold' : 'text-[var(--c-text-2)]'}>
                        {t.deadline ? new Date(t.deadline).toLocaleDateString() : 'No deadline'}
                      </span>
                    </td>

                    {renderExtraCells && renderExtraCells(t)}

                    <td className="px-6 py-3 text-sm text-right">
                      <button 
                        className="text-[var(--c-primary)] font-bold text-xs opacity-0 group-hover:opacity-100 transition-opacity"
                        onClick={(e) => {
                          e.stopPropagation();
                          onTaskClick(t.id);
                        }}
                      >
                        [Open →]
                      </button>
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

'use client';

import { useApp } from '@/contexts/AppContext';
import { Task, PRIORITY_CONFIG } from '@/lib/data';
import { X, Calendar as CalendarIcon, Clock } from 'lucide-react';
import TaskDrawer from '@/components/tasks/TaskDrawer';
import { useState, useEffect } from 'react';

interface Props {
  date: Date | null;
  isOpen: boolean;
  onClose: () => void;
}

export default function VerticalTimelineModal({ date, isOpen, onClose }: Props) {
  const { state } = useApp();
  const [selectedTaskId, setSelectedTaskId] = useState<string | null>(null);

  // Close on Escape
  useEffect(() => {
    const handler = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [onClose]);

  if (!isOpen || !date) return null;

  // Set the start and end of the selected day
  const startOfDay = new Date(date);
  startOfDay.setHours(0, 0, 0, 0);

  const endOfDay = new Date(date);
  endOfDay.setHours(23, 59, 59, 999);

  // Filter tasks that have a deadline or start time on this day
  const dayTasks = state.tasks.filter(t => {
    const tStart = t.startTime ? new Date(t.startTime) : new Date(t.createdAt);
    const tEnd = t.deadline ? new Date(t.deadline) : null;

    // Falls within this day
    if (tEnd && tEnd >= startOfDay && tEnd <= endOfDay) return true;
    if (tStart >= startOfDay && tStart <= endOfDay) return true;

    // Spans across this day
    if (tEnd && tStart <= startOfDay && tEnd >= endOfDay) return true;

    return false;
  }).sort((a, b) => {
    const timeA = a.deadline ? new Date(a.deadline).getTime() : new Date(a.createdAt).getTime();
    const timeB = b.deadline ? new Date(b.deadline).getTime() : new Date(b.createdAt).getTime();
    return timeA - timeB;
  });

  const hours = Array.from({ length: 15 }, (_, i) => i + 8); // 8 AM to 10 PM

  return (
    <>
      {/* Backdrop */}
      <div className="fixed inset-0 z-[100] bg-black/50 backdrop-blur-[2px]" onClick={onClose} />

      {/* Drawer */}
      <div 
