'use client';

import { useState, useEffect, useRef } from 'react';
import { useRouter } from 'next/navigation';
import { Search, Folder, CheckSquare, Users, ArrowRight, Target, Zap, Layers, AlignLeft, X, LayoutDashboard } from 'lucide-react';
import { useApp } from '@/contexts/AppContext';

const STATUS_COLORS: Record<string, string> = {
  todo: '#64748B', in_progress: '#3B82F6', in_review: '#F59E0B',
  blocked: '#EF4444', done: '#10B981', paused: '#F97316', rework: '#8B5CF6',
};

const PRIORITY_COLORS: Record<string, string> = {
  critical: '#EF4444', high: '#F97316', medium: '#F59E0B', low: '#94A3B8',
};

const QUICK_CREATE_OPTIONS = [
  { label: 'Goal', action: 'create_goal', icon: Target, color: '#7C3AED', desc: 'Project or milestone', type: 'goal' },
  { label: 'Task', action: 'create_task', icon: CheckSquare, color: '#2AB182', desc: 'A specific work item', type: 'task' },
  { label: 'Subtask', action: 'create_subtask', icon: Layers, color: '#3B82F6', desc: 'Part of a task', type: 'subtask' },
];

const STATIC_ROUTES = [
  { label: 'Dashboard', icon: LayoutDashboard, url: '/dashboard' },
  { label: 'Task Board', icon: CheckSquare, url: '/tasks' },
  { label: 'Clients', icon: Folder, url: '/clients' },
  { label: 'Team Directory', icon: Users, url: '/team' },
  { label: 'Calendar', icon: AlignLeft, url: '/calendar' },
  { label: 'Team Dashboard', icon: Zap, url: '/team-dashboard' },
];

export default function CommandPalette() {
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState('');
  const { state } = useApp();
  const router = useRouter();
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const down = (e: KeyboardEvent) => {
      if (e.key === 'k' && (e.metaKey || e.ctrlKey)) {
        e.preventDefault();
        setOpen(o => !o);
      }
    };
    const openEvent = () => setOpen(true);
    document.addEventListener('keydown', down);
    window.addEventListener('open-command-palette', openEvent);
    return () => {
      document.removeEventListener('keydown', down);
      window.removeEventListener('open-command-palette', openEvent);
    };
  }, []);

  useEffect(() => {
    if (open) {
      setQuery('');
      setTimeout(() => inputRef.current?.focus(), 50);
    }
  }, [open]);

  const close = () => setOpen(false);

  if (!open) return null;

  const q = query.toLowerCase().trim();

  const taskResults = q.length > 0
    ? state.tasks
        .filter(t =>
          t.title.toLowerCase().includes(q) ||
          t.id.toLowerCase().includes(q) ||
          (t.description || '').toLowerCase().includes(q)
        )
        .slice(0, 6)
    : [];

  const clientResults = q.length > 0
    ? state.clients
        .filter(c => c.name.toLowerCase().includes(q) || c.code.toLowerCase().includes(q))
        .slice(0, 3)
    : [];

  const pageResults = q.length > 0
    ? STATIC_ROUTES.filter(r => r.label.toLowerCase().includes(q))
    : STATIC_ROUTES;

  const handleNavigate = (url: string) => {
    close();
    router.push(url);
  };

  const handleOpenTask = (taskId: string) => {
    close();
    window.dispatchEvent(new CustomEvent('open-task-drawer', { detail: { taskId } }));
  };

  const handleQuickCreate = (type: string) => {
    close();
    window.dispatchEvent(new CustomEvent('open-new-task-modal', {
      detail: { title: query.trim(), type }
    }));
  };

  const todayStr = new Date().toISOString().split('T')[0];

  return (
    <div
      className="fixed inset-0 z-[300] flex items-start justify-center pt-[10vh] bg-black/60 backdrop-blur-sm"
      onClick={close}
    >
      <div
        className="w-full max-w-2xl rounded-2xl overflow-hidden shadow-2xl"
        style={{
          background: 'var(--c-surface)',
          border: '1px solid var(--c-border)',
          animation: 'paletteIn 0.18s ease-out',
        }}
        onClick={e => e.stopPropagation()}
      >
        {/* Search Input */}
        <div className="flex items-center px-4 py-3" style={{ borderBottom: '1px solid var(--c-border)' }}>
          <Search className="w-5 h-5 mr-3 flex-shrink-0" style={{ color: '#2AB182' }} />
          <input
            ref={inputRef}
            type="text"
            className="flex-1 bg-transparent outline-none text-[15px]"
            style={{ color: 'var(--c-text)' }}
            placeholder="Search tasks, clients, or type to create…"
            value={query}
            onChange={e => setQuery(e.target.value)}
            onKeyDown={e => { if (e.key === 'Escape') close(); }}
          />
          {query && (
            <button
              onClick={() => setQuery('')}
              className="p-1 rounded transition-colors"
              style={{ color: 'var(--c-text-3)' }}
            >
              <X className="w-4 h-4" />
            </button>
          )}
          <kbd
            className="ml-2 px-1.5 py-0.5 rounded text-[10px] font-mono font-bold"
            style={{ background: 'var(--c-surface-3)', color: 'var(--c-text-2)', border: '1px solid var(--c-border)' }}
          >
            esc
          </kbd>
        </div>

        <div className="max-h-[480px] overflow-y-auto custom-scrollbar" style={{ paddingBottom: 8 }}>

          {/* ── Quick Create (always shown when query has text) ── */}
          {q.length > 0 && (
            <div className="px-3 pt-4 pb-2">
              <div
                className="text-[10px] font-bold uppercase tracking-wider mb-2 px-1"
                style={{ color: 'var(--c-text-3)' }}
              >
                Quick Create
              </div>
              <div className="flex flex-col gap-1">
                {QUICK_CREATE_OPTIONS.map(opt => {
                  const Icon = opt.icon;
                  return (
                    <button
                      key={opt.action}
                      onClick={() => handleQuickCreate(opt.type)}
                      className="flex items-center gap-3 px-3 py-2.5 rounded-xl text-left w-full transition hover:opacity-90"
                      style={{
                        background: `${opt.color}12`,
                        border: `1px solid ${opt.color}30`,
                      }}
                    >
                      <div
                        className="w-8 h-8 rounded-lg flex items-center justify-center flex-shrink-0"
                        style={{ background: `${opt.color}20` }}
                      >
                        <Icon className="w-4 h-4" style={{ color: opt.color }} />
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="text-[11px] font-bold" style={{ color: opt.color }}>
                          Create {opt.label}
                        </div>
                        <div
                          className="text-[13px] font-semibold truncate"
                          style={{ color: 'var(--c-text)' }}
                        >
                          &ldquo;{query.trim()}&rdquo;
                        </div>
                      </div>
                      <div
                        className="text-[10px] font-bold uppercase tracking-wider flex-shrink-0"
                        style={{ color: opt.color, opacity: 0.6 }}
                      >
                        {opt.desc}
                      </div>
                    </button>
                  );
                })}
              </div>
            </div>
          )}

          {/* ── Task Results ── */}
          {taskResults.length > 0 && (
            <div className="px-3 pt-4 pb-2">
              <div
                className="text-[10px] font-bold uppercase tracking-wider mb-2 px-1"
                style={{ color: 'var(--c-text-3)' }}
              >
                Tasks — {taskResults.length} found
              </div>
              <div className="flex flex-col gap-1">
                {taskResults.map(task => {
                  const client = state.clients.find(c => c.id === task.clientId);
                  const statusColor = STATUS_COLORS[task.status] || '#64748B';
                  const priorityColor = PRIORITY_COLORS[task.priority] || '#94A3B8';
                  const isOverdue = task.deadline && task.status !== 'done' && task.deadline < todayStr;
                  return (
                    <button
                      key={task.id}
                      onClick={() => handleOpenTask(task.id)}
                      className="flex items-center gap-3 px-3 py-2.5 rounded-xl text-left w-full transition-colors group"
                      style={{ background: 'transparent' }}
                      onMouseEnter={e => (e.currentTarget.style.background = 'var(--c-surface-2)')}
                      onMouseLeave={e => (e.currentTarget.style.background = 'transparent')}
                    >
                      <div
                        className="w-2 h-2 rounded-full flex-shrink-0 mt-0.5"
                        style={{ background: statusColor }}
                      />
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 min-w-0">
                          <span
                            className="text-[13px] font-semibold truncate"
                            style={{ color: 'var(--c-text)' }}
                          >
                            {task.title}
                          </span>
                          <span
                            className="text-[9px] font-mono flex-shrink-0"
                            style={{ color: 'var(--c-text-3)' }}
                          >
                            {task.id}
                          </span>
                        </div>
                        <div className="flex items-center gap-2 mt-0.5 flex-wrap">
                          {client && (
                            <span className="text-[11px] font-bold" style={{ color: '#2AB182' }}>
                              {client.code}
                            </span>
                          )}
                          <span
                            className="px-1.5 py-0.5 rounded text-[10px] font-bold uppercase"
                            style={{ background: `${priorityColor}18`, color: priorityColor }}
                          >
                            {task.priority}
                          </span>
                          <span
                            className="px-1.5 py-0.5 rounded text-[10px] font-bold"
                            style={{ background: `${statusColor}18`, color: statusColor }}
                          >
                            {task.status.replace(/_/g, ' ')}
                          </span>
                          {task.deadline && (
                            <span
                              className="text-[10px]"
                              style={{ color: isOverdue ? '#EF4444' : 'var(--c-text-3)' }}
                            >
                              {isOverdue ? '⚠ ' : ''}
                              {new Date(task.deadline).toLocaleDateString('en-IN', {
                                day: 'numeric',
                                month: 'short',
                              })}
                            </span>
                          )}
                        </div>
                      </div>
                      <div
                        className="text-[10px] font-semibold flex-shrink-0 self-center px-2 py-1 rounded-lg"
                        style={{ background: 'var(--c-surface-3)', color: 'var(--c-text-3)' }}
                      >
                        Open ↗
                      </div>
                    </button>
                  );
                })}
              </div>
            </div>
          )}

          {/* ── Client Results ── */}
          {clientResults.length > 0 && (
            <div className="px-3 pt-4 pb-2">
              <div
                className="text-[10px] font-bold uppercase tracking-wider mb-2 px-1"
                style={{ color: 'var(--c-text-3)' }}
              >
                Clients
              </div>
              <div className="flex flex-col gap-1">
                {clientResults.map(client => {
                  const clientTasks = state.tasks.filter(
                    t => t.clientId === client.id && t.status !== 'done'
                  );
                  return (
                    <button
                      key={client.id}
                      onClick={() => handleNavigate(`/clients/${client.id}`)}
                      className="flex items-center gap-3 px-3 py-2.5 rounded-xl text-left w-full transition-colors"
                      style={{ background: 'transparent' }}
                      onMouseEnter={e => (e.currentTarget.style.background = 'var(--c-surface-2)')}
                      onMouseLeave={e => (e.currentTarget.style.background = 'transparent')}
                    >
                      <div
                        className="w-8 h-8 rounded-lg flex items-center justify-center text-[11px] font-bold text-white flex-shrink-0"
                        style={{ background: client.color }}
                      >
                        {client.code.slice(0, 2)}
                      </div>
                      <div className="flex-1 min-w-0">
                        <div
                          className="text-[13px] font-semibold"
                          style={{ color: 'var(--c-text)' }}
                        >
                          {client.name}
                        </div>
                        <div className="text-[11px]" style={{ color: 'var(--c-text-3)' }}>
                          {clientTasks.length} active tasks · {client.category}
                        </div>
                      </div>
                      <Folder className="w-4 h-4 flex-shrink-0" style={{ color: 'var(--c-text-3)' }} />
                    </button>
                  );
                })}
              </div>
            </div>
          )}

          {/* ── Pages / Navigate ── */}
          {pageResults.length > 0 && (
            <div className="px-3 pt-4 pb-2">
              <div
                className="text-[10px] font-bold uppercase tracking-wider mb-2 px-1"
                style={{ color: 'var(--c-text-3)' }}
              >
                {q ? 'Pages' : 'Navigate'}
              </div>
              <div className="flex flex-col gap-1">
                {pageResults.map(page => {
                  const Icon = page.icon;
                  return (
                    <button
                      key={page.url}
                      onClick={() => handleNavigate(page.url)}
                      className="flex items-center gap-3 px-3 py-2 rounded-xl text-left w-full transition-colors"
                      style={{ background: 'transparent' }}
                      onMouseEnter={e => (e.currentTarget.style.background = 'var(--c-surface-2)')}
                      onMouseLeave={e => (e.currentTarget.style.background = 'transparent')}
                    >
                      <Icon className="w-4 h-4 flex-shrink-0" style={{ color: 'var(--c-text-3)' }} />
                      <span
                        className="text-[13px] font-medium"
                        style={{ color: 'var(--c-text-2)' }}
                      >
                        {page.label}
                      </span>
                      <span className="ml-auto text-[10px]" style={{ color: 'var(--c-text-3)' }}>
                        {page.url}
                      </span>
                    </button>
                  );
                })}
              </div>
            </div>
          )}

          {/* ── No Results ── */}
          {q.length > 0 &&
            taskResults.length === 0 &&
            clientResults.length === 0 &&
            pageResults.length === 0 && (
              <div className="p-8 text-center" style={{ color: 'var(--c-text-3)' }}>
                <Search className="w-8 h-8 mx-auto mb-3 opacity-30" />
                <p className="text-[13px]">No results for &ldquo;{query}&rdquo;</p>
                <p className="text-[11px] mt-1 opacity-70">
                  Use the Quick Create options above to create a new task
                </p>
              </div>
            )}
        </div>

        {/* Footer */}
        <div
          className="px-4 py-2.5 flex items-center justify-between text-[11px] font-medium"
          style={{
            borderTop: '1px solid var(--c-border)',
            background: 'var(--c-surface-2)',
            color: 'var(--c-text-3)',
          }}
        >
          <div className="flex items-center gap-4">
            <span className="flex items-center gap-1">
              <kbd
                className="rounded px-1"
                style={{ background: 'var(--c-surface)', border: '1px solid var(--c-border)' }}
              >
                ↵
              </kbd>{' '}
              open / create
            </span>
            <span className="flex items-center gap-1">
              <kbd
                className="rounded px-1"
                style={{ background: 'var(--c-surface)', border: '1px solid var(--c-border)' }}
              >
                esc
              </kbd>{' '}
              close
            </span>
          </div>
          <span className="flex items-center gap-1.5">
            <span className="w-1.5 h-1.5 rounded-full bg-primary animate-pulse" />
            Invictus Command Palette
          </span>
        </div>
      </div>

      <style jsx global>{`
        @keyframes paletteIn {
          from {
            opacity: 0;
            transform: translateY(-14px) scale(0.97);
          }
          to {
            opacity: 1;
            transform: translateY(0) scale(1);
          }
        }
      `}</style>
    </div>
  );
}

'use client';

import Link from 'next/link';
import { usePathname, useSearchParams } from 'next/navigation';
import { useState, Suspense } from 'react';
import { 
  LayoutDashboard, User, CheckSquare, CalendarDays, Briefcase, 
  Users, Layers, TrendingUp, Key, History, Sparkles, Shield,
  Menu, PanelLeftClose, Zap, LogOut, Terminal, Brush, Film, LineChart,
  List, Calendar, BarChart, FileBarChart, Megaphone, Wallet
} from 'lucide-react';
import { NAV_SECTIONS } from '@/lib/data';
import { useApp } from '@/contexts/AppContext';

function SideNavBarInner() {
  const pathname = usePathname();
  const searchParams = useSearchParams();
  const { state } = useApp();
  const [collapsed, setCollapsed] = useState(false);
  const [expandedGroups, setExpandedGroups] = useState<Record<string, boolean>>({
    'Workspace': true,
    'Client Ops': true,
    'Agency Ops': true,
    'Settings & AI': true
  });

  const toggleGroup = (title: string) => {
    setExpandedGroups(prev => ({
      ...prev,
      [title]: !prev[title]
    }));
  };

  const currentUser = state.teamMembers.find(m => m.id === state.currentUserId);
  console.log('SideNavBar currentUser:', currentUser, 'currentUserId:', state.currentUserId, 'teamMembers count:', state.teamMembers.length);

  const overdueCount = state.tasks.filter(t => {
    if (!t.deadline || t.status === 'done') return false;
    return new Date(t.deadline) < new Date(new Date().toDateString());
  }).length;

  return (
    <aside
      className="fixed left-0 top-0 h-full z-50 flex flex-col transition-all duration-300 bg-app-sidebar border-r border-app-border"
      style={{
        width: collapsed ? '64px' : '240px',
      }}
    >
      {/* Logo */}
      <div className="flex items-center gap-3 px-4 h-14 flex-shrink-0 border-b border-app-border">
        <div className="w-8 h-8 rounded-lg flex items-center justify-center flex-shrink-0"
          style={{ background: 'linear-gradient(135deg, #2AB182, #1A8F68)' }}>
          <Zap className="w-5 h-5 text-white" fill="currentColor" />
        </div>
        {!collapsed && (
          <span className="text-app-text font-syne font-bold text-lg tracking-tight leading-none">
            INVICTUS<br /><span className="text-[10px] tracking-[0.3em] font-medium opacity-50">OS</span>
          </span>
        )}
        <button
          onClick={() => setCollapsed(p => !p)}
          className="ml-auto text-app-text3 hover:text-app-text transition-colors"
          style={{ display: collapsed ? 'block' : 'block' }}
        >
          {collapsed ? <Menu className="w-5 h-5" /> : <PanelLeftClose className="w-5 h-5" />}
        </button>
      </div>

      {/* Nav items */}
      <nav className="flex-1 py-3 overflow-y-auto overflow-x-hidden">
        {(() => {
          const SIDEBAR_GROUPS = [
            {
              title: 'Workspace',
              items: ['/dashboard', '/developer-dashboard', '/designer-dashboard', '/editor-dashboard', '/sales-dashboard', '/team-dashboard', '/my-workspace', '/tasks', '/calendar']
            },
            {
              title: 'Client Ops',
              items: ['/clients', '/sales', '/campaigns', '/ad-budget', '/social']
            },
            {
              title: 'Agency Ops',
              items: ['/team', '/development', '/team/workload', '/analytics', '/finance']
            },
            {
              title: 'Settings & AI',
              items: ['/credentials', '/audit', '/ai', '/admin']
            }
          ];

          return SIDEBAR_GROUPS.map((group, groupIdx) => {
            const groupItems = NAV_SECTIONS.filter((item) => {
              if (!currentUser) return false;
              if (!group.items.includes(item.href)) return false;

              const role = currentUser.role;
              const department = currentUser.department;

              // Dashboard Filtering Logic
              if (item.section === 'dashboard') {
                if (role === 'super_admin' || role === 'ops' || role === 'admin') {
                  if (item.href !== '/dashboard') return false;
                } else if (department === 'design') {
                  if (item.href !== '/designer-dashboard') return false;
                } else if (department === 'video' || department === 'video_editor') {
                  if (item.href !== '/editor-dashboard') return false;
                } else if (department === 'development' || department === 'web_developer' || department === 'ai_developer') {
                  if (item.href !== '/developer-dashboard') return false;
                } else if (department === 'performance_marketing' || department === 'sales') {
                  if (item.href !== '/sales-dashboard') return false;
                } else {
                  if (item.href !== '/team-dashboard') return false;
                }
              }

              // General Section Filtering Logic
              if (role === 'team') {
                const hiddenFromTeam = ['/admin', '/audit', '/credentials', '/team/workload', '/finance'];
                if (hiddenFromTeam.includes(item.href)) return false;
              }

              if (role === 'ops') {
                const hiddenFromOps = ['/admin', '/finance'];
                if (hiddenFromOps.includes(item.href)) return false;
              }

              return true;
            });

            if (groupItems.length === 0) return null;

            return (
              <div key={group.title} className={groupIdx > 0 ? "mt-4" : ""}>
                {!collapsed && (
                  <div 
                    className="px-5 mb-2 flex items-center justify-between cursor-pointer group"
                    onClick={() => toggleGroup(group.title)}
                  >
                    <p className="text-[10px] font-semibold tracking-[0.15em] uppercase text-app-text3 group-hover:text-app-text transition-colors">
                      {group.title}
                    </p>
                    <span 
                      className="material-symbols-outlined text-[14px] text-app-text3 group-hover:text-app-text transition-transform duration-200" 
                      style={{ transform: expandedGroups[group.title] ? 'rotate(0deg)' : 'rotate(-90deg)' }}
                    >
                      expand_more
                    </span>
                  </div>
                )}
                <div className={`transition-all duration-200 overflow-hidden ${!collapsed && !expandedGroups[group.title] ? 'max-h-0 opacity-0' : 'max-h-[1000px] opacity-100'}`}>
                {groupItems.map((item) => {
                  const isActive = pathname === item.href || (item.href !== '/dashboard' && pathname.startsWith(item.href));

                  let IconComponent: any = LayoutDashboard;
                  switch (item.icon) {
                    case 'grid_view': IconComponent = LayoutDashboard; break;
                    case 'terminal': IconComponent = Terminal; break;
                    case 'brush': IconComponent = Brush; break;
                    case 'movie': IconComponent = Film; break;
                    case 'show_chart': IconComponent = LineChart; break;
                    case 'person': IconComponent = User; break;
                    case 'check_box': IconComponent = CheckSquare; break;
                    case 'view_timeline': IconComponent = CalendarDays; break;
                    case 'business_center': IconComponent = Briefcase; break;
                    case 'groups': IconComponent = Users; break;
                    case 'workspaces': IconComponent = Layers; break;
                    case 'trending_up': IconComponent = TrendingUp; break;
                    case 'key': IconComponent = Key; break;
                    case 'history_edu': IconComponent = History; break;
                    case 'auto_awesome': IconComponent = Sparkles; break;
                    case 'admin_panel_settings': IconComponent = Shield; break;
                    case 'campaign': IconComponent = Megaphone; break;
                    case 'account_balance': IconComponent = Wallet; break;
                  }
                  return (
                    <div key={item.href}>
                      <Link
                        href={item.href}
                        title={collapsed ? item.label : undefined}
                        className={`flex items-center gap-3 mx-3 mb-1 rounded-lg transition-all duration-150 relative group ${isActive ? 'bg-app-surface2' : 'bg-transparent hover:bg-app-hover'}`}
                        style={{
                          padding: collapsed ? '10px 18px' : '10px 16px',
                          justifyContent: collapsed ? 'center' : 'flex-start',
                        }}
                      >
                        {/* Active indicator */}
                        {isActive && (
                          <span className="absolute left-0 top-1/2 -translate-y-1/2 w-0.5 h-5 rounded-r bg-primary" />
                        )}

                        {/* Icon */}
                        <IconComponent 
                          className={`w-5 h-5 flex-shrink-0 transition-colors ${isActive ? 'text-primary' : 'text-app-text3'}`} 
                        />

                        {/* Label */}
                        {!collapsed && (
                          <span className={`font-medium text-[13px] transition-colors font-grotesk ${isActive ? 'text-app-text' : 'text-app-text2'}`}>
                            {item.label}
                          </span>
                        )}

                        {/* Badge */}
                        {item.section === 'dashboard' && overdueCount > 0 && (
                          <span className="ml-auto text-[10px] font-bold px-1.5 py-0.5 rounded-full text-red-500 min-w-[18px] text-center"
                            style={{ background: 'rgba(239, 68, 68, 0.1)' }}>
                            {overdueCount}
                          </span>
                        )}

                        {/* Tooltip for collapsed */}
                        {collapsed && (
                          <span className="absolute left-full ml-2 px-2 py-1 rounded text-[11px] font-medium whitespace-nowrap pointer-events-none opacity-0 group-hover:opacity-100 transition-opacity z-50 bg-app-surface3 text-app-text border border-app-border">
                            {item.label}
                          </span>
                        )}
                      </Link>

                      {/* SUB NAVIGATION FOR TASKS */}
                      {item.href === '/tasks' && pathname.startsWith('/tasks') && !collapsed && (
                        <div className="flex flex-col gap-1 mx-3 mb-4 pl-10 pr-3 border-l border-app-border/30 ml-7 mt-1">
                          <Link href="/tasks?view=board" className="text-[12px] font-medium text-app-text2 hover:text-primary py-1">Board</Link>
                          <Link href="/tasks?view=list" className="text-[12px] font-medium text-app-text2 hover:text-primary py-1">List</Link>
                          <Link href="/tasks?view=calendar" className="text-[12px] font-medium text-app-text2 hover:text-primary py-1">Calendar</Link>
                          <Link href="/tasks?view=gantt" className="text-[12px] font-medium text-app-text2 hover:text-primary py-1">Gantt chart</Link>
                          <Link href="/tasks?view=team" className="text-[12px] font-medium text-app-text2 hover:text-primary py-1">Team</Link>
                        </div>
                      )}

                      {/* SUB NAVIGATION FOR TEAM */}
                      {item.href === '/team' && pathname.startsWith('/team') && !collapsed && (
                        <div className="flex flex-col gap-1 mx-3 mb-4 pl-10 pr-3 border-l border-app-border/30 ml-7 mt-1">
                          <Link href="/team" className="text-[12px] font-medium text-app-text2 hover:text-primary py-1">Team Overview</Link>
                          <Link href="/team/workload" className="text-[12px] font-medium text-app-text2 hover:text-primary py-1">Workload</Link>
                        </div>
                      )}
                    </div>
                  );
                })}
                </div>
              </div>
            );
          });
        })()}
      </nav>

      {/* User section */}
      <div className="border-t border-app-border p-[12px_8px]">
        <div
          className="flex items-center gap-3 rounded-lg px-3 py-2.5 transition-colors hover:bg-app-hover"
          style={{ justifyContent: collapsed ? 'center' : 'flex-start' }}
        >
          <div
            className="w-7 h-7 rounded-lg flex items-center justify-center flex-shrink-0 text-[11px] font-bold text-[#0E0E0E] font-grotesk"
            style={{ backgroundColor: 'var(--c-primary)' }}
          >
            {currentUser?.initials || '??'}
          </div>
          {!collapsed && (
            <div className="flex-1 min-w-0">
              <p className="text-app-text text-[12px] font-semibold truncate font-grotesk">{currentUser?.name || 'Unknown'}</p>
              <p className="text-[10px] font-medium text-primary capitalize">{currentUser?.role?.replace('_', ' ') || 'User'}</p>
            </div>
          )}
          {!collapsed && (
            <Link href="/login" className="text-app-text3 hover:text-app-text transition-colors">
              <LogOut className="w-4 h-4" />
            </Link>
          )}
        </div>
      </div>
    </aside>
  );
}

export default function SideNavBar() {
  return (
    <Suspense fallback={<div className="w-[240px] h-full bg-app-sidebar border-r border-app-border"></div>}>
      <SideNavBarInner />
    </Suspense>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useTheme } from '@/contexts/ThemeContext';
import { useApp } from '@/contexts/AppContext';
import { Search, StopCircle, ChevronDown, Plus, Sun, Moon, Bell, X, AlertTriangle } from 'lucide-react';
import NewTaskModal from '@/components/tasks/NewTaskModal';
import TaskDrawer from '@/components/tasks/TaskDrawer';
import LiveTimer from '@/components/ui/LiveTimer';
import { computeAlerts } from '@/lib/alerts';

export default function TopAppBar({ sidebarWidth }: { sidebarWidth: number }) {
  const { theme, toggle } = useTheme();
  const { state, dispatch, requestStopTimer, getTimerElapsed } = useApp();
  const [modalOpen, setModalOpen] = useState(false);
  const [timersDropdownOpen, setTimersDropdownOpen] = useState(false);
  const [notificationsOpen, setNotificationsOpen] = useState(false);
  const [newTaskDefaults, setNewTaskDefaults] = useState<{title?: string, type?: string}>({});
  const [drawerTaskId, setDrawerTaskId] = useState<string | null>(null);

  const myNotifications = state.notifications.filter(n => n.userId === state.currentUserId).sort((a,b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
  const systemAlerts = computeAlerts(state);
  const unreadCount = myNotifications.filter(n => !n.read).length + systemAlerts.length;

  useEffect(() => {
    const handleOpenModal = (e: Event) => {
      const evt = e as CustomEvent;
      setNewTaskDefaults(evt.detail || {});
      setModalOpen(true);
    };
    const handleOpenDrawer = (e: Event) => {
      const evt = e as CustomEvent;
      setDrawerTaskId(evt.detail?.taskId || null);
    };
    window.addEventListener('open-new-task-modal', handleOpenModal);
    window.addEventListener('open-task-drawer', handleOpenDrawer);
    return () => {
      window.removeEventListener('open-new-task-modal', handleOpenModal);
      window.removeEventListener('open-task-drawer', handleOpenDrawer);
    };
  }, []);

  const firstTimer = state.activeTimers[0];
  const firstTimerTask = firstTimer ? state.tasks.find(t => t.id === firstTimer.taskId) : null;
  const firstTimerClient = firstTimerTask ? state.clients.find(c => c.id === firstTimerTask.clientId) : null;

  return (
    <>
      <header
        className="fixed top-0 right-0 z-40 flex items-center justify-between px-5 bg-app-surface border-b border-app-border transition-all duration-300"
        style={{
          left: sidebarWidth,
          height: 56,
        }}
      >
        {/* Left: Search */}
        <div className="flex items-center gap-3 flex-1 max-w-md">
          <div className="flex items-center gap-2 rounded-lg px-3 py-2 flex-1 cursor-pointer bg-app-input border border-app-border"
            onClick={() => window.dispatchEvent(new CustomEvent('open-command-palette'))}
          >
            <Search className="w-4 h-4 text-app-text2" />
            <span className="text-[13px] text-app-text3 font-grotesk">
              Search tasks, clients... <kbd className="text-[10px] px-1 rounded ml-1 bg-app-surface3 text-app-text2">⌘K</kbd>
            </span>
          </div>
        </div>

        {/* Right: Controls */}
        <div className="flex items-center gap-2">
          {/* Active Timer(s) */}
          {state.activeTimers.length === 1 && firstTimerTask && (
            <div className="flex items-center gap-2 rounded-lg px-3 py-1.5 hide-mobile border"
              style={{ background: 'rgba(42,177,130,0.1)', borderColor: 'rgba(42,177,130,0.25)' }}>
              <span className="w-2 h-2 rounded-full bg-primary animate-pulse flex-shrink-0"></span>
              <LiveTimer 
                startedAt={firstTimer.startedAt} 
                className="font-bold text-[13px] text-primary font-grotesk" 
              />
              <span className="text-[11px] truncate max-w-[120px] hide-mobile text-app-text2 font-grotesk">
                {firstTimerClient?.name?.split(' ')[0]}
              </span>
              <button
                onClick={() => requestStopTimer(firstTimer.taskId)}
                className="rounded p-0.5 hover:opacity-80 transition-opacity text-red-500"
                title="Complete Task"
              >
                <StopCircle className="w-4 h-4" />
              </button>
            </div>
          )}

          {state.activeTimers.length > 1 && (
            <div className="relative">
              <button 
                onClick={() => setTimersDropdownOpen(!timersDropdownOpen)}
                className="flex items-center gap-2 rounded-lg px-3 py-1.5 hide-mobile hover:opacity-90 transition-opacity border text-primary font-grotesk font-bold text-[13px]"
                style={{ background: 'rgba(42,177,130,0.1)', borderColor: 'rgba(42,177,130,0.25)' }}>
                <span className="w-2 h-2 rounded-full bg-primary animate-pulse flex-shrink-0"></span>
                <span>
                  {state.activeTimers.length} Active Tasks
                </span>
                <ChevronDown className="w-4 h-4 text-primary" />
              </button>

              {timersDropdownOpen && (
                <div className="absolute right-0 top-full mt-2 w-64 bg-surface border border-border shadow-lg rounded-lg overflow-hidden z-50">
