import React from 'react';
import { useApp } from '@/contexts/AppContext';

export default function SalesOverview({ onStageClick }: { onStageClick: (stage: string) => void }) {
  const { state } = useApp();
  const leads = state.leads || [];

  // Derived data
  const openLeads = leads.filter(l => !['won', 'lost', 'paused'].includes(l.stage));
  const pipelineValue = openLeads.reduce((acc, l) => acc + (l.monthlyValueINR || 0), 0);
  const wonThisMonth = leads.filter(l => l.stage === 'won').length;
  const lostThisMonth = leads.filter(l => l.stage === 'lost').length;

  // Follow-ups today (mock logic: nextFollowUp is today, or lastContactDate is > 7 days ago)
  const today = new Date().toISOString().split('T')[0];
  const followUps = openLeads.filter(l => {
    if (l.nextFollowUp === today) return true;
    const lastContact = new Date(l.lastContactDate);
    const diffDays = Math.floor((new Date().getTime() - lastContact.getTime()) / (1000 * 3600 * 24));
    return diffDays > 5;
  });

  // Funnel data
  const stages = [
    { id: 'discovery', label: 'DISCOVERY' },
    { id: 'proposal', label: 'PROPOSAL' },
    { id: 'revision', label: 'REVISION' },
    { id: 'closing', label: 'CLOSING' },
    { id: 'won', label: 'WON' }
  ];

  const funnelStats = stages.map(stage => {
    const stageLeads = leads.filter(l => l.stage === stage.id);
    return {
      ...stage,
      count: stageLeads.length,
      value: stageLeads.reduce((acc, l) => acc + (l.monthlyValueINR || 0), 0),
    };
  });

  const maxCount = Math.max(...funnelStats.map(s => s.count), 1);

  return (
    <div className="space-y-6">
      {/* SUMMARY STRIP */}
      <div className="bg-[var(--c-surface)] border border-[var(--c-border)] rounded-xl p-4 shadow-sm flex flex-wrap items-center justify-between gap-4">
        <div className="flex items-center gap-2">
          <span className="text-xs font-bold uppercase tracking-wider text-[var(--c-text-2)] bg-[var(--c-surface-2)] px-2 py-1 rounded">
            Sales Snapshot — July 2026
          </span>
        </div>
        <div className="flex flex-wrap gap-6 text-sm">
          <div className="flex flex-col">
            <span className="text-[var(--c-text-2)]">Open Leads</span>
            <span className="font-bold text-lg">{openLeads.length}</span>
          </div>
          <div className="flex flex-col">
            <span className="text-[var(--c-text-2)]">Pipeline Value</span>
            <span className="font-bold text-lg text-emerald-500">₹{pipelineValue.toLocaleString()}/mo</span>
          </div>
          <div className="flex flex-col">
            <span className="text-[var(--c-text-2)]">Won This Month</span>
            <span className="font-bold text-lg">{wonThisMonth}</span>
          </div>
          <div className="flex flex-col">
            <span className="text-[var(--c-text-2)]">Lost</span>
            <span className="font-bold text-lg">{lostThisMonth}</span>
          </div>
          <div className="flex flex-col">
            <span className="text-[var(--c-text-2)]">Follow-ups Today</span>
            <span className="font-bold text-lg text-orange-500">{followUps.length}</span>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">
        {/* VISUAL FUNNEL */}
        <div className="xl:col-span-2 bg-[var(--c-surface)] border border-[var(--c-border)] rounded-xl p-6 shadow-sm">
          <h3 className="font-semibold text-[var(--c-text)] mb-6 uppercase text-sm tracking-wider">Conversion Funnel</h3>

          <div className="flex flex-col md:flex-row gap-8 items-center md:items-start justify-center">

            {/* The CSS Funnel */}
            <div className="flex flex-col items-center space-y-1 w-full max-w-[280px]">
              {funnelStats.map((stat, i) => {
                const widthPercent = Math.max(30, (stat.count / maxCount) * 100);
                const isWon = stat.id === 'won';

                // Color gradient step
                const opacity = 1 - (i * 0.15);

                return (
                  <div key={stat.id} className="w-full flex flex-col items-center group cursor-pointer" onClick={() => onStageClick(stat.id)}>
                    <div className="text-[10px] font-bold text-[var(--c-text-2)] mb-1 uppercase tracking-wider group-hover:text-emerald-500 transition-colors">
                      {stat.label}
                    </div>
                    <div 
                      className={`h-12 flex items-center justify-center text-white font-bold text-sm shadow-inner transition-all group-hover:scale-[1.02] ${isWon ? 'rounded-b-xl rounded-t-sm' : 'rounded-sm'}`}
                      style={{ 
                        width: `${widthPercent}%`,
                        backgroundColor: `rgba(16, 185, 129, ${opacity})`,
                        clipPath: isWon ? 'none' : 'polygon(0 0, 100% 0, 95% 100%, 5% 100%)' // Trapezoid effect
                      }}
                    >
                      {stat.count} {isWon && '✅'}
                    </div>
                    {i < funnelStats.length - 1 && (
                      <div className="h-4 w-px bg-[var(--c-border)] my-1 relative">
                        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 text-[8px] text-[var(--c-text-3)] bg-[var(--c-surface)] px-1 rotate-90">▼</div>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>

            {/* Funnel Metrics Beside */}
            <div className="flex-1 w-full border-t md:border-t-0 md:border-l border-[var(--c-border)] pt-6 md:pt-0 md:pl-6 space-y-4">
              <table className="w-full text-sm text-left">
                <thead>
                  <tr className="text-[10px] uppercase text-[var(--c-text-2)] border-b border-[var(--c-border)]">
                    <th className="pb-2 font-semibold">Stage</th>
                    <th className="pb-2 font-semibold text-right">Leads</th>
                    <th className="pb-2 font-semibold text-right">Value/mo</th>
                    <th className="pb-2 font-semibold pl-4">Avg days</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-[var(--c-border)]">
                  {funnelStats.map(stat => (
                    <tr key={stat.id} className="group hover:bg-[var(--c-surface-2)] transition-colors cursor-pointer" onClick={() => onStageClick(stat.id)}>
                      <td className="py-3 font-medium text-[var(--c-text)]">{stat.label}</td>
                      <td className="py-3 text-right">{stat.count}</td>
                      <td className="py-3 text-right text-emerald-500 font-medium">₹{stat.value.toLocaleString()}</td>
                      <td className="py-3 pl-4 text-[var(--c-text-2)] text-xs">
                        {stat.id === 'won' ? '22d to close ✅' : stat.id === 'discovery' ? '4.2 days' : stat.id === 'proposal' ? '8.1 days' : stat.id === 'revision' ? '12.4 days' : '6.0 days'}
                      </td>
                    </tr>
                  ))}
                  <tr className="group hover:bg-[var(--c-surface-2)] transition-colors cursor-pointer" onClick={() => onStageClick('lost')}>
                    <td className="py-3 font-medium text-[var(--c-text)]">LOST (this mo)</td>
                    <td className="py-3 text-right">{lostThisMonth}</td>
                    <td className="py-3 text-right text-emerald-500 font-medium">
                      ₹{leads.filter(l => l.stage === 'lost').reduce((acc, l) => acc + (l.monthlyValueINR || 0), 0).toLocaleString()}
                    </td>
                    <td className="py-3 pl-4 text-[var(--c-text-2)] text-xs text-red-500 truncate max-w-[120px]">
                      (YM Motors - Price)
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>

          </div>
        </div>

        {/* TODAY'S ACTIONS */}
        <div className="bg-[var(--c-surface)] border border-[var(--c-border)] rounded-xl p-6 shadow-sm flex flex-col">
          <div className="flex justify-between items-center mb-6">
            <h3 className="font-semibold text-[var(--c-text)] uppercase text-sm tracking-wider">Today's Follow-ups ({followUps.length})</h3>
          </div>

          <div className="flex-1 overflow-y-auto custom-scrollbar -mx-2 px-2 space-y-3">
            {followUps.map(lead => {
              const lastContact = new Date(lead.lastContactDate);
              const diffDays = Math.floor((new Date().getTime() - lastContact.getTime()) / (1000 * 3600 * 24));

              const isUrgent = diffDays >= 9;
              const isWarm = diffDays >= 5 && diffDays < 9;
              const isPending = lead.nextFollowUp === today;

              let tag = null;
              if (isUrgent) tag = <span className="text-[10px] font-bold text-red-500 bg-red-500/10 px-1.5 py-0.5 rounded uppercase flex items-center gap-1"><span className="w-1.5 h-1.5 rounded-full bg-red-500"></span>Urgent</span>;
              else if (isWarm) tag = <span className="text-[10px] font-bold text-amber-500 bg-amber-500/10 px-1.5 py-0.5 rounded uppercase flex items-center gap-1"><span className="w-1.5 h-1.5 rounded-full bg-amber-500"></span>Warm</span>;
              else if (isPending) tag = <span className="text-[10px] font-bold text-yellow-500 bg-yellow-500/10 px-1.5 py-0.5 rounded uppercase flex items-center gap-1"><span className="w-1.5 h-1.5 rounded-full bg-yellow-500"></span>Pending</span>;

              return (
                <div key={lead.id} className="p-3 border border-[var(--c-border)] rounded-lg hover:border-emerald-500/50 transition-colors bg-[var(--c-surface-2)]">
                  <div className="flex justify-between items-start mb-2">
                    <div className="flex items-center gap-2">
                      {tag}
                      <span className="font-semibold text-sm">{lead.contactPerson}</span>
                    </div>
                  </div>
                  <div className="text-xs text-[var(--c-text-2)] mb-3 flex items-center gap-2">
                    <span>{lead.name}</span>
                    <span>•</span>
                    <span className="capitalize">{lead.stage}</span>
                    <span>•</span>
                    <span className={isUrgent ? 'text-red-500' : ''}>
                      {diffDays === 0 ? 'Contacted today' : `No contact in ${diffDays}d`}
                    </span>
                  </div>
                  <div className="flex gap-2">
                    <button className="flex-1 text-[10px] font-medium border border-[var(--c-border)] rounded py-1.5 hover:bg-[var(--c-surface)]">Log Call</button>
                    <button className="flex-1 text-[10px] font-medium border border-[var(--c-border)] rounded py-1.5 bg-[#25D366]/10 text-[#25D366] hover:bg-[#25D366]/20">WhatsApp</button>
                  </div>
                </div>
              );
            })}

            {followUps.length === 0 && (
              <div className="text-center py-10 text-[var(--c-text-2)] text-sm">
                No follow-ups due today!
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { useApp } from '@/contexts/AppContext';

export default function SalesPipeline({ isReadOnly }: { isReadOnly: boolean }) {
  const { state, dispatch } = useApp();
  const leads = state.leads || [];

  const columns = [
    { id: 'discovery', label: 'DISCOVERY' },
    { id: 'proposal', label: 'PROPOSAL' },
    { id: 'revision', label: 'REVISION' },
    { id: 'closing', label: 'CLOSING' },
    { id: 'won', label: 'WON (this mo)' },
    { id: 'lost', label: 'LOST (this mo)' },
    { id: 'paused', label: 'PAUSED' }
  ];

  const handleDragStart = (e: React.DragEvent, leadId: string) => {
    if (isReadOnly) return;
    e.dataTransfer.setData('leadId', leadId);
  };

  const handleDragOver = (e: React.DragEvent) => {
    if (isReadOnly) return;
    e.preventDefault();
  };

  const handleDrop = (e: React.DragEvent, targetStage: string) => {
    if (isReadOnly) return;
    e.preventDefault();
    const leadId = e.dataTransfer.getData('leadId');
    if (!leadId) return;

    const leadIndex = leads.findIndex(l => l.id === leadId);
    if (leadIndex === -1) return;

    const lead = leads[leadIndex];
    if (lead.stage === targetStage) return;

    const updatedLead = {
      ...lead,
      stage: targetStage as any,
      stageHistory: [...(lead.stageHistory || []), { stage: targetStage, date: new Date().toISOString().split('T')[0] }]
    };

    const newLeads = [...leads];
    newLeads[leadIndex] = updatedLead;

    dispatch({ type: 'UPDATE_LEAD', payload: updatedLead });
  };

  return (
    <div className="flex-1 flex overflow-x-auto overflow-y-hidden custom-scrollbar pb-4 -mx-6 px-6 gap-4">
      {columns.map(col => {
        const colLeads = leads.filter(l => l.stage === col.id);
        const colValue = colLeads.reduce((acc, l) => acc + (l.monthlyValueINR || 0), 0);

        return (
          <div 
            key={col.id} 
            className="w-72 shrink-0 flex flex-col h-full bg-[var(--c-surface)] rounded-xl border border-[var(--c-border)]"
            onDragOver={handleDragOver}
            onDrop={(e) => handleDrop(e, col.id)}
          >
            {/* Column Header */}
            <div className="p-4 border-b border-[var(--c-border)] bg-[var(--c-surface-2)] rounded-t-xl shrink-0">
              <div className="flex justify-between items-center mb-1">
                <h3 className="font-semibold text-sm">{col.label} ({colLeads.length})</h3>
              </div>
              <div className="text-emerald-500 font-medium text-xs">
                {col.id === 'won' ? `${colLeads.length} deals` : `₹${colValue.toLocaleString()}/mo`}
              </div>
            </div>

            {/* Column Body */}
            <div className="flex-1 overflow-y-auto custom-scrollbar p-3 space-y-3">
              {colLeads.map(lead => {
                const isWon = lead.stage === 'won';
                const isLost = lead.stage === 'lost';

                return (
                  <div 
                    key={lead.id}
                    draggable={!isReadOnly}
                    onDragStart={(e) => handleDragStart(e, lead.id)}
                    className={`bg-[var(--c-bg)] border border-[var(--c-border)] rounded-lg p-3 shadow-sm hover:border-[var(--c-text-3)] transition-colors ${!isReadOnly ? 'cursor-grab active:cursor-grabbing' : ''}`}
                  >
                    <div className="flex justify-between items-start mb-2">
                      <div className="font-semibold text-sm">{lead.contactPerson}</div>
                      <div className="w-5 h-5 rounded-full bg-emerald-500/10 text-emerald-600 flex items-center justify-center text-[10px] font-bold" title="Assigned BD">
                        {lead.assignedTo ? lead.assignedTo.replace('u-', '').substring(0, 1).toUpperCase() : 'S'}
                      </div>
                    </div>
                    <div className="text-xs text-[var(--c-text-2)] mb-1">{lead.name}</div>

                    <div className="text-sm font-medium text-emerald-500 mb-2">
                      ₹{lead.monthlyValueINR?.toLocaleString()}/mo
                    </div>

                    {lead.servicesNeeded && lead.servicesNeeded.length > 0 && (
                      <div className="flex flex-wrap gap-1 mb-3">
                        {lead.servicesNeeded.map((svc: string) => (
                          <span key={svc} className="text-[9px] font-bold text-purple-600 bg-purple-100 dark:bg-purple-900/30 dark:text-purple-400 px-1.5 py-0.5 rounded uppercase">
                            {svc.replace('_', ' ')}
                          </span>
                        ))}
                      </div>
                    )}

                    <div className="text-[10px] text-[var(--c-text-2)] flex flex-wrap gap-1 mb-3">
                      {isWon ? (
                        <span className="text-emerald-500 bg-emerald-500/10 px-1.5 py-0.5 rounded">Closed ✅</span>
                      ) : isLost ? (
                        <span className="text-red-500 bg-red-500/10 px-1.5 py-0.5 rounded">{lead.lostReason || 'Lost'}</span>
                      ) : (
                        <span className="bg-[var(--c-surface-2)] px-1.5 py-0.5 rounded border border-[var(--c-border)]">Last: {lead.lastContactDate}</span>
                      )}
                    </div>

                    {/* Next Action Button (mock) */}
                    {!isReadOnly && !isWon && !isLost && (
                      <button className="w-full text-center text-xs font-medium py-1.5 rounded border border-[var(--c-border)] hover:bg-[var(--c-surface-2)] transition-colors text-[var(--c-text-2)] hover:text-[var(--c-text)]">
                        {lead.stage === 'discovery' ? '→ Proposal' : lead.stage === 'proposal' ? '→ Revision' : lead.stage === 'revision' ? '→ Closing' : '→ Won'}
                      </button>
                    )}
                    {isWon && (
                      <button className="w-full text-center text-xs font-medium py-1.5 rounded border border-emerald-500/20 text-emerald-600 bg-emerald-500/5 hover:bg-emerald-500/10 transition-colors">
                        View Contract →
                      </button>
                    )}
                  </div>
                );
              })}

              {colLeads.length === 0 && (
                <div className="h-24 flex items-center justify-center border-2 border-dashed border-[var(--c-border)] rounded-lg text-xs text-[var(--c-text-3)]">
                  Empty
                </div>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
}

'use client';

import { useState, useMemo, useRef, useEffect } from 'react';
import { Task, PRIORITY_CONFIG, STATUS_CONFIG, Client } from '@/lib/data';
import { GoogleEvent } from '@/lib/googleCalendar';

// ─── Helpers ────────────────────────────────────────────────────────────────

function isoDate(d: Date) {
  return d.toISOString().split('T')[0];
}

function startOfWeek(d: Date) {
  const s = new Date(d);
  s.setDate(d.getDate() - d.getDay());
  s.setHours(0, 0, 0, 0);
  return s;
}

function addDays(d: Date, n: number) {
  const r = new Date(d);
  r.setDate(r.getDate() + n);
  return r;
}

const DAY_LABELS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const HOURS = Array.from({ length: 24 }, (_, i) => i);

// ─── Month View ─────────────────────────────────────────────────────────────

function MonthView({
  tasks,
  googleEvents,
  currentDate,
  onTaskClick,
  onDayClick,
}: {
  tasks: Task[];
  googleEvents: GoogleEvent[];
  currentDate: Date;
  onTaskClick: (id: string) => void;
  onDayClick: (d: Date) => void;
}) {
  const year = currentDate.getFullYear();
  const month = currentDate.getMonth();
  const firstDow = new Date(year, month, 1).getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const totalCells = Math.ceil((firstDow + daysInMonth) / 7) * 7;
  const todayStr = isoDate(new Date());

  return (
    <div className="flex flex-col h-full">
      {/* Day headers */}
      <div className="grid grid-cols-7 flex-shrink-0 mb-1">
        {DAY_LABELS.map(d => (
          <div key={d} className="text-center text-[11px] font-black uppercase tracking-wider py-2" style={{ color: 'var(--c-text-3)' }}>
            {d}
          </div>
        ))}
      </div>

      {/* Grid */}
      <div className="grid grid-cols-7 gap-px flex-1 min-h-0" style={{ background: 'var(--c-border)' }}>
        {Array.from({ length: totalCells }).map((_, i) => {
          const dayNum = i - firstDow + 1;
          const cellDate = new Date(year, month, dayNum);
          const cellStr = isoDate(cellDate);
          const isCurrentMonth = cellDate.getMonth() === month;
          const isToday = cellStr === todayStr;

          const dayTasks = tasks.filter(t => t.deadline?.startsWith(cellStr));
          const dayEvents = googleEvents.filter(evt =>
            evt.start.dateTime.startsWith(cellStr)
          );
          const overflow = dayTasks.length + dayEvents.length - 3;

          return (
            <div
              key={i}
              onClick={() => onDayClick(cellDate)}
              className="flex flex-col p-1.5 cursor-pointer transition-colors min-h-[100px]"
              style={{
                background: isToday ? 'rgba(42,177,130,0.05)' : 'var(--c-surface)',
                opacity: isCurrentMonth ? 1 : 0.38,
              }}
            >
              {/* Day number */}
              <div className="flex items-center justify-between mb-1">
                <span
                  className="text-[12px] font-bold w-6 h-6 flex items-center justify-center rounded-full"
                  style={{
                    background: isToday ? '#2AB182' : 'transparent',
                    color: isToday ? 'white' : 'var(--c-text-2)',
                  }}
                >
                  {cellDate.getDate()}
                </span>
                {dayEvents.length > 0 && (
                  <div className="w-1.5 h-1.5 rounded-full" style={{ background: '#4285F4' }} />
                )}
              </div>

              {/* Task chips (up to 2) */}
              <div className="flex flex-col gap-0.5 flex-1">
                {dayTasks.slice(0, 2).map(t => (
                  <div
                    key={t.id}
                    onClick={e => { e.stopPropagation(); onTaskClick(t.id); }}
                    className="text-[9px] font-bold truncate px-1.5 py-0.5 rounded cursor-pointer hover:opacity-80 transition-opacity"
                    style={{
                      background: PRIORITY_CONFIG[t.priority].bg,
                      color: PRIORITY_CONFIG[t.priority].color,
                    }}
                    title={t.title}
                  >
                    {t.title}
                  </div>
                ))}
                {/* Google event chips */}
                {dayEvents.slice(0, dayTasks.length >= 2 ? 0 : 2 - dayTasks.length).map(evt => (
                  <div
                    key={evt.id}
                    className="text-[9px] font-bold truncate px-1.5 py-0.5 rounded"
                    style={{ background: 'rgba(66,133,244,0.12)', color: '#4285F4' }}
                    title={evt.summary}
                  >
                    📅 {evt.summary}
                  </div>
                ))}
                {overflow > 0 && (
                  <div className="text-[9px] font-bold" style={{ color: 'var(--c-text-3)' }}>
                    +{overflow} more
                  </div>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ─── Week View ───────────────────────────────────────────────────────────────

function WeekView({
  tasks,
  googleEvents,
  currentDate,
  onTaskClick,
  onDayClick,
}: {
  tasks: Task[];
  googleEvents: GoogleEvent[];
  currentDate: Date;
  onTaskClick: (id: string) => void;
  onDayClick: (d: Date) => void;
}) {
  const weekStart = startOfWeek(currentDate);
  const days = Array.from({ length: 7 }, (_, i) => addDays(weekStart, i));
  const todayStr = isoDate(new Date());
  const nowRef = useRef<HTMLDivElement>(null);
  const now = new Date();
  const nowPx = now.getHours() * 60 + now.getMinutes();

  useEffect(() => {
    if (nowRef.current) {
      nowRef.current.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
  }, []);

  return (
    <div className="flex flex-col h-full">
      {/* Day header row */}
      <div className="grid flex-shrink-0" style={{ gridTemplateColumns: '52px repeat(7, 1fr)' }}>
        <div /> {/* time gutter */}
        {days.map(d => {
          const dStr = isoDate(d);
          const isToday = dStr === todayStr;
          return (
            <div
              key={dStr}
              onClick={() => onDayClick(d)}
              className="text-center py-2 cursor-pointer"
              style={{ borderBottom: '1px solid var(--c-border)' }}
            >
              <p className="text-[10px] font-black uppercase tracking-wider mb-0.5" style={{ color: isToday ? '#2AB182' : 'var(--c-text-3)' }}>
                {DAY_LABELS[d.getDay()]}
              </p>
              <div
                className="w-7 h-7 rounded-full mx-auto flex items-center justify-center text-[14px] font-bold"
                style={{
                  background: isToday ? '#2AB182' : 'transparent',
                  color: isToday ? 'white' : 'var(--c-text)',
                }}
              >
                {d.getDate()}
              </div>
            </div>
          );
        })}
      </div>

      {/* Deadline task pills at top */}
      <div className="grid flex-shrink-0 mb-1" style={{ gridTemplateColumns: '52px repeat(7, 1fr)' }}>
        <div className="text-[9px] font-bold flex items-center justify-end pr-2" style={{ color: 'var(--c-text-3)' }}>All day</div>
        {days.map(d => {
          const dStr = isoDate(d);
          const dayTasks = tasks.filter(t => t.deadline?.startsWith(dStr));
          return (
            <div key={dStr} className="min-h-[28px] p-0.5 flex flex-col gap-0.5" style={{ borderLeft: '1px solid var(--c-border)' }}>
              {dayTasks.slice(0, 2).map(t => (
                <div
                  key={t.id}
                  onClick={() => onTaskClick(t.id)}
                  className="text-[9px] font-bold truncate px-1.5 py-0.5 rounded cursor-pointer hover:opacity-80"
                  style={{ background: PRIORITY_CONFIG[t.priority].bg, color: PRIORITY_CONFIG[t.priority].color }}
                >
                  {t.title}
                </div>
              ))}
            </div>
          );
        })}
      </div>

      {/* Time grid */}
      <div className="flex-1 overflow-y-auto relative custom-scrollbar">
        <div className="relative" style={{ height: `${24 * 60}px` }}>
          {/* Hour lines + labels */}
          {HOURS.map(h => (
            <div
              key={h}
              className="absolute left-0 right-0 flex items-start"
              style={{ top: `${h * 60}px`, height: '60px' }}
            >
              <span
                className="text-[9px] font-bold w-12 text-right pr-2 flex-shrink-0 -mt-2.5"
                style={{ color: 'var(--c-text-3)' }}
              >
                {h === 0 ? '' : `${h}:00`}
              </span>
              <div className="flex-1 border-t" style={{ borderColor: 'var(--c-border)' }} />
            </div>
          ))}

          {/* Google events */}
          <div className="absolute left-12 right-0 top-0 bottom-0 grid" style={{ gridTemplateColumns: 'repeat(7, 1fr)' }}>
            {days.map(d => {
              const dStr = isoDate(d);
              const isToday = dStr === todayStr;
              const dayEvents = googleEvents.filter(evt => evt.start.dateTime.startsWith(dStr));
              return (
                <div
                  key={dStr}
                  className="relative"
                  style={{
                    borderLeft: '1px solid var(--c-border)',
                    background: isToday ? 'rgba(42,177,130,0.03)' : 'transparent',
                  }}
                >
                  {dayEvents.map(evt => {
                    const start = new Date(evt.start.dateTime);
                    const end = new Date(evt.end.dateTime);
                    const top = start.getHours() * 60 + start.getMinutes();
                    const height = Math.max(20, (end.getTime() - start.getTime()) / 60000);
                    return (
                      <div
                        key={evt.id}
                        className="absolute left-0.5 right-0.5 rounded-md px-1.5 py-1 overflow-hidden cursor-pointer hover:opacity-90 transition-opacity"
                        style={{
                          top: `${top}px`,
                          height: `${height}px`,
                          background: 'rgba(66,133,244,0.18)',
                          border: '1px solid rgba(66,133,244,0.35)',
                          zIndex: 5,
                        }}
                        title={evt.summary}
                      >
                        <p className="text-[9px] font-bold truncate" style={{ color: '#4285F4' }}>{evt.summary}</p>
                        <p className="text-[8px]" style={{ color: '#4285F4', opacity: 0.8 }}>
                          {start.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                        </p>
                        {evt.meetLink && (
                          <a
                            href={evt.meetLink}
                            target="_blank"
                            rel="noopener noreferrer"
                            onClick={e => e.stopPropagation()}
                            className="text-[8px] font-bold mt-0.5 block"
                            style={{ color: '#4285F4' }}
                          >
                            📹 Join
                          </a>
                        )}
                      </div>
                    );
                  })}
                </div>
              );
            })}
          </div>

          {/* NOW line */}
          <div
            ref={nowRef}
            className="absolute left-12 right-0 z-20 pointer-events-none flex items-center"
            style={{ top: `${nowPx}px` }}
          >
            <div className="w-2 h-2 rounded-full flex-shrink-0" style={{ background: '#EF4444', marginLeft: '-4px' }} />
            <div className="flex-1 border-t border-red-500" style={{ borderStyle: 'solid' }} />
          </div>
        </div>
      </div>
    </div>
  );
}

// ─── Day View ────────────────────────────────────────────────────────────────

function DayView({
  tasks,
  googleEvents,
  currentDate,
  onTaskClick,
}: {
  tasks: Task[];
  googleEvents: GoogleEvent[];
  currentDate: Date;
  onTaskClick: (id: string) => void;
}) {
  const dStr = isoDate(currentDate);
  const dayTasks = tasks.filter(t => t.deadline?.startsWith(dStr));
  const dayEvents = googleEvents.filter(evt => evt.start.dateTime.startsWith(dStr));
  const isToday = dStr === isoDate(new Date());
  const now = new Date();
  const nowPx = now.getHours() * 60 + now.getMinutes();
  const nowRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (nowRef.current) {
      nowRef.current.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
  }, []);

  return (
    <div className="flex flex-col h-full">
      {/* Day header */}
      <div
        className="flex items-center gap-4 px-4 py-3 flex-shrink-0"
        style={{ borderBottom: '1px solid var(--c-border)', background: 'var(--c-surface-2)' }}
      >
        <div
          className="w-10 h-10 rounded-xl flex items-center justify-center text-[18px] font-black"
          style={{
            background: isToday ? '#2AB182' : 'var(--c-surface)',
            color: isToday ? 'white' : 'var(--c-text)',
          }}
        >
          {currentDate.getDate()}
        </div>
        <div>
          <p className="text-[16px] font-bold" style={{ color: 'var(--c-text)' }}>
            {currentDate.toLocaleDateString('en-IN', { weekday: 'long', month: 'long', day: 'numeric' })}
          </p>
          <p className="text-[12px]" style={{ color: 'var(--c-text-3)' }}>
            {dayTasks.length} task{dayTasks.length !== 1 ? 's' : ''} due · {dayEvents.length} meeting{dayEvents.length !== 1 ? 's' : ''}
          </p>
        </div>
      </div>

      {/* All-day tasks */}
      {dayTasks.length > 0 && (
        <div
          className="px-4 py-2.5 flex-shrink-0 flex flex-wrap gap-1.5"
          style={{ borderBottom: '1px solid var(--c-border)', background: 'var(--c-surface-2)' }}
        >
          <span className="text-[10px] font-black uppercase tracking-wider mr-2 self-center" style={{ color: 'var(--c-text-3)' }}>Due today</span>
          {dayTasks.map(t => (
            <button
              key={t.id}
              onClick={() => onTaskClick(t.id)}
              className="text-[10px] font-bold px-2.5 py-1 rounded-lg cursor-pointer hover:opacity-80 transition-opacity"
              style={{ background: PRIORITY_CONFIG[t.priority].bg, color: PRIORITY_CONFIG[t.priority].color }}
            >
              {t.title}
            </button>
          ))}
        </div>
      )}

      {/* Time grid */}
      <div className="flex-1 overflow-y-auto relative custom-scrollbar">
        <div className="relative" style={{ height: `${24 * 60}px` }}>
          {HOURS.map(h => (
            <div
              key={h}
              className="absolute left-0 right-0 flex items-start"
              style={{ top: `${h * 60}px`, height: '60px' }}
            >
              <span
                className="text-[10px] font-bold w-14 text-right pr-3 flex-shrink-0 -mt-2.5"
                style={{ color: 'var(--c-text-3)' }}
              >
                {h === 0 ? '' : `${String(h).padStart(2, '0')}:00`}
              </span>
              <div className="flex-1 border-t" style={{ borderColor: 'var(--c-border)' }} />
            </div>
          ))}

          {/* Events */}
          <div className="absolute left-14 right-2 top-0 bottom-0">
            {dayEvents.map(evt => {
              const start = new Date(evt.start.dateTime);
              const end = new Date(evt.end.dateTime);
              const top = start.getHours() * 60 + start.getMinutes();
              const height = Math.max(30, (end.getTime() - start.getTime()) / 60000);
              return (
                <div
                  key={evt.id}
                  className="absolute left-0 right-0 rounded-xl px-3 py-2 overflow-hidden cursor-pointer hover:opacity-90"
                  style={{
                    top: `${top}px`,
                    height: `${height}px`,
                    background: 'rgba(66,133,244,0.14)',
                    border: '1px solid rgba(66,133,244,0.35)',
                    borderLeft: '4px solid #4285F4',
                  }}
                >
                  <p className="text-[12px] font-bold truncate mb-0.5" style={{ color: '#4285F4' }}>{evt.summary}</p>
                  <p className="text-[11px]" style={{ color: '#4285F4', opacity: 0.8 }}>
                    {start.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })} –{' '}
                    {end.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </p>
                  {evt.meetLink && (
                    <a
                      href={evt.meetLink}
                      target="_blank"
                      rel="noopener noreferrer"
                      onClick={e => e.stopPropagation()}
                      className="inline-flex items-center gap-1 text-[10px] font-bold mt-1 px-2 py-0.5 rounded-lg"
                      style={{ background: 'rgba(66,133,244,0.2)', color: '#4285F4' }}
                    >
                      📹 Join meeting
                    </a>
                  )}
                </div>
              );
            })}
          </div>

          {/* NOW line */}
          {isToday && (
            <div
              ref={nowRef}
              className="absolute left-14 right-0 z-20 pointer-events-none flex items-center"
              style={{ top: `${nowPx}px` }}
            >
              <div className="w-2 h-2 rounded-full flex-shrink-0" style={{ background: '#EF4444', marginLeft: '-4px' }} />
              <div className="flex-1 border-t-2" style={{ borderColor: '#EF4444' }} />
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

// ─── Main CalendarView ────────────────────────────────────────────────────────

type CalendarSubView = 'month' | 'week' | 'day';

interface Props {
  tasks: Task[];
  googleEvents: GoogleEvent[];
  onTaskClick: (id: string) => void;
}

export default function CalendarView({ tasks, googleEvents, onTaskClick }: Props) {
  const [subView, setSubView] = useState<CalendarSubView>('month');
  const [currentDate, setCurrentDate] = useState(new Date());

  const navigatePrev = () => {
    const d = new Date(currentDate);
    if (subView === 'month') d.setMonth(d.getMonth() - 1);
    else if (subView === 'week') d.setDate(d.getDate() - 7);
    else d.setDate(d.getDate() - 1);
    setCurrentDate(d);
  };

  const navigateNext = () => {
    const d = new Date(currentDate);
    if (subView === 'month') d.setMonth(d.getMonth() + 1);
    else if (subView === 'week') d.setDate(d.getDate() + 7);
    else d.setDate(d.getDate() + 1);
    setCurrentDate(d);
  };

  const headerLabel = useMemo(() => {
    if (subView === 'month') return currentDate.toLocaleDateString('en-IN', { month: 'long', year: 'numeric' });
    if (subView === 'week') {
      const ws = startOfWeek(currentDate);
      const we = addDays(ws, 6);
      return `${ws.toLocaleDateString('en-IN', { day: 'numeric', month: 'short' })} – ${we.toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })}`;
    }
    return currentDate.toLocaleDateString('en-IN', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
  }, [subView, currentDate]);

  const handleDayClick = (d: Date) => {
    setCurrentDate(d);
    setSubView('day');
  };

  return (
    <div className="flex flex-col h-full rounded-2xl overflow-hidden" style={{ border: '1px solid var(--c-border)', background: 'var(--c-surface)' }}>
      {/* Toolbar */}
      <div
        className="flex items-center justify-between px-4 py-3 flex-shrink-0"
        style={{ borderBottom: '1px solid var(--c-border)', background: 'var(--c-surface-2)' }}
      >
        {/* Nav */}
        <div className="flex items-center gap-2">
          <button
            onClick={() => setCurrentDate(new Date())}
            className="px-3 py-1.5 rounded-lg text-[12px] font-bold transition-all hover:opacity-80"
            style={{ background: 'var(--c-surface)', border: '1px solid var(--c-border)', color: 'var(--c-text-2)' }}
          >
            Today
          </button>
          <button
            onClick={navigatePrev}
            className="w-8 h-8 rounded-lg flex items-center justify-center transition-all hover:opacity-80"
            style={{ background: 'var(--c-surface)', border: '1px solid var(--c-border)', color: 'var(--c-text-2)' }}
          >
            ‹
          </button>
          <button
            onClick={navigateNext}
            className="w-8 h-8 rounded-lg flex items-center justify-center transition-all hover:opacity-80"
            style={{ background: 'var(--c-surface)', border: '1px solid var(--c-border)', color: 'var(--c-text-2)' }}
          >
            ›
          </button>
          <h3 className="text-[15px] font-bold ml-1" style={{ color: 'var(--c-text)', fontFamily: 'var(--font-syne-var)' }}>
            {headerLabel}
          </h3>
        </div>

        {/* Sub-view switcher */}
        <div className="flex items-center gap-1 p-1 rounded-lg" style={{ background: 'var(--c-surface)', border: '1px solid var(--c-border)' }}>
          {(['month', 'week', 'day'] as const).map(sv => (
            <button
              key={sv}
              onClick={() => setSubView(sv)}
              className="px-4 py-1.5 rounded-md text-[12px] font-bold capitalize transition-all"
              style={{
                background: subView === sv ? '#2AB182' : 'transparent',
                color: subView === sv ? 'white' : 'var(--c-text-2)',
              }}
            >
              {sv}
            </button>
          ))}
        </div>
      </div>

      {/* View content */}
      <div className="flex-1 min-h-0 overflow-hidden">
        {subView === 'month' && (
          <MonthView
            tasks={tasks}
            googleEvents={googleEvents}
            currentDate={currentDate}
            onTaskClick={onTaskClick}
            onDayClick={handleDayClick}
          />
        )}
        {subView === 'week' && (
          <WeekView
            tasks={tasks}
            googleEvents={googleEvents}
            currentDate={currentDate}
            onTaskClick={onTaskClick}
            onDayClick={(d) => { setCurrentDate(d); setSubView('day'); }}
          />
        )}
        {subView === 'day' && (
          <DayView
            tasks={tasks}
            googleEvents={googleEvents}
            currentDate={currentDate}
            onTaskClick={onTaskClick}
          />
        )}
      </div>
    </div>
  );
}

'use client';
import { useState, useRef, MouseEvent, useEffect } from 'react';
import { useApp } from '@/contexts/AppContext';
import TaskDrawer from '@/components/tasks/TaskDrawer';
import { PRIORITY_CONFIG } from '@/lib/data';
import { AlignLeft, ChevronLeft, ChevronRight, GripVertical, ChevronDown } from 'lucide-react';

export default function GanttView({ 
  selectedTaskId, 
  setSelectedTaskId, 
  clientFilter, 
  memberFilter 
}: { 
  selectedTaskId: string | null; 
  setSelectedTaskId: (id: string | null) => void;
  clientFilter: string;
  memberFilter: string;
}) {
  const { state, updateTask } = useApp();
  const [zoomLevel, setZoomLevel] = useState<'day' | 'week' | 'month'>('day');
  const [zoomMultiplier, setZoomMultiplier] = useState(1);

  const timelineRef = useRef<HTMLDivElement>(null);

  // Panning state
  const [isPanning, setIsPanning] = useState(false);
  const [startX, setStartX] = useState(0);
  const [scrollLeft, setScrollLeft] = useState(0);

  // Task Dragging state
  const [draggingTaskId, setDraggingTaskId] = useState<string | null>(null);
  const [dragOffsetDays, setDragOffsetDays] = useState(0);
  const [dragMode, setDragMode] = useState<'move' | 'extend-left' | 'extend-right'>('move');

  const BASE_UNIT_WIDTH = zoomLevel === 'day' ? 60 : zoomLevel === 'week' ? 40 : 30;
  const UNIT_WIDTH = BASE_UNIT_WIDTH * zoomMultiplier;
  const numUnits = zoomLevel === 'day' ? 48 : zoomLevel === 'week' ? 30 : 90;

  // Helper to get a Date object whose local time methods return IST values
  const getISTDate = (dateInput: Date | string | number = new Date()) => {
    const d = new Date(dateInput);
    const utc = d.getTime() + (d.getTimezoneOffset() * 60000);
    return new Date(utc + (3600000 * 5.5)); // IST is +5:30
  };

  const [today, setToday] = useState<Date>(() => {
    const d = getISTDate();
    d.setHours(0,0,0,0);
    return d;
  });

  const [startDate, setStartDate] = useState(() => {
    const d = getISTDate();
    d.setHours(0,0,0,0);
    d.setDate(d.getDate() - 1); // For 'day' view, start yesterday so 48 hrs covers yesterday & today
    return d;
  });

  useEffect(() => {
    // Update today dynamically if app stays open
    const interval = setInterval(() => {
      const d = getISTDate();
      d.setHours(0,0,0,0);
      setToday(d);
    }, 60000);
    return () => clearInterval(interval);
  }, []);

  const shiftDays = (days: number) => {
    const d = new Date(startDate);
    d.setDate(d.getDate() + days);
    setStartDate(d);
  };

  const units = Array.from({ length: numUnits }).map((_, i) => {
    const d = new Date(startDate);
    if (zoomLevel === 'day') {
      d.setHours(i, 0, 0, 0);
    } else {
      d.setDate(d.getDate() + i);
    }
    return d;
  });

  const getLeft = (date: Date | string) => {
    const d = getISTDate(date);
    if (zoomLevel === 'day') {
      const diffMs = d.getTime() - startDate.getTime();
      return (diffMs / (1000 * 60 * 60)) * UNIT_WIDTH;
    } else {
      const startOfDay = new Date(d);
      startOfDay.setHours(0,0,0,0);
      const diffDays = (startOfDay.getTime() - startDate.getTime()) / (1000 * 60 * 60 * 24);
      return diffDays * UNIT_WIDTH;
    }
  };

  const clients = clientFilter ? state.clients.filter(c => c.id === clientFilter) : state.clients;

  // Panning handlers
  const handleMouseDown = (e: MouseEvent) => {
    if (draggingTaskId) return; // don't pan if dragging a task
    if (!timelineRef.current) return;
    setIsPanning(true);
    setStartX(e.pageX - timelineRef.current.offsetLeft);
    setScrollLeft(timelineRef.current.scrollLeft);
  };

  const handleMouseMove = (e: MouseEvent) => {
    if (isPanning && timelineRef.current) {
      e.preventDefault();
      const x = e.pageX - timelineRef.current.offsetLeft;
      const walk = (x - startX) * 1.5; 
      timelineRef.current.scrollLeft = scrollLeft - walk;
    }
  };

  const handleMouseUp = () => {
    setIsPanning(false);
  };

  // Task Drag handlers
  const handleTaskDragStart = (e: MouseEvent, taskId: string, mode: 'move' | 'extend-left' | 'extend-right' = 'move') => {
    e.stopPropagation();
    setDraggingTaskId(taskId);
    setDragMode(mode);
    setDragOffsetDays(0);
    setStartX(e.pageX);
  };

  const handleTaskDragMove = (e: MouseEvent) => {
    if (draggingTaskId) {
      const diffX = e.pageX - startX;
      const unitsMoved = Math.round(diffX / UNIT_WIDTH);
      setDragOffsetDays(zoomLevel === 'day' ? unitsMoved / 24 : unitsMoved);
    }
  };

  const handleTaskDragEnd = (e: MouseEvent) => {
    if (draggingTaskId && dragOffsetDays !== 0) {
      const task = state.tasks.find(t => t.id === draggingTaskId);
      if (task) {
        if (dragMode === 'move' && task.deadline) {
          const d = new Date(task.deadline);
          d.setDate(d.getDate() + dragOffsetDays);

          const updateData: any = { deadline: d.toISOString() };
          if (task.startTime) {
            const st = new Date(task.startTime);
            st.setDate(st.getDate() + dragOffsetDays);
            updateData.startTime = st.toISOString();
          }
          updateTask(task.id, updateData);
        } else if (dragMode === 'extend-right' && task.deadline) {
          const d = new Date(task.deadline);
          d.setDate(d.getDate() + dragOffsetDays);
          updateTask(task.id, { deadline: d.toISOString() });
        } else if (dragMode === 'extend-left') {
          const st = task.startTime ? new Date(task.startTime) : new Date(task.createdAt);
          st.setDate(st.getDate() + dragOffsetDays);
          updateTask(task.id, { startTime: st.toISOString() });
        }
      }
    }
    setDraggingTaskId(null);
    setDragMode('move');
    setDragOffsetDays(0);
  };

  return (
    <div 
      className="flex flex-col h-full overflow-hidden select-none"
      onMouseMove={(e) => {
        handleMouseMove(e);
        handleTaskDragMove(e);
      }}
      onMouseUp={(e) => {
        handleMouseUp();
        handleTaskDragEnd(e);
      }}
      onMouseLeave={(e) => {
        handleMouseUp();
        handleTaskDragEnd(e);
      }}
    >
      <div className="flex items-center justify-between mb-4 flex-shrink-0">
        <div className="flex gap-3">
          <div className="flex bg-surface-2 rounded-lg p-1 items-center" style={{ border: '1px solid var(--c-border)' }}>
            <button 
              onClick={() => setZoomMultiplier(prev => Math.min(prev + 0.5, 5.0))} 
              className="px-2 hover:text-text transition-colors text-text-2 flex items-center"
              title="Zoom In"
            >
              <span className="material-symbols-outlined text-[18px]">add</span>
            </button>
            <button onClick={() => { setZoomLevel('day'); setZoomMultiplier(1); const d = getISTDate(); d.setHours(0,0,0,0); d.setDate(d.getDate() - 1); setStartDate(d); }} className={`px-2 py-1 rounded text-[11px] font-bold ${zoomLevel === 'day' ? 'bg-surface text-text shadow-sm' : 'text-text-2 hover:text-text'}`}>Day</button>
            <button onClick={() => { setZoomLevel('week'); setZoomMultiplier(1); const d = getISTDate(); d.setHours(0,0,0,0); d.setDate(d.getDate() - 5); setStartDate(d); }} className={`px-2 py-1 rounded text-[11px] font-bold ${zoomLevel === 'week' ? 'bg-surface text-text shadow-sm' : 'text-text-2 hover:text-text'}`}>Week</button>
            <button onClick={() => { setZoomLevel('month'); setZoomMultiplier(1); const d = getISTDate(); d.setHours(0,0,0,0); d.setDate(d.getDate() - 5); setStartDate(d); }} className={`px-2 py-1 rounded text-[11px] font-bold ${zoomLevel === 'month' ? 'bg-surface text-text shadow-sm' : 'text-text-2 hover:text-text'}`}>Month</button>
            <button 
              onClick={() => setZoomMultiplier(prev => Math.max(prev - 0.5, 0.25))} 
              className="px-2 hover:text-text transition-colors text-text-2 flex items-center"
              title="Zoom Out"
            >
              <span className="material-symbols-outlined text-[18px]">remove</span>
            </button>
          </div>
          <div className="flex bg-surface-2 rounded-lg p-1 items-center" style={{ border: '1px solid var(--c-border)' }}>
            <button onClick={() => shiftDays(zoomLevel === 'day' ? -1 : zoomLevel === 'week' ? -7 : zoomLevel === 'month' ? -30 : -90)} className="px-2 hover:text-text transition-colors text-text-2 flex items-center"><ChevronLeft className="w-5 h-5" /></button>
            <button onClick={() => {
              const d = getISTDate();
              d.setHours(0,0,0,0);
              d.setDate(d.getDate() - (zoomLevel === 'day' ? 1 : 5));
              setStartDate(d);
            }} className="px-3 text-[13px] font-bold text-text-2 hover:text-text transition-colors">Today</button>
            <button onClick={() => shiftDays(zoomLevel === 'day' ? 1 : zoomLevel === 'week' ? 7 : zoomLevel === 'month' ? 30 : 90)} className="px-2 hover:text-text transition-colors text-text-2 flex items-center"><ChevronRight className="w-5 h-5" /></button>
          </div>
        </div>
      </div>

      <div className="flex gap-5 mb-4 flex-shrink-0 items-center bg-surface-2 w-fit px-4 py-2 rounded-lg border border-border">
        <span className="text-[12px] font-bold uppercase tracking-widest text-text-3">Priority Legend</span>
        <div className="w-px h-4 bg-border mx-1"></div>
        {Object.entries(PRIORITY_CONFIG).map(([k, v]) => (
          <div key={k} className="flex items-center gap-2 text-[12px] font-semibold text-text-2">
            <span className="w-3 h-3 rounded shadow-sm" style={{ background: v.color }}></span>
            {v.label}
          </div>
        ))}
      </div>

      <div className="flex flex-1 min-h-0 border border-border rounded-xl bg-surface overflow-hidden shadow-sm">
        {/* Left Panel */}
        <div className="w-[280px] flex-shrink-0 border-r border-border flex flex-col bg-surface-2 z-20">
          <div className="h-[54px] border-b border-border flex items-center px-5 bg-surface-2">
            <span className="text-[12px] font-bold uppercase tracking-wider text-text-3">Task Details</span>
          </div>
          <div className="flex-1 overflow-y-auto pb-8 gantt-scrollbar">
            {clients.map(c => {
              let ctasks = state.tasks.filter(t => t.clientId === c.id && t.status !== 'done');
              if (memberFilter) {
                ctasks = ctasks.filter(t => t.assignedTo.includes(memberFilter));
              }
              if (ctasks.length === 0) return null;
              return (
                <div key={c.id}>
                  <div className="px-5 py-2.5 bg-surface-3 border-y border-border sticky top-0 z-20 font-bold text-[13px] text-text flex justify-between items-center">
                    <div className="flex items-center gap-2">
                      <span className="w-2 h-2 rounded-full" style={{ background: c.color || '#2AB182' }}></span>
                      {c.name}
                    </div>
                    <span className="text-[10px] bg-surface px-1.5 py-0.5 rounded text-text-2 border border-border">{ctasks.length}</span>
                  </div>
                  {ctasks.map(t => (
                    <div key={t.id} className="px-5 border-b border-border h-[58px] flex flex-col justify-center cursor-pointer hover:bg-hover transition-colors group" onClick={() => setSelectedTaskId(t.id)}>
                      <p className="text-[13px] font-semibold text-text truncate group-hover:text-primary">{t.title}</p>
                      <div className="flex items-center gap-1.5 mt-1">
                        <span className="text-[10px] font-bold px-1.5 rounded-sm" style={{ background: `${PRIORITY_CONFIG[t.priority].color}20`, color: PRIORITY_CONFIG[t.priority].color }}>{PRIORITY_CONFIG[t.priority].label.toUpperCase()}</span>
                      </div>
                    </div>
                  ))}
                </div>
              );
            })}
          </div>
        </div>

        {/* Right Panel (Timeline) */}
        <div 
          ref={timelineRef}
          onMouseDown={handleMouseDown}
          onWheel={(e) => {
            // Optional: if the user scrolls vertically with mouse wheel, pan horizontally instead
            if (timelineRef.current && e.deltaY !== 0 && e.deltaX === 0 && !e.shiftKey) {
              timelineRef.current.scrollLeft += e.deltaY;
            }
          }}
          className={`flex-1 overflow-x-auto overflow-y-auto relative bg-surface gantt-scrollbar ${isPanning ? 'cursor-grabbing' : 'cursor-grab'}`}
          style={{ scrollbarWidth: 'auto' }} // Ensure native visible scrollbars
        >
          <div className="flex sticky top-0 z-10 bg-surface border-b border-border" style={{ width: units.length * UNIT_WIDTH }}>
            {units.map((d, i) => {
              const isToday = zoomLevel !== 'day' && d.getDate() === today.getDate() && d.getMonth() === today.getMonth() && d.getFullYear() === today.getFullYear();
              const isCurrentHour = zoomLevel === 'day' && d.getHours() === getISTDate().getHours() && d.getDate() === today.getDate() && d.getMonth() === today.getMonth() && d.getFullYear() === today.getFullYear();
              const isFirstOfMonth = d.getDate() === 1;
              const isFirstOfWeek = d.getDay() === 1;

              return (
                <div key={d.toISOString()} className="flex-shrink-0 border-r border-border flex items-center justify-center flex-col h-[53px] relative" style={{ width: UNIT_WIDTH, background: (isToday || isCurrentHour) ? 'rgba(42,177,130,0.08)' : 'var(--c-surface)' }}>
                  {zoomLevel === 'day' && UNIT_WIDTH >= 25 && (
                    <span className={`text-[12px] font-bold ${isCurrentHour ? 'text-[#2AB182]' : 'text-text-2'}`}>
                      {d.toLocaleTimeString('en-US', { hour: 'numeric', hour12: true })}
                    </span>
                  )}
                  {zoomLevel === 'day' && UNIT_WIDTH < 25 && (
                    <span className={`text-[10px] font-bold ${isCurrentHour ? 'text-[#2AB182]' : 'text-text-2'}`}>
                      {d.getHours() % 3 === 0 ? d.getHours() + 'h' : ''}
                    </span>
                  )}
                  {zoomLevel === 'week' && (
                    <>
                      {UNIT_WIDTH >= 30 && <span className="text-[11px] font-bold uppercase tracking-wider mb-0.5" style={{ color: isToday ? '#2AB182' : 'var(--c-text-3)' }}>{d.toLocaleDateString('en-US', { weekday: 'short' })}</span>}
                      {UNIT_WIDTH >= 20 && (
                        <span className={`text-[14px] font-bold flex flex-col items-center gap-0 ${isToday ? 'text-[#2AB182]' : 'text-text'}`}>
                          <span>{d.getDate()}</span>
                          {(isFirstOfMonth || i === 0) && <span className="text-[9px] text-text-3 font-medium bg-surface-2 px-1 rounded">{d.toLocaleDateString('en-US', { month: 'short' })}</span>}
                        </span>
                      )}
                      {UNIT_WIDTH < 20 && <span className={`text-[10px] font-bold ${isToday ? 'text-[#2AB182]' : 'text-text-3'}`}>{d.getDate() % 2 === 0 ? d.getDate() : ''}</span>}
                    </>
                  )}
                  {zoomLevel === 'month' && (
                    <div className="flex flex-col items-center justify-center w-full h-full overflow-hidden">
                      {(isFirstOfMonth || i === 0) && (
                        <span className="text-[10px] font-bold text-text-2 whitespace-nowrap bg-surface-2 px-1 rounded border border-border/50 z-10 sticky left-0">
                          {d.toLocaleDateString('en-US', { month: 'short', year: 'numeric' })}
                        </span>
                      )}
                      {UNIT_WIDTH >= 15 && !(isFirstOfMonth || i === 0) && (
                        <span className="text-[10px] font-bold text-text-3 mt-1">
                          {d.getDate() % 2 === 0 ? d.getDate() : ''}
                        </span>
                      )}
                      {UNIT_WIDTH < 15 && UNIT_WIDTH >= 8 && !(isFirstOfMonth || i === 0) && (
                        <span className="text-[9px] font-bold text-text-3 mt-1">
                          {d.getDate() % 5 === 0 ? d.getDate() : ''}
                        </span>
                      )}
                    </div>
                  )}
                </div>
              );
            })}
          </div>

          <div className="relative" style={{ width: units.length * UNIT_WIDTH, minHeight: 'calc(100% - 54px)' }}>
            {/* Background grid */}
            <div className="absolute inset-0 flex pointer-events-none">
              {units.map(d => {
                const isToday = zoomLevel !== 'day' && d.getTime() === today.getTime();
                const isCurrentHour = zoomLevel === 'day' && d.getHours() === getISTDate().getHours() && startDate.getTime() === today.getTime();
                const isWorkingHour = zoomLevel === 'day' && d.getHours() >= 9 && d.getHours() < 18;
                const isFirstOfMonth = d.getDate() === 1;
                return (
                  <div key={d.toISOString()} className={`flex-shrink-0 h-full relative border-r border-border/40`} style={{ width: UNIT_WIDTH, background: (isToday || isCurrentHour) ? 'rgba(42,177,130,0.03)' : (zoomLevel === 'day' && isWorkingHour ? 'var(--c-surface-2)' : 'transparent') }}>
                    {(isToday || isCurrentHour) && <div className="absolute top-0 bottom-0 border-l-2 border-dashed border-[#EF4444]/60 z-0" style={{ left: '50%' }}></div>}
                  </div>
                );
              })}
            </div>

            <div className="pb-8 z-10 relative">
              {clients.map(c => {
                let ctasks = state.tasks.filter(t => t.clientId === c.id && t.status !== 'done');
                if (memberFilter) {
                  ctasks = ctasks.filter(t => t.assignedTo.includes(memberFilter));
                }
                if (ctasks.length === 0) return null;
                return (
                  <div key={c.id}>
                    <div className="h-[40px] pointer-events-none"></div> {/* Header spacer (bg-surface-3 matches left) */}
                    {ctasks.map(t => {
                      const dl = t.deadline ? new Date(t.deadline) : null;
                      const st = getISTDate();
                      if (dl) {
                        const daysToSubtract = Math.max(1, Math.ceil((t.estimatedHours || 8) / 8));
                        st.setTime(dl.getTime() - (daysToSubtract * 86400000));
                      } else {
                        st.setTime(new Date(t.startTime || t.createdAt).getTime());
                      }
                      if (dl && dl < st) st.setTime(dl.getTime() - 86400000); 

                      let left = getLeft(st);
                      let width = UNIT_WIDTH * 2;
                      if (dl) {
                        width = getLeft(dl) - left;
                        if (zoomLevel === 'day' && width < UNIT_WIDTH * 2) width = UNIT_WIDTH * Math.max(t.estimatedHours || 2, 2);
                      } else if (zoomLevel === 'day' && t.estimatedHours) {
                        width = t.estimatedHours * UNIT_WIDTH;
                      }
                      width = Math.max(width, UNIT_WIDTH);

                      // Apply drag offset
                      if (draggingTaskId === t.id) {
                        const dragPx = (dragOffsetDays * (zoomLevel === 'day' ? 24 : 1) * UNIT_WIDTH);
                        if (dragMode === 'move') {
                          left += dragPx;
                        } else if (dragMode === 'extend-right') {
                          width += dragPx;
                        } else if (dragMode === 'extend-left') {
                          left += dragPx;
                          width -= dragPx;
                        }
                      }

                      const pcolor = PRIORITY_CONFIG[t.priority].color;
                      const isDraggingThis = draggingTaskId === t.id;

                      return (
                        <div key={t.id} className="h-[58px] border-b border-transparent relative flex items-center group hover:bg-[var(--c-hover)] transition-colors">
                          <div 
                            onMouseDown={(e) => dl ? handleTaskDragStart(e, t.id, 'move') : null}
                            onClick={() => { if (dragOffsetDays === 0) setSelectedTaskId(t.id); }}
                            className={`absolute h-[32px] rounded transition-shadow shadow-sm flex items-center px-2 z-10 overflow-hidden text-[12px] font-bold text-white whitespace-nowrap hover:shadow-md ${dl ? 'cursor-move' : 'cursor-pointer'} ${isDraggingThis ? 'scale-[1.02] shadow-xl z-50 ring-2 ring-primary' : 'hover:scale-[1.01]'}`}
                            style={{ 
                              left: Math.max(0, left) + 2, 
                              width: dl ? Math.max(12, Math.min(width - 4, (units.length * UNIT_WIDTH) - left - 4)) : Math.max(12, width - 4), 
                              background: dl ? pcolor : 'transparent',
                              border: dl ? 'none' : `2px dashed ${pcolor}`,
                              color: dl ? '#fff' : pcolor,
                              opacity: (left + width < 0 || left > units.length * UNIT_WIDTH) ? 0 : 1
                            }}
                          >
                            {!dl && "No Deadline"}
                            {dl && (
                              <>
                                <div 
                                  className="absolute left-0 top-0 bottom-0 w-2 hover:bg-black/20 cursor-col-resize flex items-center justify-center pointer-events-auto"
                                  onMouseDown={(e) => handleTaskDragStart(e, t.id, 'extend-left')}
                                ></div>
                                {width > 40 && <span className="ml-2 font-medium text-[10px] truncate w-full pointer-events-none select-none overflow-hidden">{t.title}</span>}
                                <div 
                                  className="absolute right-0 top-0 bottom-0 w-4 bg-black/10 flex items-center justify-center hover:bg-black/20 cursor-col-resize pointer-events-auto"
                                  onMouseDown={(e) => handleTaskDragStart(e, t.id, 'extend-right')}
                                >
                                  <GripVertical className="w-3 h-3 text-white/50" />
                                </div>
                              </>
                            )}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useApp } from '@/contexts/AppContext';
import { Task, CLIENTS, TEAM_MEMBERS, CATEGORY_LABELS, TaskCategory, DEFAULT_BENCHMARKS } from '@/lib/data';

interface Props { isOpen: boolean; onClose: () => void; defaultClientId?: string; defaultTitle?: string; defaultType?: 'goal' | 'task' | 'subtask'; }

const PRIORITIES: Task['priority'][] = ['critical', 'high', 'medium', 'low'];
const CATEGORIES = Object.keys(CATEGORY_LABELS) as TaskCategory[];

const PRIORITY_COLORS = {
  critical: '#EF4444', high: '#F97316', medium: '#F59E0B', low: '#94A3B8'
};

export default function NewTaskModal({ isOpen, onClose, defaultClientId, defaultTitle, defaultType }: Props) {
  const { createTask, state } = useApp();

  const [form, setForm] = useState({
    title: '',
    type: 'task' as 'goal' | 'task' | 'subtask',
    parentId: '',
    clientId: defaultClientId ?? '',
    category: 'performance_marketing' as TaskCategory,
    priority: 'high' as Task['priority'],
    assignedTo: [] as string[],
    deadline: '',
    estimatedHours: '',
    description: '',
    tags: '',
    driveLink: '',
    requiresAsset: false,
    subtasksBatch: '',
    fileName: '',
    taskType: '',
    dependencies: [] as string[],
  });

  // Reset form when opened
  useEffect(() => {
    if (isOpen) {
      setForm({
        title: defaultTitle || '',
        type: defaultType || 'task',
        parentId: '',
        clientId: defaultClientId ?? '',
        category: 'performance_marketing',
        priority: 'high',
        assignedTo: [],
        deadline: '',
        estimatedHours: '',
        description: '',
        tags: '',
        driveLink: '',
        requiresAsset: false,
        subtasksBatch: '',
        fileName: '',
        taskType: '',
        dependencies: [],
      });
    }
  }, [isOpen, defaultTitle, defaultType, defaultClientId]);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [submitting, setSubmitting] = useState(false);

  if (!isOpen) return null;

  const set = (k: string, v: string | string[]) => {
    setForm(p => ({ ...p, [k]: v }));
    if (errors[k]) setErrors(p => { const n = { ...p }; delete n[k]; return n; });
  };

  const toggleAssignee = (id: string) => {
    set('assignedTo', form.assignedTo.includes(id)
      ? form.assignedTo.filter(x => x !== id)
      : [...form.assignedTo, id]);
  };

  const validate = () => {
    const e: Record<string, string> = {};
    if (!form.title.trim()) e.title = 'Title is required';
    if (!form.clientId) e.clientId = 'Client is required';
    if (!form.deadline) e.deadline = 'Deadline is required';
    if (form.type === 'subtask' && !form.parentId) e.parentId = 'Parent Task is required for subtasks';
    return e;
  };

  const handleSubmit = () => {
    const e = validate();
    if (Object.keys(e).length > 0) { setErrors(e); return; }
    setSubmitting(true);

    const assets = form.driveLink.trim() ? [{ name: 'Drive Link', url: form.driveLink.trim() }] : [];

    createTask({
      title: form.title.trim(),
      type: form.type,
      parentId: form.type === 'subtask' ? form.parentId : undefined,
      clientId: form.clientId,
      category: form.category,
      priority: form.priority,
      status: 'todo',
      assignedTo: form.assignedTo,
      createdBy: state.currentUserId,
      deadline: form.deadline ? new Date(form.deadline).toISOString() : null,
      estimatedHours: parseFloat(form.estimatedHours) || 0,
      description: form.description.trim(),
      tags: form.tags.split(',').map(t => t.trim()).filter(Boolean),
      assets: assets.length > 0 ? assets : undefined,
      requiresAsset: form.requiresAsset,
      taskType: form.taskType || undefined,
      dependencies: form.dependencies.length > 0 ? form.dependencies : undefined,
    });

    if (form.type === 'goal' && form.subtasksBatch.trim()) {
      const subtasks = form.subtasksBatch.split('\n').map(s => s.trim()).filter(Boolean);
      subtasks.forEach(title => {
        createTask({
          title: title,
          type: 'subtask',
          parentId: 'mock-goal-id', // Mock parent ID since the goal ID is not returned
          clientId: form.clientId,
          category: form.category,
          priority: form.priority,
          status: 'todo',
          assignedTo: form.assignedTo,
          createdBy: state.currentUserId,
          deadline: form.deadline ? new Date(form.deadline).toISOString() : null,
          estimatedHours: 0,
          description: '',
          tags: [],
          requiresAsset: false,
          taskType: form.taskType || undefined,
          dependencies: form.dependencies.length > 0 ? form.dependencies : undefined,
        });
      });
    }

    setSubmitting(false);
    setForm({ title: '', type: 'task', parentId: '', clientId: defaultClientId ?? '', category: 'performance_marketing', priority: 'high', assignedTo: [], deadline: '', estimatedHours: '', description: '', tags: '', driveLink: '', requiresAsset: false, subtasksBatch: '', fileName: '', taskType: '', dependencies: [] });
    setErrors({});
    onClose();
  };

  return (
    <>
      {/* Backdrop */}
      <div className="fixed inset-0 z-[120]" style={{ background: 'rgba(0,0,0,0.55)', backdropFilter: 'blur(4px)' }} onClick={onClose} />

      {/* Modal */}
      <div
        className="fixed z-[121] left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-full flex flex-col"
        style={{
          maxWidth: 580,
          maxHeight: '90vh',
          background: 'var(--c-surface)',
          border: '1px solid var(--c-border-strong)',
          borderRadius: 16,
          boxShadow: 'var(--shadow-modal)',
        }}
      >
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4" style={{ borderBottom: '1px solid var(--c-border)' }}>
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 rounded-lg flex items-center justify-center" style={{ background: 'rgba(37,99,235,0.15)' }}>
              <span className="material-symbols-outlined" style={{ fontSize: 18, color: '#2563EB', fontVariationSettings: "'FILL' 1" }}>add_task</span>
            </div>
            <h2 className="font-bold text-[16px]" style={{ color: 'var(--c-text)', fontFamily: 'var(--font-syne-var)' }}>New Task</h2>
          </div>
          <button onClick={onClose} className="rounded-lg p-1.5 transition-colors" style={{ color: 'var(--c-text-2)', background: 'var(--c-hover)' }}>
            <span className="material-symbols-outlined" style={{ fontSize: 20 }}>close</span>
          </button>
        </div>

        {/* Body */}
        <div className="overflow-y-auto flex-1 p-6 space-y-5">
          {/* Title */}
          <div>
            <label className="block text-[11px] font-semibold uppercase tracking-wider mb-1.5" style={{ color: 'var(--c-text-2)' }}>
              Task Title <span style={{ color: '#EF4444' }}>*</span>
            </label>
            <input
              className="input-base"
              placeholder="e.g. WhatsNexus Lead Tracking Setup"
              value={form.title}
              onChange={e => set('title', e.target.value)}
            />
            {errors.title && <p className="text-[11px] mt-1" style={{ color: '#EF4444' }}>{errors.title}</p>}
          </div>

          {/* Type + Client + Category */}
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-[11px] font-semibold uppercase tracking-wider mb-1.5" style={{ color: 'var(--c-text-2)' }}>Task Type</label>
              <select className="input-base" value={form.type} onChange={e => {
                set('type', e.target.value);
                if (e.target.value !== 'subtask') set('parentId', '');
              }}>
                <option value="goal">Goal (Project)</option>
                <option value="task">Standard Task</option>
                <option value="subtask">Subtask</option>
              </select>
            </div>
            {form.type === 'subtask' ? (
              <div>
                <label className="block text-[11px] font-semibold uppercase tracking-wider mb-1.5" style={{ color: 'var(--c-text-2)' }}>
                  Parent Task <span style={{ color: '#EF4444' }}>*</span>
                </label>
                <select className="input-base" value={form.parentId} onChange={e => set('parentId', e.target.value)}>
                  <option value="">Select Parent Task…</option>
                  {state.tasks.filter(t => t.type === 'goal' || t.type === 'task').map(t => (
                    <option key={t.id} value={t.id}>{t.title}</option>
                  ))}
                </select>
                {errors.parentId && <p className="text-[11px] mt-1" style={{ color: '#EF4444' }}>{errors.parentId}</p>}
              </div>
            ) : (
              <div>
                <label className="block text-[11px] font-semibold uppercase tracking-wider mb-1.5" style={{ color: 'var(--c-text-2)' }}>
                  Client <span style={{ color: '#EF4444' }}>*</span>
                </label>
                <select className="input-base" value={form.clientId} onChange={e => set('clientId', e.target.value)}>
                  <option value="">Select client…</option>
                  {CLIENTS.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
                {errors.clientId && <p className="text-[11px] mt-1" style={{ color: '#EF4444' }}>{errors.clientId}</p>}
              </div>
            )}
          </div>

          <div className="grid grid-cols-2 gap-4">
            {form.type === 'subtask' && (
              <div>
                <label className="block text-[11px] font-semibold uppercase tracking-wider mb-1.5" style={{ color: 'var(--c-text-2)' }}>
                  Client <span style={{ color: '#EF4444' }}>*</span>
                </label>
                <select className="input-base" value={form.clientId} onChange={e => set('clientId', e.target.value)}>
                  <option value="">Select client…</option>
                  {CLIENTS.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
                {errors.clientId && <p className="text-[11px] mt-1" style={{ color: '#EF4444' }}>{errors.clientId}</p>}
              </div>
            )}
            <div className={form.type !== 'subtask' ? "col-span-2" : ""}>
              <label className="block text-[11px] font-semibold uppercase tracking-wider mb-1.5" style={{ color: 'var(--c-text-2)' }}>Category</label>
              <select className="input-base" value={form.category} onChange={e => set('category', e.target.value)}>
                {CATEGORIES.map(c => <option key={c} value={c}>{CATEGORY_LABELS[c]}</option>)}
              </select>
            </div>
          </div>

          {/* Task Type and Dependencies */}
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-[11px] font-semibold uppercase tracking-wider mb-1.5" style={{ color: 'var(--c-text-2)' }}>Task Type (Optional)</label>
              <select className="input-base" value={form.taskType} onChange={e => set('taskType', e.target.value)}>
                <option value="">None</option>
                {Object.keys(DEFAULT_BENCHMARKS).map(t => (
                  <option key={t} value={t}>{t}</option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-[11px] font-semibold uppercase tracking-wider mb-1.5" style={{ color: 'var(--c-text-2)' }}>Dependencies (Hold Cmd/Ctrl)</label>
              <select 
                multiple 
                className="input-base text-[12px] h-[36px]" 
                style={{ padding: '4px' }}
                value={form.dependencies} 
                onChange={e => {
                  const opts = Array.from(e.target.selectedOptions, option => option.value);
                  set('dependencies', opts);
                }}
              >
                {state.tasks.filter(t => t.id !== form.parentId && t.status !== 'done').map(t => (
                  <option key={t.id} value={t.id}>{t.title}</option>
                ))}
              </select>
            </div>
          </div>

          {/* Priority */}
          <div>
            <label className="block text-[11px] font-semibold uppercase tracking-wider mb-1.5" style={{ color: 'var(--c-text-2)' }}>Priority</label>
            <div className="flex gap-2">
              {PRIORITIES.map(p => (
                <button
                  key={p}
                  type="button"
                  onClick={() => set('priority', p)}
                  className="flex-1 py-2 rounded-lg text-[11px] font-bold uppercase transition"
                  style={{
                    background: form.priority === p ? `${PRIORITY_COLORS[p]}20` : 'var(--c-surface-2)',
                    color: form.priority === p ? PRIORITY_COLORS[p] : 'var(--c-text-2)',
                    border: `1px solid ${form.priority === p ? PRIORITY_COLORS[p] + '40' : 'var(--c-border)'}`,
                  }}
                >
                  {p}
                </button>
              ))}
            </div>
          </div>

          {/* Deadline + Estimate */}
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-[11px] font-semibold uppercase tracking-wider mb-1.5" style={{ color: 'var(--c-text-2)' }}>
                Deadline <span style={{ color: '#EF4444' }}>*</span>
              </label>
              <input type="datetime-local" className="input-base" value={form.deadline} onChange={e => set('deadline', e.target.value)} />
              {errors.deadline && <p className="text-[11px] mt-1" style={{ color: '#EF4444' }}>{errors.deadline}</p>}
            </div>
            <div>
              <label className="block text-[11px] font-semibold uppercase tracking-wider mb-1.5" style={{ color: 'var(--c-text-2)' }}>Estimate (hours)</label>
              <input type="number" min="0.5" step="0.5" className="input-base" placeholder="e.g. 4" value={form.estimatedHours}
                onChange={e => set('estimatedHours', e.target.value)} />
            </div>
          </div>

          {/* Assignees */}
          <div>
            <label className="block text-[11px] font-semibold uppercase tracking-wider mb-2" style={{ color: 'var(--c-text-2)' }}>Assignees</label>
            <div className="flex flex-wrap gap-2">
              {TEAM_MEMBERS.map(m => {
                const selected = form.assignedTo.includes(m.id);
                return (
                  <button
                    key={m.id}
                    type="button"
                    onClick={() => toggleAssignee(m.id)}
                    className="flex items-center gap-1.5 px-2.5 py-1.5 rounded-full text-[11px] font-medium transition"
                    style={{
                      background: selected ? `${m.color}20` : 'var(--c-surface-2)',
                      border: `1px solid ${selected ? m.color + '60' : 'var(--c-border)'}`,
                      color: selected ? m.color : 'var(--c-text-2)',
                    }}
                  >
                    <div className="w-4 h-4 rounded-full flex items-center justify-center text-[8px] font-bold text-white flex-shrink-0"
                      style={{ background: m.color }}>
                      {m.initials}
                    </div>
                    {m.name.split(' ')[0]}
                  </button>
                );
              })}
            </div>
          </div>

          {/* Subtasks Batch for Goals */}
          {form.type === 'goal' && (
            <div>
              <label className="block text-[11px] font-semibold uppercase tracking-wider mb-1.5 flex items-center gap-1" style={{ color: 'var(--c-text-2)' }}>
                <span className="material-symbols-outlined text-[14px]">format_list_bulleted</span> Batch Create Subtasks
              </label>
              <textarea 
                className="input-base resize-y" 
                rows={3} 
                placeholder="Enter subtask titles, one per line..."
                value={form.subtasksBatch} 
                onChange={e => set('subtasksBatch', e.target.value)} 
              />
              <p className="text-[10px] text-text-3 mt-1">Each line will be created as a separate subtask under this goal, assigned to the same team.</p>
            </div>
          )}

          {/* Description */}
          <div>
            <label className="block text-[11px] font-semibold uppercase tracking-wider mb-1.5" style={{ color: 'var(--c-text-2)' }}>Description</label>
            <textarea className="input-base resize-none" rows={3} placeholder="What needs to be done?"
              value={form.description} onChange={e => set('description', e.target.value)} />
          </div>

          {/* Drive Link & Tags */}
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-[11px] font-semibold uppercase tracking-wider mb-1.5" style={{ color: 'var(--c-text-2)' }}>Drive / Asset Link</label>
              <div className="flex flex-col gap-2">
                <input className="input-base" placeholder="https://drive.google.com/..." value={form.driveLink}
                  onChange={e => set('driveLink', e.target.value)} />
                <div className="flex items-center gap-2">
                  <button type="button" className="btn-outline text-[11px] py-1 px-2 flex-1 border-dashed" onClick={() => setForm(p => ({...p, fileName: 'mock_asset_file.zip'}))}>
                    <span className="material-symbols-outlined text-[14px]">upload_file</span> {form.fileName || 'Attach File'}
                  </button>
                  {form.fileName && (
                    <button type="button" className="text-red-500 hover:bg-red-500/10 p-1 rounded" onClick={() => setForm(p => ({...p, fileName: ''}))}>
                      <span className="material-symbols-outlined text-[16px]">close</span>
                    </button>
                  )}
                </div>
              </div>
            </div>
            <div>
              <label className="block text-[11px] font-semibold uppercase tracking-wider mb-1.5" style={{ color: 'var(--c-text-2)' }}>Tags (comma-separated)</label>
              <input className="input-base" placeholder="meta, campaign, design" value={form.tags}
                onChange={e => set('tags', e.target.value)} />
            </div>
          </div>

          <div className="mt-2 flex items-center gap-2 bg-surface-2 p-3 rounded-lg border border-border">
            <input 
              type="checkbox" 
              id="requiresAsset" 
              checked={form.requiresAsset}
              onChange={e => setForm(p => ({ ...p, requiresAsset: e.target.checked }))}
              className="rounded border-border text-primary focus:ring-primary"
            />
            <label htmlFor="requiresAsset" className="text-[12px] font-medium text-text cursor-pointer">
              Require asset attachment on completion
            </label>
          </div>
        </div>

        {/* Footer */}
        <div className="flex justify-end gap-3 px-6 py-4" style={{ borderTop: '1px solid var(--c-border)' }}>
          <button onClick={onClose} className="btn-ghost">Cancel</button>
          <button
            onClick={handleSubmit}
            disabled={submitting}
            className="btn-primary"
            style={{ opacity: submitting ? 0.7 : 1 }}
          >
            <span className="material-symbols-outlined" style={{ fontSize: 16 }}>add_task</span>
            Create Task
          </button>
        </div>
      </div>
    </>
  );
}

'use client';

import { useState, useMemo } from 'react';
import { useApp } from '@/contexts/AppContext';
import { Task, PRIORITY_CONFIG, TeamMember, TaskCategory } from '@/lib/data';

interface SubtaskRow {
  title: string;
  assigneeId: string;
  deadline: string;
  priority: Task['priority'];
  estimatedHours: number;
  requiresAsset: boolean;
}

function emptyRow(): SubtaskRow {
  return { title: '', assigneeId: '', deadline: '', priority: 'medium', estimatedHours: 2, requiresAsset: false };
}

interface Props {
  parentTask: Task;
  onClose: () => void;
}

export default function SubtaskModal({ parentTask, onClose }: Props) {
  const { state, dispatch } = useApp();
  const [mode, setMode] = useState<'single' | 'batch'>('single');
  const [rows, setRows] = useState<SubtaskRow[]>([emptyRow()]);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Smart suggestions: members whose roleTag matches the parent task category
  const ROLE_TAG_MAP: Record<TaskCategory, string[]> = {
    video_editing: ['video_editor'],
    video_creative: ['video_editor', 'designer'],
    design_creative: ['designer'],
    performance_marketing: ['performance_marketer'],
    web_development: ['web_developer', 'developer'],
    whatsapp_automation: ['web_developer', 'ai_developer'],
    social_media: ['performance_marketer', 'ops'],
    strategy: ['leadership', 'ops'],
    operations: ['ops'],
    content_writing: ['ops'],
    seo: ['performance_marketer'],
  };

  const suggestedMembers = useMemo(() => {
    const tags = ROLE_TAG_MAP[parentTask.category] ?? [];
    const suggested = state.teamMembers.filter(m => tags.includes(m.roleTag));
    const others = state.teamMembers.filter(m => !tags.includes(m.roleTag));
    return { suggested, others };
  }, [state.teamMembers, parentTask.category]);

  const updateRow = (i: number, patch: Partial<SubtaskRow>) => {
    setRows(prev => prev.map((r, idx) => idx === i ? { ...r, ...patch } : r));
  };

  const addRow = () => setRows(prev => [...prev, emptyRow()]);
  const removeRow = (i: number) => setRows(prev => prev.filter((_, idx) => idx !== i));

  const handleSubmit = () => {
    const validRows = rows.filter(r => r.title.trim());
    if (!validRows.length) return;
    setIsSubmitting(true);

    const now = new Date().toISOString();
    for (const row of validRows) {
      dispatch({
        type: 'CREATE_TASK',
        payload: {
          title: row.title.trim(),
          description: '',
          clientId: parentTask.clientId,
          category: parentTask.category,
          priority: row.priority,
          status: 'todo',
          assignedTo: row.assigneeId ? [row.assigneeId] : [],
          createdBy: state.currentUserId,
          deadline: row.deadline || null,
          estimatedHours: row.estimatedHours,
          loggedMinutes: 0,
          tags: [],
          type: 'subtask',
          parentId: parentTask.id,
          requiresAsset: row.requiresAsset,
          displayCode: '',
          updatedAt: now,
        } as any,
      });
    }

    setIsSubmitting(false);
    onClose();
  };

  const memberSelectEl = (rowIdx: number, value: string) => (
    <select
      value={value}
      onChange={e => updateRow(rowIdx, { assigneeId: e.target.value })}
      style={{
        background: 'var(--c-input)',
        border: '1px solid var(--c-border)',
        borderRadius: 8,
        color: 'var(--c-text)',
        fontSize: 13,
        padding: '7px 10px',
        width: '100%',
      }}
    >
      <option value="">— Unassigned —</option>
      {suggestedMembers.suggested.length > 0 && (
        <optgroup label="✨ Suggested">
          {suggestedMembers.suggested.map(m => (
            <option key={m.id} value={m.id}>{m.name}</option>
          ))}
        </optgroup>
      )}
      <optgroup label="All team">
        {suggestedMembers.others.map(m => (
          <option key={m.id} value={m.id}>{m.name}</option>
        ))}
      </optgroup>
    </select>
  );

  const prioritySelectEl = (rowIdx: number, value: Task['priority']) => (
    <select
      value={value}
      onChange={e => updateRow(rowIdx, { priority: e.target.value as Task['priority'] })}
      style={{
        background: 'var(--c-input)',
        border: '1px solid var(--c-border)',
        borderRadius: 8,
        color: PRIORITY_CONFIG[value].color,
        fontSize: 12,
        fontWeight: 700,
        padding: '7px 10px',
        width: '100%',
      }}
    >
      {(Object.keys(PRIORITY_CONFIG) as Task['priority'][]).map(p => (
        <option key={p} value={p}>{PRIORITY_CONFIG[p].label}</option>
      ))}
    </select>
  );

  return (
    <div
      style={{
        position: 'fixed', inset: 0, zIndex: 200,
        background: 'rgba(0,0,0,0.6)',
        backdropFilter: 'blur(6px)',
        display: 'flex', alignItems: 'center', justifyContent: 'center',
        padding: 16,
      }}
      onClick={e => { if (e.target === e.currentTarget) onClose(); }}
    >
      <div
        style={{
          background: 'var(--c-surface)',
          border: '1px solid var(--c-border)',
          borderRadius: 20,
          width: '100%',
          maxWidth: mode === 'batch' ? 860 : 520,
          maxHeight: '90vh',
          overflow: 'hidden',
          display: 'flex',
          flexDirection: 'column',
          boxShadow: '0 24px 80px rgba(0,0,0,0.5)',
        }}
      >
        {/* Header */}
        <div style={{ padding: '20px 24px 16px', borderBottom: '1px solid var(--c-border)', flexShrink: 0 }}>
          <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', marginBottom: 12 }}>
            <div>
              <p style={{ fontSize: 11, fontWeight: 700, color: '#2AB182', textTransform: 'uppercase', letterSpacing: 2, marginBottom: 4 }}>
                Add Subtasks
              </p>
              <h2 style={{ fontSize: 17, fontWeight: 800, color: 'var(--c-text)', lineHeight: 1.3, fontFamily: 'var(--font-syne-var)' }}>
                {parentTask.title}
              </h2>
            </div>
            <button
              onClick={onClose}
              style={{ background: 'var(--c-surface-2)', border: '1px solid var(--c-border)', borderRadius: 8, padding: '6px 8px', cursor: 'pointer', color: 'var(--c-text-3)' }}
            >
              <span className="material-symbols-outlined" style={{ fontSize: 18 }}>close</span>
            </button>
          </div>

          {/* Mode toggle */}
          <div style={{ display: 'flex', background: 'var(--c-surface-2)', borderRadius: 10, padding: 4, width: 'fit-content', border: '1px solid var(--c-border)' }}>
            {(['single', 'batch'] as const).map(m => (
              <button
                key={m}
                onClick={() => { setMode(m); setRows([emptyRow()]); }}
                style={{
                  padding: '6px 16px',
                  borderRadius: 7,
                  fontSize: 12,
                  fontWeight: 700,
                  border: 'none',
                  cursor: 'pointer',
                  background: mode === m ? 'var(--c-surface)' : 'transparent',
                  color: mode === m ? 'var(--c-text)' : 'var(--c-text-3)',
                  boxShadow: mode === m ? '0 1px 4px rgba(0,0,0,0.1)' : 'none',
                  transition: 'all 0.15s',
                }}
              >
                {m === 'single' ? '📌 Single Task' : '📋 Batch Create'}
              </button>
            ))}
          </div>
        </div>

        {/* Body */}
        <div style={{ flex: 1, overflowY: 'auto', padding: '20px 24px' }}>
          {mode === 'single' ? (
            /* ─── Single Mode ─── */
            <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
              <div>
                <label style={{ fontSize: 11, fontWeight: 700, color: 'var(--c-text-3)', textTransform: 'uppercase', letterSpacing: 1, display: 'block', marginBottom: 6 }}>
                  Subtask Title *
                </label>
                <input
                  autoFocus
                  placeholder="What needs to be done?"
                  value={rows[0].title}
                  onChange={e => updateRow(0, { title: e.target.value })}
                  style={{
                    width: '100%', padding: '10px 14px', fontSize: 14, fontWeight: 500,
                    background: 'var(--c-input)', border: '1px solid var(--c-border)',
                    borderRadius: 10, color: 'var(--c-text)', boxSizing: 'border-box',
                  }}
                />
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
                <div>
                  <label style={{ fontSize: 11, fontWeight: 700, color: 'var(--c-text-3)', textTransform: 'uppercase', letterSpacing: 1, display: 'block', marginBottom: 6 }}>
                    Assignee
                  </label>
                  {/* Assignee with avatar preview */}
                  <select
                    value={rows[0].assigneeId}
                    onChange={e => updateRow(0, { assigneeId: e.target.value })}
                    style={{
                      background: 'var(--c-input)', border: '1px solid var(--c-border)', borderRadius: 8,
                      color: 'var(--c-text)', fontSize: 13, padding: '9px 12px', width: '100%',
                    }}
                  >
                    <option value="">— Unassigned —</option>
                    {suggestedMembers.suggested.length > 0 && (
                      <optgroup label="✨ Suggested for this category">
                        {suggestedMembers.suggested.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}
                      </optgroup>
                    )}
                    <optgroup label="All team">
                      {suggestedMembers.others.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}
                    </optgroup>
                  </select>
                  {/* Color preview for selected member */}
                  {rows[0].assigneeId && (() => {
                    const m = state.teamMembers.find(x => x.id === rows[0].assigneeId);
                    if (!m) return null;
                    return (
                      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginTop: 8, padding: '6px 10px', background: m.color + '15', border: `1px solid ${m.color}33`, borderRadius: 8 }}>
                        <span style={{ width: 24, height: 24, borderRadius: '50%', background: m.color, display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#fff', fontSize: 10, fontWeight: 800 }}>
                          {m.initials}
                        </span>
                        <span style={{ fontSize: 12, fontWeight: 600, color: m.color }}>{m.name}</span>
                        <span style={{ fontSize: 11, color: 'var(--c-text-3)', marginLeft: 'auto' }}>{m.department}</span>
                      </div>
                    );
                  })()}
                </div>
                <div>
                  <label style={{ fontSize: 11, fontWeight: 700, color: 'var(--c-text-3)', textTransform: 'uppercase', letterSpacing: 1, display: 'block', marginBottom: 6 }}>
                    Deadline
                  </label>
                  <input
                    type="date"
                    value={rows[0].deadline}
                    onChange={e => updateRow(0, { deadline: e.target.value })}
                    style={{
                      background: 'var(--c-input)', border: '1px solid var(--c-border)', borderRadius: 8,
                      color: 'var(--c-text)', fontSize: 13, padding: '9px 12px', width: '100%', boxSizing: 'border-box',
                    }}
                  />
                </div>
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
                <div>
                  <label style={{ fontSize: 11, fontWeight: 700, color: 'var(--c-text-3)', textTransform: 'uppercase', letterSpacing: 1, display: 'block', marginBottom: 6 }}>
                    Priority
                  </label>
                  {prioritySelectEl(0, rows[0].priority)}
                </div>
                <div>
                  <label style={{ fontSize: 11, fontWeight: 700, color: 'var(--c-text-3)', textTransform: 'uppercase', letterSpacing: 1, display: 'block', marginBottom: 6 }}>
                    Est. Hours
                  </label>
                  <input
                    type="number"
                    min="0.5" step="0.5"
                    value={rows[0].estimatedHours}
                    onChange={e => updateRow(0, { estimatedHours: Number(e.target.value) })}
                    style={{
                      background: 'var(--c-input)', border: '1px solid var(--c-border)', borderRadius: 8,
                      color: 'var(--c-text)', fontSize: 13, padding: '9px 12px', width: '100%', boxSizing: 'border-box',
                    }}
                  />
                </div>
              </div>

              <label style={{ display: 'flex', alignItems: 'center', gap: 10, cursor: 'pointer', padding: '10px 14px', background: 'var(--c-surface-2)', borderRadius: 10, border: '1px solid var(--c-border)' }}>
                <input
                  type="checkbox"
                  checked={rows[0].requiresAsset}
                  onChange={e => updateRow(0, { requiresAsset: e.target.checked })}
                />
                <div>
                  <p style={{ fontSize: 13, fontWeight: 600, color: 'var(--c-text)' }}>Requires Asset Upload</p>
                  <p style={{ fontSize: 11, color: 'var(--c-text-3)' }}>Assignee must attach a file to submit this task</p>
                </div>
              </label>
            </div>
          ) : (
            /* ─── Batch Mode ─── */
            <div>
              <div style={{ display: 'grid', gridTemplateColumns: '2fr 1.5fr 130px 100px 80px 32px', gap: 8, padding: '0 0 8px', borderBottom: '1px solid var(--c-border)', marginBottom: 8 }}>
                {['Subtask Title', 'Assignee', 'Deadline', 'Priority', 'Est. h', ''].map(h => (
                  <p key={h} style={{ fontSize: 10, fontWeight: 800, color: 'var(--c-text-3)', textTransform: 'uppercase', letterSpacing: 1 }}>{h}</p>
                ))}
              </div>

              <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                {rows.map((row, i) => (
                  <div key={i} style={{ display: 'grid', gridTemplateColumns: '2fr 1.5fr 130px 100px 80px 32px', gap: 8, alignItems: 'center' }}>
                    <input
                      placeholder={`Subtask ${i + 1}…`}
                      value={row.title}
                      onChange={e => updateRow(i, { title: e.target.value })}
                      style={{
                        padding: '8px 10px', fontSize: 13, background: 'var(--c-input)',
                        border: '1px solid var(--c-border)', borderRadius: 8, color: 'var(--c-text)',
                      }}
                    />
                    <select
                      value={row.assigneeId}
                      onChange={e => updateRow(i, { assigneeId: e.target.value })}
                      style={{
                        padding: '8px 10px', fontSize: 12, background: 'var(--c-input)',
                        border: '1px solid var(--c-border)', borderRadius: 8, color: 'var(--c-text)',
                      }}
                    >
                      <option value="">Unassigned</option>
                      {suggestedMembers.suggested.length > 0 && (
                        <optgroup label="✨ Suggested">
                          {suggestedMembers.suggested.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}
                        </optgroup>
                      )}
                      <optgroup label="All">
                        {suggestedMembers.others.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}
                      </optgroup>
                    </select>
                    <input
                      type="date"
                      value={row.deadline}
                      onChange={e => updateRow(i, { deadline: e.target.value })}
                      style={{
                        padding: '8px 8px', fontSize: 12, background: 'var(--c-input)',
                        border: '1px solid var(--c-border)', borderRadius: 8, color: 'var(--c-text)',
                      }}
                    />
                    <select
                      value={row.priority}
                      onChange={e => updateRow(i, { priority: e.target.value as Task['priority'] })}
                      style={{
                        padding: '8px 8px', fontSize: 11, fontWeight: 700, background: 'var(--c-input)',
                        border: '1px solid var(--c-border)', borderRadius: 8,
                        color: PRIORITY_CONFIG[row.priority].color,
                      }}
                    >
                      {(Object.keys(PRIORITY_CONFIG) as Task['priority'][]).map(p => (
                        <option key={p} value={p}>{PRIORITY_CONFIG[p].label}</option>
                      ))}
                    </select>
                    <input
                      type="number" min="0.5" step="0.5"
                      value={row.estimatedHours}
                      onChange={e => updateRow(i, { estimatedHours: Number(e.target.value) })}
                      style={{
                        padding: '8px 8px', fontSize: 13, background: 'var(--c-input)',
                        border: '1px solid var(--c-border)', borderRadius: 8, color: 'var(--c-text)', textAlign: 'center',
                      }}
                    />
                    <button
                      onClick={() => rows.length > 1 && removeRow(i)}
                      style={{
                        width: 32, height: 32, borderRadius: 8, border: '1px solid var(--c-border)',
                        background: 'transparent', cursor: rows.length > 1 ? 'pointer' : 'not-allowed',
                        color: rows.length > 1 ? '#EF4444' : 'var(--c-text-3)',
                        display: 'flex', alignItems: 'center', justifyContent: 'center',
                      }}
                    >
                      <span className="material-symbols-outlined" style={{ fontSize: 16 }}>delete</span>
                    </button>
                  </div>
                ))}
              </div>

              <button
                onClick={addRow}
                style={{
                  marginTop: 12, display: 'flex', alignItems: 'center', gap: 6,
                  fontSize: 13, fontWeight: 700, color: '#2AB182',
                  background: 'rgba(42,177,130,0.08)', border: '1px dashed rgba(42,177,130,0.35)',
                  borderRadius: 10, padding: '9px 16px', cursor: 'pointer', width: '100%', justifyContent: 'center',
                  transition: 'all 0.15s',
                }}
                onMouseEnter={e => (e.currentTarget.style.background = 'rgba(42,177,130,0.15)')}
                onMouseLeave={e => (e.currentTarget.style.background = 'rgba(42,177,130,0.08)')}
              >
                <span className="material-symbols-outlined" style={{ fontSize: 18 }}>add</span>
                Add another subtask
              </button>

              {/* Summary */}
              <div style={{
                marginTop: 16, padding: '12px 16px', background: 'var(--c-surface-2)',
                border: '1px solid var(--c-border)', borderRadius: 10,
                display: 'flex', gap: 24,
              }}>
                <div>
                  <p style={{ fontSize: 10, color: 'var(--c-text-3)', fontWeight: 700, textTransform: 'uppercase', letterSpacing: 1 }}>Subtasks</p>
                  <p style={{ fontSize: 20, fontWeight: 800, color: 'var(--c-text)' }}>{rows.filter(r => r.title.trim()).length}</p>
                </div>
                <div>
                  <p style={{ fontSize: 10, color: 'var(--c-text-3)', fontWeight: 700, textTransform: 'uppercase', letterSpacing: 1 }}>Total Est.</p>
                  <p style={{ fontSize: 20, fontWeight: 800, color: 'var(--c-text)' }}>
                    {rows.reduce((s, r) => s + r.estimatedHours, 0)}h
                  </p>
                </div>
                <div>
                  <p style={{ fontSize: 10, color: 'var(--c-text-3)', fontWeight: 700, textTransform: 'uppercase', letterSpacing: 1 }}>Assigned</p>
                  <div style={{ display: 'flex', marginTop: 2, gap: -6 }}>
                    {[...new Set(rows.filter(r => r.assigneeId).map(r => r.assigneeId))].map(id => {
                      const m = state.teamMembers.find(x => x.id === id);
                      if (!m) return null;
                      return (
                        <span key={id} title={m.name} style={{
                          width: 24, height: 24, borderRadius: '50%', background: m.color,
                          border: '2px solid var(--c-surface)', display: 'flex',
                          alignItems: 'center', justifyContent: 'center', fontSize: 9, fontWeight: 800, color: '#fff',
                          marginRight: -8,
                        }}>
                          {m.initials}
                        </span>
                      );
                    })}
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Footer */}
        <div style={{ padding: '16px 24px', borderTop: '1px solid var(--c-border)', display: 'flex', justifyContent: 'flex-end', gap: 10, flexShrink: 0 }}>
          <button
            onClick={onClose}
            style={{
              padding: '9px 20px', borderRadius: 10, fontSize: 13, fontWeight: 700,
              background: 'var(--c-surface-2)', border: '1px solid var(--c-border)', color: 'var(--c-text-2)', cursor: 'pointer',
            }}
          >
            Cancel
          </button>
          <button
            onClick={handleSubmit}
            disabled={isSubmitting || !rows.some(r => r.title.trim())}
            style={{
              padding: '9px 24px', borderRadius: 10, fontSize: 13, fontWeight: 800,
              background: '#2AB182', border: 'none', color: '#fff', cursor: 'pointer',
              opacity: !rows.some(r => r.title.trim()) ? 0.5 : 1,
              transition: 'all 0.15s',
            }}
          >
            {mode === 'batch'
              ? `Create ${rows.filter(r => r.title.trim()).length} Subtask${rows.filter(r => r.title.trim()).length !== 1 ? 's' : ''}`
              : 'Create Subtask'}
          </button>
        </div>
      </div>
    </div>
  );
}

'use client';

import { memo } from 'react';
import { Calendar, PlayCircle, StopCircle } from 'lucide-react';
import { Task, PRIORITY_CONFIG, STATUS_CONFIG, CATEGORY_LABELS, isOverdue, calculateTaskProgress } from '@/lib/data';
import { useApp } from '@/contexts/AppContext';
import LiveTimer from '@/components/ui/LiveTimer';

interface TaskCardProps {
  task: Task;
  onClick?: () => void;
  showClient?: boolean;
  compact?: boolean;
}

export default memo(function TaskCard({ task, onClick, showClient = true, compact = false }: TaskCardProps) {
  const { state, setTaskStatus, isTimerRunning, startTimer, requestStopTimer } = useApp();
  const client = state.clients.find(c => c.id === task.clientId);
  const assignees = task.assignedTo.map(id => state.teamMembers.find(m => m.id === id)).filter(Boolean);
  const overdue = isOverdue(task);
  const timer = state.activeTimers.find(t => t.taskId === task.id);
  const timerRunning = !!timer;

  const pc = PRIORITY_CONFIG[task.priority];
  const sc = STATUS_CONFIG[task.status];

  const pct = calculateTaskProgress(task, state.tasks);

  const handleTimer = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (timerRunning) requestStopTimer(task.id);
    else startTimer(task.id);
  };

  const handleStatus = (e: React.MouseEvent) => {
    e.stopPropagation();
    const order: Task['status'][] = ['todo', 'in_progress', 'in_review', 'done'];
    const idx = order.indexOf(task.status);
    const nextStatus = order[(idx + 1) % order.length];

    if (nextStatus === 'todo' && task.status !== 'todo') {
      const currentUser = state.teamMembers.find(m => m.id === state.currentUserId);
      const isAdmin = currentUser?.role === 'admin';
      if (task.createdBy !== state.currentUserId && !isAdmin) {
        alert("Only the task assigner or admin can move a task back to Todo.");
        return;
      }
    }

    setTaskStatus(task.id, nextStatus);
  };

  if (compact) {
    return (
      <div
        onClick={onClick}
        className="flex items-center gap-3 p-3 rounded-lg cursor-pointer transition duration-150 group bg-app-surface2 border border-app-border"
      >
        {/* Status dot button */}
        <button
          onClick={handleStatus}
          className="w-4 h-4 rounded-full border-2 flex-shrink-0 transition"
          title={`${sc.label} → click to advance`}
          style={{ borderColor: sc.color, background: task.status === 'done' ? sc.color : 'transparent' }}
        />

        <div className="flex-1 min-w-0">
          <p className={`text-[13px] font-medium truncate text-app-text ${task.status === 'done' ? 'line-through opacity-50' : ''}`}>
            {task.title}
          </p>
        </div>

        <span className="text-[10px] font-bold px-1.5 py-0.5 rounded" style={{ background: pc.bg, color: pc.color }}>
          {pc.label}
        </span>
      </div>
    );
  }

  return (
    <div
      onClick={onClick}
      className="card p-3.5 cursor-pointer group transition duration-150 hover:translate-y-[-1px]"
      style={{ borderLeft: `3px solid ${pc.color}` }}
    >
      {/* Header row */}
      <div className="flex items-start justify-between gap-2 mb-2">
        <div className="flex-1 min-w-0">
          {showClient && client && (
            <p className="text-[10px] font-semibold uppercase tracking-wider mb-1 text-primary">
              {client.name}
            </p>
          )}
          <p className="text-[13px] font-semibold leading-snug text-app-text font-grotesk">
            {task.title}
          </p>
        </div>
        <div className="flex flex-col items-end gap-1 flex-shrink-0">
          <span className="text-[10px] font-bold px-1.5 py-0.5 rounded" style={{ background: pc.bg, color: pc.color }}>
            {pc.label.toUpperCase()}
          </span>
        </div>
      </div>

      {/* Category */}
      <p className="text-[11px] mb-2.5 truncate text-app-text2">
        {CATEGORY_LABELS[task.category]}
      </p>

      {/* Status + deadline row */}
      <div className="flex items-center gap-2 mb-3 flex-wrap">
        <button
          onClick={handleStatus}
          className="inline-flex items-center gap-1.5 text-[11px] font-semibold px-2 py-1 rounded-full transition hover:opacity-80"
          style={{ background: sc.bg, color: sc.color }}
        >
          <span className="w-1.5 h-1.5 rounded-full" style={{ background: sc.color }} />
          {sc.label}
        </button>

        {task.deadline && (
          <span className={`inline-flex items-center gap-1 text-[11px] px-2 py-1 rounded-full ${overdue ? 'bg-red-500/10 text-red-500' : 'bg-app-surface3 text-app-text2'}`}>
            <Calendar className="w-3 h-3" />
            {overdue ? 'Overdue · ' : ''}{new Date(task.deadline).toLocaleString('en-IN', { day: 'numeric', month: 'short', hour: 'numeric', minute: '2-digit' })}
          </span>
        )}
      </div>

      {/* Progress bar */}
      {task.estimatedHours > 0 && (
        <div className="mb-3">
          <div className="flex justify-between items-center mb-1">
            <span className="text-[10px] text-app-text3">
              {timer ? (
                <LiveTimer startedAt={timer.startedAt} accumulatedMinutes={task.loggedMinutes} format="hm" />
              ) : (
                <>{Math.floor(task.loggedMinutes / 60)}h {task.loggedMinutes % 60}m</>
              )} / {task.estimatedHours}h
            </span>
            <span className={`text-[10px] font-semibold ${pct >= 100 ? 'text-red-500' : 'text-primary'}`}>{pct}%</span>
          </div>
          <div className="h-1 rounded-full overflow-hidden bg-app-surface3">
            <div className="h-full rounded-full transition" style={{ width: `${Math.min(pct, 100)}%`, background: pct >= 100 ? '#EF4444' : '#2AB182' }} />
          </div>
        </div>
      )}

      {/* Footer: assignees + timer */}
      <div className="flex items-center justify-between">
        {/* Assignees */}
        <div className="flex -space-x-1.5">
          {assignees.slice(0, 3).map(m => m && (
            <div
              key={m.id}
              className="w-6 h-6 rounded-full border border-app-surface flex items-center justify-center text-[9px] font-bold text-white font-grotesk"
              style={{ background: m.color }}
              title={m.name}
            >
              {m.initials}
            </div>
          ))}
          {assignees.length > 3 && (
            <div className="w-6 h-6 rounded-full border border-app-surface flex items-center justify-center text-[9px] font-bold bg-app-surface3 text-app-text2">
              +{assignees.length - 3}
            </div>
          )}
        </div>

        {/* Timer */}
        {task.status !== 'done' && (
          <div className="flex items-center gap-2">
            {timerRunning && timer && (
              <div className="flex items-center gap-2 bg-red-50 text-red-600 px-2 py-1 rounded-lg border border-red-200 dark:bg-red-500/10 dark:border-red-500/20">
                <span className="w-1.5 h-1.5 rounded-full bg-red-500 animate-pulse" />
                <LiveTimer 
                  startedAt={timer.startedAt} 
                  accumulatedMinutes={task.loggedMinutes} 
                  format="hhmmss"
                  className="font-mono font-bold text-[12px] tracking-wider"
                />
              </div>
            )}
            <button
              onClick={handleTimer}
              className={`flex items-center gap-1.5 rounded-lg px-2 py-1 text-[11px] font-semibold transition border ${
                timerRunning 
                  ? 'bg-red-500/10 text-red-600 border-red-500/30 hover:bg-red-500/20' 
                  : 'bg-green-500/10 text-green-600 border-green-500/30 hover:bg-green-500/20'
              }`}
            >
              {timerRunning ? <StopCircle className="w-3.5 h-3.5" /> : <PlayCircle className="w-3.5 h-3.5" />}
              {timerRunning ? 'Stop' : 'Start'}
            </button>
          </div>
        )}
      </div>
    </div>
  );
});

'use client';

import { useState, useEffect } from 'react';
import { X, PlayCircle, StopCircle, PlusCircle } from 'lucide-react';
import { useApp } from '@/contexts/AppContext';
import { Task, PRIORITY_CONFIG, STATUS_CONFIG, CATEGORY_LABELS, isOverdue, calculateTaskProgress } from '@/lib/data';
import LiveTimer from '@/components/ui/LiveTimer';

interface Props {
  taskId: string | null;
  onClose: () => void;
  onTaskSelect?: (id: string) => void;
}

const STATUSES: Task['status'][] = ['todo', 'in_progress', 'rework', 'in_review', 'blocked', 'done'];


export default function TaskDrawer({ taskId, onClose, onTaskSelect }: Props) {
  const { state, setTaskStatus, updateTask, startTimer, requestStopTimer, isTimerRunning, dispatch, addReviewComment } = useApp();
  const [tab, setTab] = useState<'details' | 'timelog' | 'audit'>('details');
  const [manualHours, setManualHours] = useState('');
  const [manualMins, setManualMins] = useState('');
  const [logNote, setLogNote] = useState('');
  const [comment, setComment] = useState('');
  const [newAssetUrl, setNewAssetUrl] = useState('');
  const [newAssetName, setNewAssetName] = useState('');

  const task = taskId ? state.tasks.find(t => t.id === taskId) : null;
  const client = task ? state.clients.find(c => c.id === task.clientId) : null;
  const assignees = task ? task.assignedTo.map(id => state.teamMembers.find(m => m.id === id)).filter(Boolean) : [];
  const overdue = task ? isOverdue(task) : false;
  const timer = task ? state.activeTimers.find(t => t.taskId === task.id) : null;
  const timerRunning = !!timer;
  const taskAudit = task
    ? state.auditLog.filter(a => a.entityRef.toLowerCase().includes(task.title.slice(0, 15).toLowerCase()))
    : [];

  // Close on Escape
  useEffect(() => {
    const handler = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [onClose]);

  if (!task) return null;

  const pc = PRIORITY_CONFIG[task.priority];
  const pct = task ? calculateTaskProgress(task, state.tasks) : 0;

  const handleManualLog = () => {
    const mins = (parseInt(manualHours || '0') * 60) + parseInt(manualMins || '0');
    if (mins <= 0) return;
    dispatch({ type: 'LOG_TIME_MANUAL', payload: { taskId: task.id, minutes: mins, note: logNote, actorId: state.currentUserId } });
    setManualHours(''); setManualMins(''); setLogNote('');
  };

  return (
    <>
      {/* Backdrop */}
      <div
        className="fixed inset-0 z-[100] bg-black/50 backdrop-blur-[2px]"
        onClick={onClose}
      />

      {/* Drawer */}
      <div
        className="fixed top-0 right-0 h-full z-[101] flex flex-col overflow-hidden bg-app-surface border-l border-app-border shadow-[var(--shadow-drawer)]"
        style={{ width: 'min(520px, 100vw)' }}
      >
        {/* Header */}
        <div className="flex items-start gap-3 p-5 border-b border-app-border">
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2 mb-2">
              <span className="text-[10px] font-bold px-2 py-0.5 rounded bg-primary/10 text-primary">
                {task.id}
              </span>
              {task.type === 'goal' && (
                <span className="text-[10px] font-bold px-2 py-0.5 rounded bg-primary/20 text-primary">
                  GOAL
                </span>
              )}
              {task.type === 'subtask' && (
                <span className="text-[10px] font-bold px-2 py-0.5 rounded bg-secondary/20 text-secondary">
                  SUBTASK
                </span>
              )}
              {overdue && (
                <span className="text-[10px] font-bold px-2 py-0.5 rounded bg-red-500/10 text-red-500">
                  OVERDUE
                </span>
              )}
              {timerRunning && timer && (
                <span className="flex items-center gap-1 text-[10px] font-bold px-2 py-0.5 rounded bg-primary/10 text-primary">
                  <span className="w-1.5 h-1.5 rounded-full animate-pulse bg-primary" />
                  <LiveTimer startedAt={timer.startedAt} />
                </span>
              )}
            </div>
            <h2 className="font-bold text-[16px] leading-snug text-app-text font-grotesk">
              {task.title}
            </h2>
            {client && (
              <p className="text-[12px] mt-1 font-semibold text-primary">{client.name}</p>
            )}
          </div>
          <button onClick={onClose} className="rounded-lg p-1.5 transition-colors flex-shrink-0 text-app-text2 bg-app-hover hover:opacity-80">
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-app-border">
          {(['details', 'timelog', 'audit'] as const).map(t => (
            <button
              key={t}
              onClick={() => setTab(t)}
              className={`flex-1 py-3 text-[12px] font-semibold uppercase tracking-wide transition-all font-grotesk border-b-2 bg-transparent ${tab === t ? 'text-primary border-primary' : 'text-app-text2 border-transparent hover:text-app-text'}`}
            >
              {t === 'timelog' ? 'Time Log' : t.charAt(0).toUpperCase() + t.slice(1)}
            </button>
          ))}
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto">
          {/* ── DETAILS TAB ── */}
          {tab === 'details' && (
            <div className="p-5 space-y-5">
              {/* Status */}
              <div>
                <label className="block text-[11px] font-semibold uppercase tracking-wider mb-2 text-app-text3">Status</label>
                <div className="flex flex-wrap gap-2">
                  {STATUSES.map(s => {
                    const sc = STATUS_CONFIG[s];
                    return (
                      <button
                        key={s}
                        onClick={() => {
                          if (s === 'todo' && task.status !== 'todo') {
                            const currentUser = state.teamMembers.find(m => m.id === state.currentUserId);
                            const isAdmin = currentUser?.role === 'admin' || currentUser?.role === 'super_admin';
                            if (task.createdBy !== state.currentUserId && !isAdmin) {
                              alert("Only the task assigner or admin can move a task back to Todo.");
                              return;
                            }
                          }

                          if (['paused', 'blocked', 'in_review'].includes(s) && task.status !== s) {
                            requestStopTimer(task.id, s as 'paused' | 'blocked' | 'in_review');
                          } else {
                            setTaskStatus(task.id, s);
                          }
                        }}
                        className="flex items-center gap-1.5 text-[12px] font-semibold px-3 py-1.5 rounded-full transition-all"
                        style={{
                          background: task.status === s ? sc.bg : 'var(--c-surface-2)',
                          color: task.status === s ? sc.color : 'var(--c-text-2)',
                          border: `1px solid ${task.status === s ? sc.color + '40' : 'var(--c-border)'}`,
                        }}
                      >
                        <span className="w-2 h-2 rounded-full" style={{ background: sc.color }} />
                        {sc.label}
                      </button>
                    );
                  })}
                </div>
              </div>

              {/* Priority */}
              <div>
                <label className="block text-[11px] font-semibold uppercase tracking-wider mb-2 text-app-text3">Priority</label>
                <div className="flex gap-2">
                  {(['critical','high','medium','low'] as const).map(p => {
                    const pc2 = PRIORITY_CONFIG[p];
                    return (
                      <button
                        key={p}
                        onClick={() => updateTask(task.id, { priority: p })}
                        className="text-[11px] font-bold px-2.5 py-1 rounded transition-all"
                        style={{
                          background: task.priority === p ? pc2.bg : 'var(--c-surface-2)',
                          color: task.priority === p ? pc2.color : 'var(--c-text-2)',
                          border: `1px solid ${task.priority === p ? pc2.color + '40' : 'var(--c-border)'}`,
                        }}
                      >
                        {pc2.label}
                      </button>
                    );
                  })}
                </div>
              </div>

              {/* Details grid */}
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-[11px] font-semibold uppercase tracking-wider mb-1 text-app-text3">Category</label>
                  <p className="text-[13px] text-app-text2">{CATEGORY_LABELS[task.category]}</p>
                </div>
                <div>
                  <label className="block text-[11px] font-semibold uppercase tracking-wider mb-1 text-app-text3">Deadline</label>
                  <input
                    type="datetime-local"
                    value={task.deadline ? new Date(new Date(task.deadline).getTime() - new Date(task.deadline).getTimezoneOffset() * 60000).toISOString().slice(0, 16) : ''}
                    onChange={e => updateTask(task.id, { deadline: e.target.value ? new Date(e.target.value).toISOString() : null })}
                    className={`input-base text-[13px] py-1 px-2 ${overdue ? 'text-red-500' : 'text-app-text2'}`}
                  />
                </div>
                <div>
                  <label className="block text-[11px] font-semibold uppercase tracking-wider mb-1 text-app-text3">Estimate</label>
                  <p className="text-[13px] text-app-text2">{task.estimatedHours}h</p>
                </div>
                <div>
                  <label className="block text-[11px] font-semibold uppercase tracking-wider mb-1 text-app-text3">Logged</label>
                  <div className={`text-[13px] font-semibold flex items-center gap-1 ${pct >= 100 ? 'text-red-500' : 'text-primary'}`}>
                    {timer ? <LiveTimer startedAt={timer.startedAt} accumulatedMinutes={task.loggedMinutes} /> : (
                      <span>{Math.floor(task.loggedMinutes/60)}:{String(task.loggedMinutes%60).padStart(2,'0')}</span>
                    )} ({pct}%)
                  </div>
                </div>
              </div>

              {/* Progress */}
              <div>
                <div className="h-2 rounded-full overflow-hidden bg-app-surface3">
                  <div className="h-full rounded-full transition-all" style={{ width: `${Math.min(pct, 100)}%`, background: pct >= 100 ? '#EF4444' : '#2AB182' }} />
                </div>
              </div>

              {/* Assignees */}
              <div>
                <label className="block text-[11px] font-semibold uppercase tracking-wider mb-2 text-app-text3">Assigned To</label>
                <div className="flex flex-wrap gap-2">
                  {assignees.map(m => m && (
                    <div key={m.id} className="flex items-center gap-2 rounded-full px-3 py-1 bg-app-surface2 border border-app-border">
                      <div className="w-5 h-5 rounded-full flex items-center justify-center text-[9px] font-bold text-white"
                        style={{ background: m.color }}>
                        {m.initials}
                      </div>
                      <span className="text-[12px] text-app-text">{m.name}</span>
                    </div>
                  ))}
                </div>
              </div>

              {/* Description */}
              {task.description && (
                <div>
                  <label className="block text-[11px] font-semibold uppercase tracking-wider mb-2 text-app-text3">Description</label>
                  <p className="text-[13px] leading-relaxed text-app-text2">{task.description}</p>
                </div>
              )}

              {/* Relative Assets (Drive Links) */}
              <div>
                <label className="block text-[11px] font-semibold uppercase tracking-wider mb-2 text-app-text3">Relative Assets / Drive Links</label>
                <div className="flex flex-col gap-2">
                  {(task.assets || []).map((asset, i) => (
                    <div key={i} className="flex items-center justify-between p-2.5 rounded-lg border border-border bg-surface-2 group">
                      <div className="flex items-center gap-2 overflow-hidden">
                        <div className="w-8 h-8 rounded bg-surface flex items-center justify-center flex-shrink-0 text-primary">
                          <span className="material-symbols-outlined text-[16px]">link</span>
                        </div>
                        <div className="min-w-0">
                          <p className="text-[12px] font-bold text-text truncate">{asset.name}</p>
                          <a href={asset.url} target="_blank" rel="noreferrer" className="text-[11px] text-text-3 hover:text-primary hover:underline truncate block">
                            {asset.url}
                          </a>
                        </div>
                      </div>
                    </div>
                  ))}

                  {(!task.assets || task.assets.length < 3) ? (
                    <div className="flex gap-2 mt-1">
                      <input 
                        type="text" 
                        placeholder="Name (e.g. Raw Footage)" 
                        className="input-base text-[12px] flex-1" 
                        value={newAssetName}
                        onChange={e => setNewAssetName(e.target.value)}
                      />
                      <input 
                        type="url" 
                        placeholder="Drive/Link URL" 
                        className="input-base text-[12px] flex-1" 
                        value={newAssetUrl}
                        onChange={e => setNewAssetUrl(e.target.value)}
                      />
                      <button 
                        className="btn-primary px-3 text-[12px]"
                        disabled={!newAssetName || !newAssetUrl}
                        onClick={() => {
                          const updatedAssets = [...(task.assets || []), { name: newAssetName, url: newAssetUrl }];
                          updateTask(task.id, { assets: updatedAssets });
                          setNewAssetName('');
                          setNewAssetUrl('');
                        }}
                      >
                        Add
                      </button>
                    </div>
                  ) : (
                    <p className="text-[11px] text-text-3 italic">Maximum 3 assets reached. Please use comments for more links.</p>
                  )}
                </div>
              </div>

              {/* Subtasks (if Goal) */}
              {task.type === 'goal' && (
                <div>
                  <label className="block text-[11px] font-semibold uppercase tracking-wider mb-2 text-app-text3">Subtasks</label>
                  <div className="flex flex-col gap-2">
                    {state.tasks.filter(t => t.parentId === task.id).length === 0 && (
                      <p className="text-[12px] text-text-3 italic">No subtasks found.</p>
                    )}
                    {state.tasks.filter(t => t.parentId === task.id).map(st => (
                      <div key={st.id} className="p-3 rounded-lg flex items-center justify-between bg-surface-2 border border-border group">
                        <div className="flex-1">
                           <div className="text-[13px] font-bold text-text group-hover:text-primary transition-colors cursor-pointer" onClick={() => onTaskSelect && onTaskSelect(st.id)}>{st.title}</div>
                           <div className="text-[11px] text-text-2 mt-0.5 flex items-center gap-2">
                             <span className="w-1.5 h-1.5 rounded-full" style={{ background: STATUS_CONFIG[st.status].color }}></span>
                             {STATUS_CONFIG[st.status].label}
                           </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Approvals */}
              {task.approvals && task.approvals.length > 0 && (
                <div>
                  <label className="block text-[11px] font-semibold uppercase tracking-wider mb-2 text-app-text3">Approvals</label>
                  <div className="flex flex-col gap-2">
                    {task.approvals.map(a => {
                      const approver = state.teamMembers.find(m => m.id === a.approver);
                      return (
                        <div key={a.id} className="p-3 rounded-lg bg-surface-2 border border-border">
                          <div className="flex justify-between items-start mb-2">
                            <div>
                              <div className="text-[12px] font-bold text-text capitalize">{a.type} Request</div>
                              <div className="text-[11px] text-text-2 mt-0.5">Approver: {approver?.name || a.approver}</div>
                            </div>
                            <span className={`text-[10px] font-bold px-2 py-0.5 rounded uppercase ${a.status === 'pending' ? 'bg-amber-500/20 text-amber-500' : a.status === 'approved' ? 'bg-emerald-500/20 text-emerald-500' : 'bg-red-500/20 text-red-500'}`}>
                              {a.status}
                            </span>
                          </div>
                          {a.requestMessage && <div className="text-[12px] text-text-2 italic bg-surface p-2 rounded">&quot;{a.requestMessage}&quot;</div>}
                        </div>
                      )
                    })}
                  </div>
                </div>
              )}

              {/* Review Comments */}
              {task.reviewComments && task.reviewComments.length > 0 && (
                <div>
                  <label className="block text-[11px] font-semibold uppercase tracking-wider mb-2 text-pink-500">Rework Feedback</label>
                  <div className="flex flex-col gap-2">
                    {task.reviewComments.map(rc => {
                      const author = state.teamMembers.find(m => m.id === rc.authorId);
                      return (
                        <div key={rc.id} className="p-3 rounded-lg bg-pink-500/5 border border-pink-500/20">
                          <div className="flex justify-between items-center mb-1">
                            <span className="text-[11px] font-bold text-pink-600">{author?.name || 'Admin'}</span>
                            <span className="text-[10px] text-pink-500/70">{new Date(rc.createdAt).toLocaleDateString()}</span>
                          </div>
                          <p className="text-[13px] text-text-2">{rc.text}</p>
                        </div>
                      )
                    })}
                  </div>
                </div>
              )}

              {/* Admin Review Flow */}
              {task.status === 'in_review' && (
                <div className="p-4 rounded-xl border border-amber-500/30 bg-amber-500/10">
                  <label className="block text-[11px] font-bold uppercase tracking-wider mb-2 text-amber-600">Admin Review</label>
                  {task.submissionNotes && (
                    <div className="mb-3 p-3 bg-surface rounded-lg border border-border">
                      <p className="text-[10px] font-bold text-text-3 uppercase mb-1">Submission Notes</p>
                      <p className="text-[12px] text-text-2">{task.submissionNotes}</p>
                    </div>
                  )}
                  <div className="flex gap-2">
                    <button 
                      onClick={() => setTaskStatus(task.id, 'done')}
                      className="flex-1 py-2 bg-emerald-500/20 text-emerald-600 border border-emerald-500/30 rounded-lg text-[12px] font-bold hover:bg-emerald-500/30 transition-colors"
                    >
                      Approve (Done)
                    </button>
                    <button 
                      onClick={() => {
                        const reason = window.prompt('Rework Reason:');
                        if (reason) {
                           addReviewComment(task.id, reason);
                           setTaskStatus(task.id, 'rework');
                        }
                      }}
                      className="flex-1 py-2 bg-pink-500/20 text-pink-600 border border-pink-500/30 rounded-lg text-[12px] font-bold hover:bg-pink-500/30 transition-colors"
                    >
                      Request Rework
                    </button>
                  </div>
                </div>
              )}

              {/* Timer control */}
              {task.status !== 'done' && (
                <button
                  onClick={() => timerRunning ? requestStopTimer(task.id) : startTimer(task.id)}
                  className={`w-full py-3 rounded-xl font-bold text-[13px] flex items-center justify-center gap-2 transition-all font-grotesk border ${timerRunning ? 'bg-red-500/10 text-red-500 border-red-500/30' : 'bg-primary/10 text-primary border-primary/30'}`}
                >
                  {timerRunning ? <StopCircle className="w-5 h-5" /> : <PlayCircle className="w-5 h-5" />}
                  {timerRunning ? 'Complete Task' : 'Start Task'}
                </button>
              )}

              {/* Comment box */}
              <div>
                <label className="block text-[11px] font-semibold uppercase tracking-wider mb-2 text-app-text3">Add Comment</label>
                <textarea
                  className="input-base resize-none"
                  rows={3}
                  placeholder="Add a note or update..."
                  value={comment}
                  onChange={e => setComment(e.target.value)}
                />
                <button
                  onClick={() => {
                    addReviewComment(task.id, comment);
                    setComment('');
                  }}
                  disabled={!comment.trim()}
                  className="btn-primary mt-2 text-[11px] py-1.5"
                  style={{ opacity: comment.trim() ? 1 : 0.4 }}
                >
                  Post
                </button>
              </div>
            </div>
          )}

          {/* ── TIME LOG TAB ── */}
          {tab === 'timelog' && (
            <div className="p-5 space-y-5">
              {/* Summary */}
              <div className="rounded-xl p-4 flex items-center justify-between bg-app-surface2 border border-app-border">
                <div>
                  <p className="text-[12px] mb-1 text-app-text2">Total Logged</p>
                  <div className="font-bold text-[18px] font-grotesk">
                    {timer ? <LiveTimer startedAt={timer.startedAt} accumulatedMinutes={task.loggedMinutes} /> : (
                      <span className="font-mono">{Math.floor(task.loggedMinutes/60)}:{String(task.loggedMinutes%60).padStart(2,'0')}</span>
                    )}
                  </div>
                </div>
                <div style={{ textAlign: 'right' }}>
                  <p className="text-[12px] mb-1 text-app-text2">Estimate</p>
                  <p className="font-bold text-[22px] num text-app-text">{task.estimatedHours}h</p>
                </div>
              </div>

              {/* Circular progress */}
              <div className="flex justify-center">
                <div className="relative w-28 h-28">
                  <svg className="w-full h-full -rotate-90" viewBox="0 0 36 36">
                    <circle cx="18" cy="18" r="15.9" fill="none" stroke="var(--c-surface-3)" strokeWidth="3" />
                    <circle cx="18" cy="18" r="15.9" fill="none"
                      stroke={pct >= 100 ? '#EF4444' : '#2AB182'}
                      strokeWidth="3"
                      strokeDasharray={`${Math.min(pct, 100)} 100`}
                      strokeLinecap="round" />
                  </svg>
                  <div className="absolute inset-0 flex items-center justify-center flex-col">
                    <span className={`font-bold text-[22px] num ${pct >= 100 ? 'text-red-500' : 'text-app-text'}`}>{pct}%</span>
                  </div>
                </div>
              </div>

              {/* Manual log entry */}
              <div className="rounded-xl p-4 bg-app-surface2 border border-app-border">
                <p className="text-[12px] font-semibold mb-3 uppercase tracking-wide text-app-text2">Log Time Manually</p>
                <div className="flex gap-2 mb-3">
                  <div className="flex-1">
                    <input type="number" min="0" max="23" className="input-base" placeholder="0" value={manualHours}
                      onChange={e => setManualHours(e.target.value)} />
                    <p className="text-[10px] mt-1 text-center text-app-text3">Hours</p>
                  </div>
                  <div className="flex-1">
                    <input type="number" min="0" max="59" className="input-base" placeholder="0" value={manualMins}
                      onChange={e => setManualMins(e.target.value)} />
                    <p className="text-[10px] mt-1 text-center text-app-text3">Minutes</p>
                  </div>
                </div>
                <input className="input-base mb-3" placeholder="Note (optional)" value={logNote}
                  onChange={e => setLogNote(e.target.value)} />
                <button onClick={handleManualLog} className="btn-primary w-full justify-center">
                  <PlusCircle className="w-4 h-4" />
                  Add Time Entry
                </button>
              </div>
            </div>
          )}

          {/* ── AUDIT TAB ── */}
          {tab === 'audit' && (
            <div className="p-5">
              {taskAudit.length === 0 ? (
                <p className="text-center py-12 text-[13px] text-app-text3">No audit entries for this task.</p>
              ) : (
                <div className="space-y-2">
                  {taskAudit.map(entry => (
                    <div key={entry.id} className="flex gap-3 p-3 rounded-lg bg-app-surface2 border border-app-border">
                      <div className="w-7 h-7 rounded-full flex items-center justify-center flex-shrink-0 text-[9px] font-bold text-white"
                        style={{ background: '#7C3AED' }}>
                        {entry.actor.split(' ').map(w => w[0]).join('').slice(0, 2)}
                      </div>
                      <div className="flex-1 min-w-0">
                        <p className="text-[12px] font-semibold text-app-text">
                          {entry.actor} <span className="font-normal text-app-text2">— {entry.action.replace(/_/g, ' ')}</span>
                        </p>
                        <p className="text-[11px] text-app-text3">
                          {entry.meta} · {new Date(entry.timestamp).toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' })}
                        </p>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </>
  );
}

