'use client';

import React, { createContext, useContext, useState, useEffect } from 'react';
import { useRouter, usePathname } from 'next/navigation';

export interface User {
  id: string;
  role: string;
  email: string;
  department: string;
  mustChangePassword?: boolean;
}

interface AuthContextType {
  user: User | null;
  token: string | null;
  loading: boolean;
  login: (token: string, user: User) => void;
  logout: () => void;
}

const AuthContext = createContext<AuthContextType>({
  user: null,
  token: null,
  loading: true,
  login: () => {},
  logout: () => {},
});

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [token, setToken] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const router = useRouter();
  const pathname = usePathname();

  useEffect(() => {
    // Check local storage for token on mount
    const savedToken = localStorage.getItem('invictus_jwt');
    const savedUser = localStorage.getItem('invictus_user');

    if (savedToken && savedUser) {
      // eslint-disable-next-line
      setToken(savedToken);
      try {
        const parsedUser = JSON.parse(savedUser);
        // Clear legacy non-UUID users
        if (parsedUser && parsedUser.id && parsedUser.id.length < 10) {
          localStorage.removeItem('invictus_jwt');
          localStorage.removeItem('invictus_user');
          setToken(null);
          setUser(null);
        } else {
          setUser(parsedUser);
        }
      } catch(e) {}
    }
    setLoading(false);
  }, []);

  const getDashboardRoute = (user: User | null) => {
    if (!user) return '/login';
    const { role, department } = user;
    if (role === 'admin' || role === 'super_admin' || role === 'ops') return '/dashboard';
    if (department === 'design') return '/designer-dashboard';
    if (department === 'video' || department === 'video_editor') return '/editor-dashboard';
    if (department === 'development' || department === 'web_developer' || department === 'ai_developer') return '/developer-dashboard';
    if (department === 'performance_marketing' || department === 'sales') return '/sales-dashboard';
    return '/team-dashboard';
  };

  useEffect(() => {
    if (!loading) {
      if (!token && !pathname.startsWith('/login')) {
        router.push('/login');
      } else if (token && pathname === '/login') {
        router.push(getDashboardRoute(user));
      }
    }
  }, [token, loading, pathname, router, user]);

  const login = (newToken: string, newUser: User) => {
    localStorage.setItem('invictus_jwt', newToken);
    localStorage.setItem('invictus_user', JSON.stringify(newUser));
    setToken(newToken);
    setUser(newUser);
    router.push(getDashboardRoute(newUser));
  };

  const logout = () => {
    localStorage.removeItem('invictus_jwt');
    localStorage.removeItem('invictus_user');
    localStorage.removeItem('invictus_app_state');
    setToken(null);
    setUser(null);
    router.push('/login');
  };

  return (
    <AuthContext.Provider value={{ user, token, loading, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
}

export const useAuth = () => useContext(AuthContext);

