import { AppState } from '@/contexts/AppContext';
import { Notification } from '@/lib/data';

export interface SystemAlert {
  title: string;
  message: string;
  type: string;
  actionUrl?: string;
  userId: string;
}

/**
 * Computes system alerts based on the current state and returns an array of alerts.
 * These are strictly derived rules.
 */
export function computeAlerts(state: AppState): SystemAlert[] {
  const alerts: SystemAlert[] = [];

  // Rule 1: Ad Budgets under 3 days
  const lowBudgets = state.adAccountBalances?.filter(a => a.daysRemaining <= 3) || [];
  for (const acc of lowBudgets) {
    alerts.push({
      userId: state.currentUserId, // Alert goes to everyone in ops for now
      title: `Low Ad Budget: ${acc.platform.toUpperCase()} (${acc.accountId})`,
      message: `Only ${acc.daysRemaining} days remaining (Balance: ₹${acc.balanceINR})`,
      type: 'warning',
      actionUrl: '/dashboard',
    });
  }

  // Rule 2: High CPL in Campaigns
  const highCPL = state.campaignWeeklyLogs?.filter(c => c.status === 'high') || [];
  for (const cmp of highCPL) {
    alerts.push({
      userId: state.currentUserId,
      title: `High CPL Alert: ${cmp.clientName}`,
      message: `CPL is ₹${cmp.cpl}, above target. Review campaign immediately.`,
      type: 'error',
      actionUrl: '/dashboard',
    });
  }

  // Rule 3: People not clocked in (after 10 AM)
  // Hardcoded for demo logic, assuming it's always after 10 AM.
  const notClocked = state.attendanceLogs?.filter(a => a.clockIn === null) || [];
  if (notClocked.length > 0) {
    alerts.push({
      userId: state.currentUserId,
      title: `Team Attendance Alert`,
      message: `${notClocked.length} members have not clocked in today.`,
      type: 'warning',
      actionUrl: '/team',
    });
  }

  // Rule 4: Overdue tasks
  const overdueTasks = state.tasks?.filter(t => {
    if (t.status === 'done' || t.status === 'cancelled' || !t.deadline) return false;
    const dl = new Date(t.deadline);
    dl.setHours(0,0,0,0);
    const today = new Date();
    today.setHours(0,0,0,0);
    return dl < today;
  }) || [];

  if (overdueTasks.length > 0) {
    alerts.push({
      userId: state.currentUserId,
      title: `Overdue Tasks`,
      message: `You have ${overdueTasks.length} overdue tasks in the system.`,
      type: 'error',
      actionUrl: '/tasks',
    });
  }

  return alerts;
}

export interface GoogleEvent {
  id: string;
  summary: string;
  description?: string;
  start: { dateTime: string; timeZone?: string };
  end: { dateTime: string; timeZone?: string };
  htmlLink?: string;
  attendees?: { email: string; responseStatus?: string }[];
  meetLink?: string;
}

export async function fetchGoogleCalendarEvents(accessToken: string, timeMin: string, timeMax: string): Promise<GoogleEvent[]> {
  // If no token or running in local dev without real keys, return mock data
  if (!accessToken || accessToken === 'mock_token') {
    return getMockEvents(timeMin);
  }

  try {
    const url = new URL('https://www.googleapis.com/calendar/v3/calendars/primary/events');
    url.searchParams.append('timeMin', timeMin);
    url.searchParams.append('timeMax', timeMax);
    url.searchParams.append('singleEvents', 'true');
    url.searchParams.append('orderBy', 'startTime');

    const res = await fetch(url.toString(), {
      headers: { Authorization: `Bearer ${accessToken}` }
    });

    if (!res.ok) {
      throw new Error('Failed to fetch Google Calendar events');
    }

    const data = await res.json();
    return data.items.map((item: any) => ({
      id: item.id,
      summary: item.summary,
      description: item.description,
      start: item.start,
      end: item.end,
      htmlLink: item.htmlLink,
      attendees: item.attendees,
      meetLink: item.hangoutLink
    }));
  } catch (error) {
    console.error('Error fetching calendar events:', error);
    return getMockEvents(timeMin); // Fallback to mock data on error
  }
}

function getMockEvents(baseDateIso: string): GoogleEvent[] {
  const base = new Date(baseDateIso);
  // Create an event for today
  const today = new Date();

  const m1Start = new Date(today);
  m1Start.setHours(10, 0, 0, 0);
  const m1End = new Date(today);
  m1End.setHours(11, 0, 0, 0);

  const m2Start = new Date(today);
  m2Start.setHours(14, 30, 0, 0);
  const m2End = new Date(today);
  m2End.setHours(15, 30, 0, 0);

  return [
    {
      id: 'mock-evt-1',
      summary: 'Weekly Sync with HAGGLE',
      description: 'Discuss Q3 marketing roadmap and deliverables.',
      start: { dateTime: m1Start.toISOString() },
      end: { dateTime: m1End.toISOString() },
      meetLink: 'https://meet.google.com/abc-defg-hij',
      attendees: [{ email: 'client@haggle.com' }, { email: 'sushil@invictus.com' }]
    },
    {
      id: 'mock-evt-2',
      summary: 'Internal Team Standup',
      start: { dateTime: m2Start.toISOString() },
      end: { dateTime: m2End.toISOString() },
      meetLink: 'https://meet.google.com/xyz-uvwx-qrs'
    }
  ];
}

